NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Ezekiel'

CHAPTERS = {
    1: {
        1: 'Kolmantenakymmenentenä vuotena, neljännessä kuussa, kuukauden viidentenä päivänä, kun minä olin karkotettujen joukossa Kebar-joen varrella, tapahtui, että taivaat aukenivat, ja näin Jumalan näkyjä.',
        2: 'Kuukauden viidentenä päivänä, kuningas Joojakinin karkotuksen viidentenä vuotena,',
        3: 'Jumalan sana tuli pappi Hesekielille, Buusin pojalle, Kaldean maassa Kebar-joen varrella, ja hänen päälleen tuli siellä Herran käsi.',
        4: 'Näin, ja katso: myrskytuuli tuli pohjoisesta, suuri pilvi ja leimahteleva tuli, ja pilveä ympäröi hohde, ja tulen keskeltä näkyi ikään kuin hehkuvaa malmia, keskeltä tulta.',
        5: 'Sen keskeltä näkyivät neljän olennon hahmot. Näöltään ne olivat tällaiset: niillä oli ihmisen hahmo.',
        6: 'Niillä oli kullakin neljät kasvot ja kullakin oli neljä siipeä.',
        7: 'Niiden sääret olivat suorat ja jalkaterät kuin vasikan sorkat, ja ne välkkyivät kuin kiiltävä vaski.',
        8: 'Siipiensä alla niillä oli, neljällä eri puolellaan, ihmiskädet. Kasvot ja siivet niillä neljällä olivat näin:',
        9: 'Niiden siivet koskettivat toisiaan. Kulkiessaan ne eivät kääntyneet. Ne kulkivat kukin suoraan eteenpäin.',
        10: 'Niiden kasvot olivat ihmiskasvojen kaltaiset. Mutta oikealla puolella niillä neljällä oli leijonankasvot, vasemmalla puolen niillä neljällä oli häränkasvot, myös niillä neljällä oli kotkankasvot.',
        11: 'Niin olivat niiden kasvot. Mutta siivet niillä oli levitettyinä ylöspäin. Kullakin oli kaksi, jotka koskettivat toisen siipiä, ja kaksi, joilla ne peittivät ruumistaan.',
        12: 'Ne kulkivat suoraan eteenpäin. Minne Henki vaati kulkemaan, sinne ne kulkivat. Kulkiessaan ne eivät kääntyneet.',
        13: 'Olentojen hahmo oli näöltään kuin tuliset hiilet, jotka paloivat tulisoihtujen näköisinä. Tulta liekehti olentojen välissä, ja tuli hohti, ja tulesta lähti salamoita.',
        14: 'Olennot kiitivät edestakaisin ja olivat nähdä kuin salaman leimaus.',
        15: 'Mutta kun katselin olentoja, niin katso: yksi pyörä oli maassa olentojen kohdalla, kunkin niiden neljän etupuolella.',
        16: 'Pyörät olivat näöltään ja teoltaan kuin krysoliittia, ja niillä neljällä oli sama muoto, ja ne olivat näöltään ja teoltaan, kuin olisi ollut sisäkkäin pyörä pyörässä.',
        17: 'Ne kulkivat neljään eri suuntaan, kun kulkivat. Kulkiessaan ne eivät kääntyneet.',
        18: 'Niiden kehät olivat korkeat ja pelottavat. Niiden kehät olivat täynnä silmiä, ympäriinsä niissä neljässä pyörässä.',
        19: 'Kun olennot kulkivat, pyörät kulkivat niiden mukana, ja kun olennot kohosivat ylös maasta, kohosivat pyörätkin.',
        20: 'Minne Henki meni, sinne ne kulkivat – minne vain Henki kulkemaan vaati. Pyörät kohosivat samalla kuin nekin, sillä olentojen henki oli pyörissä.',
        21: 'Kun olennot kulkivat, kulkivat nämäkin; kun ne seisoivat, seisoivat nämäkin. Kun ne kohosivat ylös maasta, kohosivat pyörät samalla kuin nekin, sillä olentojen henki oli pyörissä.',
        22: 'Olentojen päiden yläpuolelle hahmottui taivaanvahvuus kuin pelottava kristalli kaartuen ylös niiden päiden yli.',
        23: 'Taivaanvahvuuden alla niillä oli siivet suorina, toisen siipi toisen siipeä kohden. Kullakin oli kaksi, jotka sitä peittivät – kaksi, jotka peittivät sen ruumista.',
        24: 'Minä kuulin niiden siipien kohinan kuin paljojen vetten kohinan, kuin Kaikkivaltiaan äänen, kun ne kulkivat. Niiden ääni oli kuin sotaleirin ääni. Kun ne seisoivat, ne laskivat siipensä alas.',
        25: 'Kuului ääni ylhäältä taivaanvahvuudesta, joka oli niiden pään päällä. Kun ne seisoivat, ne laskivat siipensä alas.',
        26: 'Taivaanvahvuuden yläpuolella, joka oli niiden pään päällä, oli valtaistuimen muotoinen, näöltään kuin safiirikiveä. Valtaistuimen muotoisella istui hahmo, ihmisen näköinen, kohoten korkealle.',
        27: 'Näin ikään kuin hehkuvaa malmia, tulen näköistä, jota ympäröi kehä ylöspäin siitä, mikä näytti hänen lanteiltaan. Taas alaspäin siitä, mikä näytti hänen lanteiltaan, näin kuin tulen näköistä, ja sitä ympäröi hohde.',
        28: 'Kuin kaari, joka on pilvessä sadepäivänä, niin oli näöltään sitä ympäröivä hohde. Sellainen oli katsoa Herran kirkkauden hahmo. Kun sen näin, lankesin kasvoilleni. Kuulin äänen, kun joku puhui.',
    },
    2: {
        1: 'Hän sanoi minulle: "Ihmislapsi, nouse jaloillesi, puhun sinulle."',
        2: 'Minuun tuli Henki, kun hän puhui minulle, ja nosti minut jaloilleni, ja kuulin hänen puhuvan minulle.',
        3: 'Hän sanoi minulle: "Ihmislapsi, lähetän sinut israelilaisten luo, kapinallisten pakanoiden luo, jotka ovat kapinoineet minua vastaan. He ja heidän isänsä ovat luopuneet minusta, aina tähän päivään asti.',
        4: 'Nuo lapset, joilla on kovat kasvot ja paatuneet sydämet – niiden luo sinut lähetän, ja sinun on sanottava heille: Näin sanoo Herra, Herra.',
        5: 'Kuulkoot tai olkoot kuulematta – sillä uppiniskainen suku he ovat – he tulevat kuitenkin tietämään, että profeetta on ollut heidän keskellään.',
        6: 'Mutta sinä, ihmislapsi, älä pelkää heitä, äläkä pelkää heidän sanojaan, vaikka edessäsi on ohdakkeita ja orjantappuroita ja asut skorpionien seassa. Älä pelkää heidän sanojaan äläkä arkaile heidän kasvojaan, sillä he ovat kapinoiva suku.',
        7: 'Vaan puhu heille minun sanani, kuulkoot tai olkoot kuulematta, sillä kapinallisia he ovat.',
        8: 'Mutta sinä, ihmislapsi, kuule, mitä sinulle sanon. Älä ole kapinallinen, niin kuin kapinallinen suku on. Avaa suusi ja syö, mitä sinulle annan."',
        9: 'Näin, ja katso: käsi ojennettiin minua kohti, ja katso: siinä oli kirjakäärö.',
        10: 'Hän levitti sen eteeni, ja katso: se oli kirjoitettu täyteen sisältä ja päältä. Siihen oli kirjoitettu itkuvirret, huokaukset ja voi-huudot.',
    },
    3: {
        1: 'Sitten hän sanoi minulle: "Ihmislapsi, syö, minkä tästä löydät. Syö tämä kirjakäärö, mene ja puhu Israelin heimolle."',
        2: 'Avasin suuni, ja hän antoi tämän kirjakäärön minulle syötäväksi.',
        3: 'Hän sanoi minulle: "Ihmislapsi, ravitse vatsasi ja täytä itsesi tällä kirjakääröllä, jonka sinulle annan." Minä söin, ja se oli minun suussani makea kuin hunaja.',
        4: 'Hän sanoi minulle: "Ihmislapsi, mene nyt Israelin heimon luo ja puhu heille minun sanani.',
        5: 'Sillä sinua ei lähetetä outokielisen ja kankeapuheisen kansan luo, vaan Israelin heimon luo,',
        6: 'ei monien kansojen luo, outokielisten ja kankeapuheisten, joiden puhetta et ymmärrä. Jos niiden luo lähettäisin sinut, he sinua kuulisivat.',
        7: 'Mutta Israelin heimo ei tahdo sinua kuulla, koska he eivät tahdo kuulla minua. Sillä koko Israelin heimolla on kova otsa ja paatunut sydän.',
        8: 'Katso, teen kasvosi yhtä koviksi kuin heidän kasvonsa ja otsasi yhtä kovaksi kuin heidän otsansa.',
        9: 'Timantin kaltaiseksi, kiveä kovemmaksi teen otsasi. Älä pelkää heitä äläkä arkaile heidän kasvojaan, sillä he ovat kapinoiva suku."',
        10: 'Sitten hän sanoi minulle: "Ihmislapsi, kaikki sanani, jotka sinulle puhun, ota sydämeesi ja kuule korvillasi.',
        11: 'Mene ja saavu karkotettujen luo, kansasi lasten luo. Puhu heille ja sano heille: Näin sanoo Herra, Herra – kuulkoot he tai olkoot kuulematta."',
        12: 'Niin Henki nosti minut, ja minä kuulin takaani suuren, jylisevän äänen: "Kiitetty olkoon Herran kirkkaus, siinä missä se on!"',
        13: 'ja olentojen siipien äänen, kun ne löivät toisiinsa, samalla pyörien äänen ja suuren, jylisevän äänen.',
        14: 'Silloin Henki nosti minut ja otti minut, ja minä kuljin murheellisena henkeni kiivaudessa, ja Herran käsi oli väkevänä päälläni.',
        15: 'Tulin Tell-Aabibiin karkotettujen luo, jotka asuivat Kebar-joen varrella; ja siellä, missä he asuivat, istuin hämilläni heidän keskuudessaan seitsemän päivää.',
        16: 'Mutta seitsemän päivän kuluttua minulle tuli tämä Herran sana, ja se kuului:',
        17: '"Ihmislapsi, olen asettanut sinut Israelin heimolle vartijaksi. Kun kuulet sanan suustani, on sinun varoitettava heitä puolestani.',
        18: 'Jos sanon jumalattomalle: sinun on kuolemalla kuoltava, mutta sinä et häntä varoita etkä puhu varoittaaksesi jumalatonta hänen jumalattomasta tiestään, että pelastaisit hänen henkensä, niin jumalaton kuolee synnissään, mutta hänen verensä vaadin sinun kädestäsi.',
        19: 'Mutta jos sinä varoitat jumalatonta eikä hän käänny jumalattomuudestaan eikä jumalattomalta tieltään, niin hän kuolee synnissään, mutta sinä olet sielusi pelastanut.',
        20: 'Jos taas vanhurskas kääntyy pois vanhurskaudestaan ja tekee vääryyttä ja panen kompastuksen hänen eteensä, niin hän kuolee – kun et häntä varoittanut, niin hän kuolee synnissään, ja vanhurskautta, jota hän oli harjoittanut, ei muisteta – mutta hänen verensä vaadin sinun kädestäsi.',
        21: 'Mutta jos sinä varoitat vanhurskasta, ettei vanhurskas tekisi syntiä, eikä hän tee syntiä, niin hän totisesti on elävä, koska otti varoituksesta vaarin, ja sinä olet sielusi pelastanut."',
        22: 'Herran käsi tuli siellä minun päälleni, ja hän sanoi minulle: "Nouse ja mene laaksoon, niin puhun siellä sinulle."',
        23: 'Nousin ja menin laaksoon, ja katso, siellä seisoi Herran kirkkaus, samanlainen kuin se kirkkaus, jonka olin nähnyt Kebar-joen varrella. Lankesin kasvoilleni.',
        24: 'Mutta minuun tuli Henki ja nosti minut jaloilleni, ja hän puhui minulle ja sanoi minulle: "Mene, sulkeudu sisälle huoneeseesi.',
        25: 'Sinä, ihmislapsi! Katso, sinut pannaan köysiin ja sidotaan niillä, niin ettet voi mennä ulos heidän keskuuteensa.',
        26: 'Tartutan kielesi suusi lakeen, niin että mykistyt etkä voi olla heille nuhtelijana, sillä he ovat kapinallinen suku.',
        27: 'Mutta kun puhun sinulle, avaan suusi, ja sinun on sanottava heille: Näin sanoo Herra, Herra. Kuulkoon, joka kuulee, ja olkoon kuulematta, joka ei kuule, sillä he ovat kapinoiva suku."',
    },
    4: {
        1: '"Sinä ihmislapsi, ota tiili ja aseta se eteesi ja piirrä siihen kaupunki, Jerusalem.',
        2: 'Pane se piiritykseen, rakenna sitä vastaan saartovarusteet, luo sitä vastaan valli, aseta sitä vastaan sotaleirejä ja pane sitä ympäröimään muurinmurtajia.',
        3: 'Ota sitten rautainen leivinlevy ja aseta se rautamuuriksi itsesi ja kaupungin väliin ja suuntaa kasvosi kaupunkia kohti, niin että se tulee piiritykseen, ja piiritä sitä. Tämä on oleva merkki Israelin heimolle.',
        4: 'Pane sitten maata vasemmalle kyljellesi ja aseta sitä painamaan Israelin heimon syntivelka. Yhtä monta päivää, kuin sinä makaat sillä, sinä kannat heidän syntivelkaansa.',
        5: 'Minä panen sinulle saman luvun päiviä, kuin on heidän syntivelkansa vuosia: kolmesataa yhdeksänkymmentä päivää. Niin kannat Israelin heimon syntivelkaa.',
        6: 'Kun olet saanut ne päättymään, sinun on pantava maata toistamiseen, oikealle kyljellesi, ja kannettava Juudan heimon syntivelkaa neljäkymmentä päivää. Päivän kutakin vuotta kohden olen sinulle pannut.',
        7: 'Suuntaa kasvosi ja paljastettu käsivartesi piiritettyä Jerusalemia kohti ja profetoi sitä vastaan.',
        8: 'Katso, panen sinut köysiin, niin ettet voi kääntyä kyljeltä toiselle, kunnes piirityspäiväsi ovat päättyneet.',
        9: 'Ota myös itsellesi vehnää, ohria, papuja, linssiä, hirssiä ja spelttiä, pane ne samaan astiaan ja tee niistä itsellesi leipää. Yhtä monta päivää, kuin makaat kyljelläsi, kolmesataa yhdeksänkymmentä päivää, sinun tulee sitä syödä.',
        10: 'Ruoka, jota syöt, sinun tulee syödä painon mukaan: kaksikymmentä sekeliä päivässä. Sinun on syötävä se määräaikana.',
        11: 'Vettä sinun on juotava mitan mukaan: kuudennes hiin-mittaa sinun on juotava määräajoin.',
        12: 'Ohrarieskana sinun on se syötävä, ja ihmisen ulosteella sinun on se paistettava heidän silmiensä edessä."',
        13: 'Herra sanoi: "Näin tulevat israelilaiset syömään leipänsä saastaisena pakanoiden seassa, jonne heidät karkotan."',
        14: 'Mutta minä sanoin: "Voi Herra, Herra! Katso, milloinkaan sieluni ei ole ollut saastutettu. En ole syönyt itsestään kuollutta enkä kuoliaaksi raadeltua nuoruudestani tähän asti, eikä mitään saastaista lihaa ole tullut suuhuni."',
        15: 'Hän sanoi minulle: "Katso, annan sinulle eläimen lantaa ihmisen ulosteen sijaan. Valmista leipäsi sen päällä."',
        16: 'Hän sanoi minulle: "Ihmislapsi, katso, murran leivän tuen Jerusalemilta, ja he tulevat syömään leipää painon mukaan ja huolissaan sekä juomaan vettä mitan mukaan ja kauhuissaan,',
        17: 'niin että heillä on puute leivästä ja vedestä ja yhdessä he nääntyvät ja voipuvat syntivelkansa tähden."',
    },
    5: {
        1: '"Sinä, ihmislapsi, ota terävä miekka. Ota se partaveitseksesi, ja aja sillä hiuksesi ja partasi. Ota sitten vaaka ja jaa ne.',
        2: 'Polta kolmannes tulessa keskellä kaupunkia, sitten kun piirityspäivät ovat lopussa. Kolmannes ota ja lyö miekalla sen ympärillä. Kolmannes hajota tuuleen, ja minä ajan niitä takaa paljastetulla miekalla.',
        3: 'Ota sitten niitä pieni määrä ja sido ne helmaasi,',
        4: 'ja ota niitä vielä, heitä ne tuleen ja polta ne tulessa. Siitä lähtee tuli koko Israelin heimoon.',
        5: 'Näin sanoo Herra, Herra: Tämä on Jerusalem. Pakanoiden keskelle olen sen asettanut ja niiden maat sen ympärille.',
        6: 'Mutta se on kapinoinut minun oikeuksiani vastaan jumalattomammin kuin pakanat ja minun käskyjäni vastaan jumalattomammin kuin ne maat, jotka ovat sen ympärillä. Sillä oikeuksiani he ovat pitäneet halpoina eivätkä ole vaeltaneet säädöksieni mukaan.',
        7: 'Sen tähden, näin sanoo Herra, Herra: Koska teidän napinanne on ollut pahempi kuin pakanoiden, jotka ovat ympärillänne, ja koska te ette ole vaeltaneet käskyjeni mukaan, ette ole noudattaneet oikeuksiani ettekä ole tehneet niiden pakanoidenkaan oikeuksien mukaan, jotka ympärillänne ovat,',
        8: 'sen tähden, näin sanoo Herra, Herra: Katso, minäkin käyn sinun kimppuusi ja toteutan tuomiot keskelläsi pakanoiden silmien edessä',
        9: 'ja teen sinulle kaikkien kauhistustesi tähden, mitä en ole vielä ennen tehnyt ja millaista en ole vastakaan tekevä.',
        10: 'Sen tähden isät tulevat keskelläsi syömään lapsiaan, ja lapset tulevat syömään isiään, ja minä toteutan sinussa tuomiot ja hajotan jäännöksesi kaikkiin tuuliin.',
        11: 'Sen tähden, niin totta kuin minä elän, sanoo Herra, Herra: Totisesti, koska olet saastuttanut pyhäkköni kaikilla iljetyksilläsi ja kaikilla kauhistuksillasi, minäkin käännyn pois, en sääli enkä armahda.',
        12: 'Kolmannes sinusta kuolee ruttoon ja nääntyy nälkään keskelläsi. Kolmannes kaatuu miekkaan ympärilläsi. Kolmanneksen hajotan kaikkiin tuuliin, ja ajan niitä takaa paljastetulla miekalla.',
        13: 'Minun vihani täyttyy, ja tyydytän kiivauteni heissä ja kostan. He tulevat tietämään, että minä, Herra, olen puhunut kiivaudessani, kun toteutan heissä vihani.',
        14: 'Teen sinut raunioksi ja häväistyksi jokaisen ohikulkijan silmissä pakanoiden keskuudessa, jotka ovat ympärilläsi.',
        15: 'Se on oleva häväistys ja herjaus, varoitus ja pelästys pakanoiden joukossa, jotka ovat ympärilläsi, kun toteutan sinussa tuomiot vihassa ja kiivaudessa ja kovin rangaistuksin – minä, Herra, olen puhunut –',
        16: 'kun lähetän heidän kimppuunsa nälän pahat nuolet, joista tulee tuhooja ja jotka lähetän teitä tuhoamaan. Lisään teille nälkää ja murran teiltä leivän tuen.',
        17: 'Lähetän kimppuunne nälän ja pahat petoeläimet, jotka riistävät sinulta lapset. Rutto ja veri käyvät päällesi, ja annan miekan tulla kimppuusi. Minä, Herra, olen puhunut."',
    },
    6: {
        1: 'Minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Ihmislapsi, käännä kasvosi Israelin vuoria kohti ja profetoi niitä vastaan',
        3: 'ja sano: Israelin vuoret, kuulkaa Herran, Herran sana. Näin sanoo Herra, Herra vuorille ja kukkuloille, puroille ja laaksoille: Katso, minä annan miekan tulla päällenne ja hävitän uhrikukkulanne.',
        4: 'Alttarinne jäävät autioiksi, auringonpatsaanne murskataan, ja surmattujenne annan kaatua epäjumalienne eteen.',
        5: 'Panen israelilaisten ruumiit heidän epäjumaliensa eteen ja hajotan heidän luunsa heidän alttariensa ympärille.',
        6: 'Kaikilla asuinpaikoillanne tulevat kaupungit raunioiksi ja uhrikukkulat autioiksi. Alttarinne jäävät raunioiksi ja autioiksi, epäjumalanne murskataan ja hävitetään, auringonpatsaanne särjetään, ja aikaansaannoksenne pyyhkäistään pois,',
        7: 'surmattuja kaatuu keskellänne, ja te tulette tietämään, että minä olen Herra.',
        8: 'Mutta jätän jäännöksen: teillä on oleva miekasta pelastuneita pakanoiden joukossa, kun teidät hajotetaan niiden maihin.',
        9: 'Silloin ne teistä, jotka pelastuvat, muistavat minut pakanoiden seassa, mihin heidät on viety vangeiksi. Särjen heidän haureellisen sydämensä, joka poikkesi minusta pois, ja heidän silmänsä, jotka haureellisina kulkivat heidän epäjumaliensa perässä. Heitä etoo oma itsensä pahojen tekojen tähden, joita he ovat tehneet, kaikkien heidän kauhistustensa tähden.',
        10: 'Silloin he tulevat tietämään, että minä olen Herra. En ole sanonut turhaan tuottavani teille tätä onnettomuutta.',
        11: "Näin sanoo Herra, Herra: lyö käsiäsi yhteen, polje jalkaasi ja sano: 'Voi!' kaikille Israelin heimon pahoille kauhistuksille, heidän, jotka kaatuvat miekkaan, nälkään ja ruttoon.",
        12: 'Kaukainen kuolee ruttoon, läheinen kaatuu miekkaan, jäljelle jäänyt ja säilynyt kuolee nälkään, ja panen vihani täytäntöön heissä.',
        13: 'Tulette tietämään, että minä olen Herra, kun heitä on surmattuina heidän epäjumaliensa keskellä, heidän alttariensa ympärillä, jokaisella korkealla kukkulalla, kaikilla vuorten huipuilla, jokaisen vihreän puun alla ja jokaisen tuuhean tammen alla, missä paikassa vain he ovat tarjonneet suloista tuoksua kaikille epäjumalilleen.',
        14: 'Ojennan käteni heitä vastaan ja teen maan autiommaksi ja hävitetymmäksi, kuin on Diblatan erämaa, kaikilla heidän asuinpaikoillaan, ja he tulevat tietämään, että minä olen Herra."',
    },
    7: {
        1: 'Minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Sinä, ihmislapsi, näin sanoo Herra, Herra Israelin maalle: Loppu! Tämän maan neljälle äärelle tulee loppu.',
        3: 'Nyt tulee sinulle loppu, ja lähetän vihani sinua vastaan, tuomitsen sinut vaelluksesi mukaan ja annan kaikkien kauhistustesi kohdata sinua.',
        4: 'En sääli sinua enkä armahda, vaan annan vaelluksesi kohdata sinua, ja kauhistuksesi tulevat keskuuteesi, ja tulette tietämään, että olen Herra.',
        5: 'Näin sanoo Herra, Herra: Onnettomuus! Yksi ja ainoa onnettomuus! Katso, se tulee!',
        6: 'Loppu tulee, tulee loppu! Se herää sinua vastaan! Katso, se tulee!',
        7: 'Vuoro tulee sinulle, maan asuja. Aika tulee, päivä on lähellä. On hämminki, ilohuutoa ei kaiu vuorilta.',
        8: 'Nyt kohta vuodatan kiivauteni päällesi, panen vihani täytäntöön sinussa, tuomitsen sinut vaelluksesi mukaan ja annan kaikkien kauhistustesi kohdata sinua.',
        9: 'En sääli enkä armahda. Annan vaelluksesi kohdata sinua, ja kauhistuksesi tulevat keskellesi, ja te tulette tietämään, että minä, Herra, olen se, joka lyön.',
        10: 'Katso, päivä! Katso, se tulee! Vuoro on tullut, ruoska kukkii ja julkeus versoo.',
        11: 'Väkivalta on noussut ruoskaksi jumalattomuudelle. Heistä ei jää mitään, ei heidän pauhaavasta joukostaan eikä heidän melustaan. Poissa on heidän pöyhkeytensä.',
        12: 'Tullut on aika, joutunut päivä, älköön ostaja iloitko, älköönkä myyjä murehtiko, sillä viha tulee kaiken siellä pauhaavan joukon päälle.',
        13: 'Sillä myyjä ei enää palaa myymään tavaroitaan, vaikka he vielä jäisivätkin henkiin. Sillä näky kaikkea sen pauhaavaa joukkoa vastaan ei peräydy, eikä kukaan synnillään vahvista elämäänsä.',
        14: 'Puhalletaan torviin, varustetaan kaikki, mutta ei ole lähtijää sotaan, sillä minun vihani tulee kaiken siellä pauhaavan joukon päälle.',
        15: 'Miekka on ulkona, sisällä rutto ja nälkä. Kedolla oleva kuolee miekkaan, kaupungissa olevan syö nälkä ja rutto.',
        16: 'Mutta jos heitä joitakin pelastuu ja pääsee pakoon, he ovat vuorilla kuin laaksojen kyyhkyset, ja he vaikertavat kaikki, kukin syntiään.',
        17: 'Kaikki kädet voipuvat, kaikki polvet käyvät veltoiksi kuin vesi.',
        18: 'He kääriytyvät säkkeihin, heidät peittää vavistus, kaikilla kasvoilla on häpeä, ja kaikki päät ovat paljaiksi ajetut.',
        19: 'Hopeansa he heittävät kaduille, ja heidän kultansa tulee heille saastaksi. Heidän kultansa ja hopeansa eivät voi heitä pelastaa Herran vihan päivänä. He eivät sillä tyydytä nälkäänsä eivätkä täytä vatsaansa, sillä siitä tuli heille kompastus syntiin.',
        20: 'Korujen loistolla he ylpeilivät ja tekivät siitä kauhistavat kuvansa ja iljetyksensä. Sen tähden teen sen heille saastaksi.',
        21: 'Annan sen vieraitten käsiin ryöstettäväksi ja maan jumalattomien saaliiksi, ja he häpäisevät sen.',
        22: 'Käännän kasvoni heistä pois, niin että minun aarteeni häväistään. Väkivaltaiset menevät sinne ja häpäisevät sen.',
        23: 'Valmista kahle, sillä maa on täynnä verivelkojen tuomiota, ja kaupunki on täynnä väkivaltaa.',
        24: 'Tuon pakanoista pahimmat, ja he ottavat talonne omikseen. Teen lopun voimallisten ylpeydestä, ja heidän pyhäkkönsä häväistään.',
        25: 'Tulee hätä, ja he etsivät pelastusta, mutta sitä ei ole.',
        26: 'Häviö tulee häviön jälkeen, sanoma tulee sanoman jälkeen. He havittelevat näkyä profeetalta. Papilta katoaa opetus ja vanhimmilta neuvo.',
        27: 'Kuningas murehtii, päämies pukeutuu kauhuun, ja maan kansan kädet vapisevat. Teen heille heidän teittensä mukaan, ja tuomitsen heidät heidän tuomioittensa mukaan, ja he tulevat tietämään, että minä olen Herra."',
    },
    8: {
        1: 'Kuudentena vuotena, kuudennessa kuussa, kuukauden viidentenä päivänä istuin huoneessani, ja Juudan vanhimmat istuivat edessäni, ja Herran, Herran käsi laskeutui siellä päälleni.',
        2: 'Näin, ja katso: tulennäköinen hahmo! Alaspäin siitä, mikä näytti sen lanteilta, oli tulta, ja ylöspäin sen lanteista näkyi loiste, joka oli nähdä kuin hehkuva malmi.',
        3: 'Hän ojensi ikään kuin käden ja tarttui minuun pääni hiussuortuvasta, ja Henki nosti minut maan ja taivaan välille ja vei minut Jerusalemiin Jumalan näyissä, sisimmän portin ovelle, joka on pohjoista kohden, sinne missä oli kiivauspatsas, joka oli herättänyt Herran kiivauden.',
        4: 'Katso, siellä oli Israelin Jumalan kirkkaus, samanlainen nähdä kuin se, minkä olin nähnyt laaksossa.',
        5: 'Hän sanoi minulle: "Ihmislapsi, nosta silmäsi pohjoista kohti." Nostin silmäni pohjoista kohti, ja katso: pohjoiseen päin alttarin portista oli tuo kiivauspatsas sisäänkäytävässä.',
        6: 'Hän sanoi minulle: "Ihmislapsi, näetkö sinä, mitä he tekevät – suuria kauhistuksia, joita Israelin heimo tekee täällä, että menisin kauas pois pyhäköstäni? Mutta palaa vielä ja näet vielä suurempia kauhistuksia."',
        7: 'Sitten hän vei minut esipihan ovelle, ja näin, ja katso: seinässä oli jokin aukko.',
        8: 'Hän sanoi minulle: "Ihmislapsi, murtaudu läpi seinän."',
        9: 'Murtauduin seinän läpi, ja katso: jokin ovi! Hän sanoi minulle: "Mene ja katso hirveitä kauhistuksia, joita he täällä tekevät."',
        10: 'Menin ja näin, ja katso: kaikenlaisia inhottavia matelijoiden ja karjaeläinten kuvia ja kaikenlaisia Israelin heimon epäjumalia oli piirretty seinään ympäri kaikkialle.',
        11: 'Niiden edessä seisoi seitsemänkymmentä miestä, Israelin heimon vanhimpia, ja näiden keskellä seisoi Jaasanja, Saafanin poika. Kullakin heillä oli suitsutusastiansa kädessään, ja suitsutuspilvestä nousi tuoksu.',
        12: 'Hän sanoi minulle: "Näetkö, ihmislapsi, mitä Israelin heimon vanhimmat tekevät pimeässä, itse kukin kuvakammiossaan? Sillä he sanovat:',
        13: '\' Herra ei meitä näe: Herra on hylännyt tämän maan.\'" Hän sanoi minulle: "Tulet näkemään vielä suurempia kauhistuksia, joita he tekevät."',
        14: 'Hän vei minut Herran huoneen portin ovelle, joka on pohjoista kohden, ja katso, siellä istui naisia itkemässä Tammusta.',
        15: 'Sitten hän sanoi minulle: "Näetkö, ihmislapsi? Tulet näkemään vielä kauhistuksia, suurempia kuin nämä."',
        16: 'Sitten hän vei minut Herran huoneen sisemmälle esipihalle, ja katso: Herran temppelin ovella, eteisen ja alttarin välillä, oli noin kaksikymmentä viisi miestä. Heillä oli selät Herran temppeliin päin ja kasvot itään päin, ja he kumarsivat aurinkoa kohti itää.',
        17: 'Hän sanoi minulle: "Näitkö, ihmislapsi? Eikö ole Juudan heimolle kylliksi, että he tekevät kauhistuksia, joita he ovat täällä tehneet, koska he täyttävät maan väkivallalla ja aina uudelleen vihoittavat minut? Katso, kuinka he vievät viiniköynnöksen lehvää nenänsä eteen!',
        18: 'Mutta minäkin teen, minkä teen, vihassani: en sääli enkä armahda; ja vaikka he huutavat korviini suurella äänellä, en heitä kuule."',
    },
    9: {
        1: 'Sitten hän huusi suurella äänellä korviini ja sanoi: "Tulkaa, kaupungin rankaisijat, ja olkoon kullakin kädessään tuhoaseensa!"',
        2: 'Katso, kuusi miestä tuli Yläportilta päin, joka on pohjoista kohden, ja kullakin oli kädessä tuhoaseensa. Mutta yksi mies oli heidän keskellään, puettu pellavavaatteisiin ja vyötäisillään kirjoitustarvikkeet. He tulivat ja asettuivat seisomaan vaskialttarin ääreen.',
        3: 'Mutta Israelin Jumalan kirkkaus oli kohonnut kerubin yläpuolelta, jonka yllä se oli ollut, huoneen kynnykselle ja huusi pellavavaatteisiin puetulle miehelle, jolla oli kirjoitustarvikkeet vyötäisillään.',
        4: 'Herra sanoi hänelle: "Kierrä kaupungin, Jerusalemin, läpi ja tee merkki niiden miesten otsiin, jotka huokaavat ja valittavat kaikkia kauhistuksia, mitä sen keskuudessa tehdään."',
        5: 'Niille toisille hän sanoi kuulteni: "Kiertäkää kaupungin läpi hänen jäljessään ja surmatkaa. Älkää säälikö, älkää armahtako,',
        6: 'tappakaa vanhukset, nuorukaiset, neitsyet, lapset ja vaimot, mutta älkää koskeko kehenkään, jolla on otsassaan merkki, ja aloittakaa pyhäköstäni." He aloittivat niistä miehistä, vanhimmista, jotka olivat temppelin edessä.',
        7: 'Hän sanoi heille: "Saastuttakaa temppeli ja täyttäkää esipihat surmatuilla. Menkää!" Ja he menivät ja surmasivat kaupungissa.',
        8: 'Mutta kun minä heidän surmatessaan olin jäänyt jäljelle, lankesin kasvoilleni, huusin ja sanoin: "Voi Herra, Herra! Hävitätkö sinä Israelin koko jäännöksen, kun vuodatat vihasi Jerusalemin päälle?"',
        9: 'Hän sanoi minulle: "Israelin ja Juudan heimon syntivelka on erityisen suuri. Maa on täynnä verivelkoja, ja kaupunki on täynnä oikeuden vääristelyä, sillä he sanovat: \' Herra on hylännyt tämän maan, ei Herra näe.\'',
        10: 'Niinpä minäkään en sääli enkä armahda. Annan heidän vaelluksensa tulla heidän oman päänsä päälle."',
        11: 'Katso, pellavavaatteisiin puettu mies, jolla oli kirjoitustarvikkeet vyötäisillään, toi tämän sanan: "Olen tehnyt kaiken, kuten käskit minun tehdä."',
    },
    10: {
        1: 'Näin, ja katso: taivaanvahvuuden yläpuolella, joka oli kerubien pään päällä, oli ikään kuin safiirikivi, näöltään valtaistuimen kaltainen. Se näkyi heidän yläpuolellaan.',
        2: 'Hän sanoi pellavavaatteisiin puetulle miehelle näin: "Mene rattaiden väliin, kerubin alle ja täytä kourasi tulisilla hiilillä kerubien välistä ja sirottele ne yli kaupungin." Niin hän meni silmieni edessä.',
        3: 'Kerubit seisoivat temppelin oikealla puolella, kun mies meni, ja pilvi peitti sisemmän esipihan.',
        4: 'Silloin Herran kirkkaus kohosi kerubin yltä temppelin kynnykselle, ja pilvi täytti temppelin, ja esipiha tuli täyteen Herran kirkkauden hohdetta.',
        5: 'Kerubien siipien kohina kuului uloimpaan esipihaan asti kuin kaikkivaltiaan Jumalan ääni, kun hän puhuu.',
        6: 'Kun hän käski pellavavaatteisiin puettua miestä sanoen: "Ota tulta rattaiden välistä, kerubien välistä", tämä meni ja seisahtui pyörän ääreen.',
        7: 'Kerubi ojensi kätensä kerubien välitse tuleen, joka oli kerubien välissä, otti sitä ja antoi pellavavaatteisiin puetun kouraan. Tämä otti sen ja meni ulos.',
        8: 'Kerubeilla näkyi ikään kuin ihmiskäsi heidän siipiensä alta.',
        9: 'Näin, ja katso: kerubien kohdalla oli neljä pyörää, yksi pyörä aina yhden kerubin vierellä, ja pyörät olivat näöltään kuin krysoliittikivi.',
        10: 'Niillä neljällä näytti olevan sama muoto, niin kuin olisi ollut pyörä pyörässä.',
        11: 'Ne kulkivat neljään eri suuntaan, kun kulkivat. Kulkiessaan ne eivät kääntyneet, sillä minne ensimmäinen meni, sinne ne kulkivat sen jäljessä. Ne eivät kääntyneet kulkiessaan.',
        12: 'Niillä oli koko ruumis ja selät ja kädet ja siivet ja pyörät, kaikki neljä pyörää, täynnä silmiä, ympäriinsä.',
        13: 'Niillä neljällä oli pyöränsä; ja pyöriä nimitettiin minun kuulteni "rattaiksi".',
        14: 'Kullakin oli neljät kasvot: yhdet kerubinkasvot, toiset ihmiskasvot, kolmannet leijonankasvot ja neljännet kotkankasvot.',
        15: 'Kerubit kohosivat – ne olivat samat olennot, jotka olin nähnyt Kebar-joen varrella. –',
        16: 'Kun kerubit kulkivat, kulkivat pyörät niiden lähellä, ja kun kerubit nostivat siipensä kohotakseen ylös maasta, eivät myöskään pyörät kääntyneet pois niiden läheltä.',
        17: 'Kun ne seisahtuivat, seisahtuivat nämäkin, ja kun ne kohosivat, kohosivat nämä niiden kanssa, sillä olentojen henki oli näissä.',
        18: 'Sitten Herran kirkkaus lähti temppelin kynnykseltä ja asettui kerubien ylle.',
        19: 'Lähtiessään kerubit nostivat siipensä ja kohosivat maasta silmieni edessä, ja pyörät samalla kuin ne. Ne seisahtuivat Herran huoneen itäportin ovelle, ja niiden yläpuolella oli Israelin Jumalan kirkkaus.',
        20: 'Nämä olivat samat olennot, jotka olin nähnyt Israelin Jumalan alla Kebar-joen varrella, ja tulin tietämään, että ne olivat kerubeja.',
        21: 'Neljät kasvot oli kullakin ja neljä siipeä kullakin, ja niiden siipien alla oli ikään kuin ihmiskädet.',
        22: 'Niiden kasvot olivat ulkomuodoltaan samat, jotka olin nähnyt Kebar-joen varrella – sekä ulkonäön puolesta että itsessään. Ne kulkivat kukin suoraan eteenpäin.',
    },
    11: {
        1: 'Henki nosti minut ja vei minut Herran huoneen itäportille, joka on itään päin. Katso: portin ovella oli kaksikymmentä viisi miestä, ja minä näin niiden keskellä Jaasanjan, Assurin pojan, ja Pelatjan, Benajan pojan, kansan ruhtinaat.',
        2: 'Hän sanoi minulle: "Ihmislapsi, nämä miehet miettivät turmiota ja pitävät pahaa neuvoa tätä kaupunkia vastaan.',
        3: "He sanovat: 'Ei nyt kohta tule rakentaa taloja: se on pata, me olemme liha.'",
        4: 'Sen tähden profetoi heitä vastaan, profetoi, ihmislapsi."',
        5: 'Herran Henki laskeutui päälleni ja sanoi minulle: "Sano: Näin sanoo Herra: Näin te, Israelin heimo, sanotte, ja minä tunnen, mitä teidän hengestänne nousee.',
        6: 'Paljon on teidän surmaamianne tässä kaupungissa, ja olette täyttäneet sen kadut surmatuilla.',
        7: 'Sen tähden, näin sanoo Herra, Herra: Surmattunne, jotka olette heittäneet sen keskelle, ovat liha, ja tämä kaupunki on pata, mutta teidät vien pois sen keskeltä.',
        8: 'Miekkaa pelkäätte, mutta miekan annan tulla päällenne, sanoo Herra, Herra.',
        9: 'Vien teidät pois sen keskeltä ja annan teidät muukalaisten käsiin ja toteutan teidän keskellänne tuomiot.',
        10: 'Te kaadutte miekkaan. Israelin rajalla teidät tuomitsen. Tulette tietämään, että minä olen Herra.',
        11: 'Ei tämä tule teille padaksi ettekä te siihen lihaksi: Israelin rajalla tuomitsen teidät.',
        12: 'Te tulette tietämään, että minä olen Herra – te, jotka ette ole vaeltaneet käskyjeni mukaan ettekä ole tehneet oikeuksieni mukaan, vaan olette tehneet niiden pakanoiden oikeuksien mukaan, jotka ovat teidän ympärillänne."',
        13: 'Kun profetoin, niin Pelatja, Benajan poika, kuoli. Lankesin kasvoilleni, huusin kovalla äänellä ja sanoin: "Voi Herra, Herra! Aivanko sinä teet lopun Israelin jäännöksestä?"',
        14: 'Minulle tuli tämä Herran sana:',
        15: '"Ihmislapsi, sinun veljesi, sinun veljesi, sukulaisesi ja koko Israelin heimo, kaikki, joille Jerusalemin asukkaat sanovat: \'Olkaa vain kaukana Herrasta, meille tämä maa on annettu perinnöksi!\'',
        16: 'Sano sen tähden: Näin sanoo Herra, Herra: Koska olen vienyt heidät kauas pakanoiden sekaan ja hajottanut heidät muihin maihin, ja olen ollut heille pyhäkkönä vähän aikaa niissä maissa, joihin he ovat joutuneet,',
        17: 'sano sen tähden: Näin sanoo Herra, Herra: Kokoan teidät kansakuntien seasta ja kerään teidät maista, joihin teidät on hajotettu, ja annan teille Israelin maan.',
        18: 'He tulevat sinne ja poistavat siitä kaikki sen iljetykset ja kaikki sen kauhistukset.',
        19: 'Annan heille yhden sydämen, ja uuden hengen annan teidän sisimpäänne, ja poistan kivisydämen heidän ruumiistaan ja annan heille lihasydämen,',
        20: 'niin että he vaeltavat säädöksieni mukaan ja noudattavat oikeuksiani ja pitävät ne. He ovat minun kansani, ja minä olen heidän Jumalansa.',
        21: 'Mutta joiden sydän vaeltaa heidän iljetystensä ja kauhistustensa mieltä myöten, niiden vaelluksen annan tulla heidän päänsä päälle, sanoo Herra, Herra."',
        22: 'Kerubit nostivat siipensä ja pyörät samalla kuin ne, ja Israelin Jumalan kirkkaus oli heidän yläpuolellaan,',
        23: 'ja Herran kirkkaus kohosi ylös, pois kaupungin keskeltä, ja asettui vuorelle, joka on kaupungista itään.',
        24: 'Mutta Henki nosti ja vei minut Kaldeaan karkotettujen luo näyssä Jumalan Hengen voimalla. Näky, jonka olin nähnyt, katosi minulta.',
        25: 'Puhuin karkotetuille kaikki Herran sanat, jotka hän oli minulle näyttänyt.',
    },
    12: {
        1: 'Minulle tuli tämä Herran sana ja se kuului:',
        2: '"Ihmislapsi, sinä asut kapinallisen suvun keskellä, niiden, joilla on silmät nähdä, mutta eivät näe, ja korvat kuulla, mutta eivät kuule, sillä he ovat kapinallinen suku.',
        3: 'Sinä, ihmislapsi, tee itsellesi varusteet mennäksesi karkotukseen, mutta mene päiväaikaan heidän silmiensä edessä karkotukseen. Sinun on mentävä karkotukseen omalta paikkakunnaltasi toiselle paikkakunnalle heidän silmiensä edessä. Ehkäpä he näkevät sen, sillä he ovat kapinallinen suku.',
        4: 'Vie ulos varusteesi, niin kuin karkotetut varusteensa, päiväaikaan heidän silmiensä edessä. Mutta lähde sinä itse illalla heidän silmiensä edessä, niin kuin karkotetut lähtevät.',
        5: 'Murtaudu muurin läpi heidän silmiensä edessä ja vie varusteesi siitä ulos.',
        6: 'Nosta ne hartioillesi heidän silmiensä edessä ja vie ulos pilkkopimeässä. Peitä kasvosi, niin ettet näe maata. Sillä ennusmerkiksi olen pannut sinut Israelin heimolle."',
        7: 'Tein, kuten minua oli käsketty ja vein ulos päiväaikaan varusteeni, niin kuin karkotetut varusteensa, mutta illalla murtauduin käsin muurin läpi. Pilkkopimeässä ne vein ulos ja nostin ne hartioilleni heidän silmiensä edessä.',
        8: 'Mutta aamulla minulle tuli tämä Herran sana, ja se kuului:',
        9: '"Ihmislapsi, eikö Israelin heimo, kapinallinen suku, ole sinulle sanonut: \'Mitä sinä teet?\'',
        10: 'Sano heille: Näin sanoo Herra, Herra: Ruhtinasta, joka on Jerusalemissa, koskee tämä profeettasana ja koko Israelin heimoa, mikä on heidän keskuudessaan.',
        11: 'Sano: Minä olen teille ennusmerkki. Kuten tein, niin heille tehdään. Karkotukseen, vankeuteen he menevät.',
        12: 'Ruhtinas, joka on heidän keskellään, nostaa kantamuksensa hartioilleen ja lähtee ulos pilkkopimeässä. Muurista he murtautuvat läpi viedäkseen siitä ulos vietävänsä. Kasvonsa hän peittää, koska hän ei ole silmillään näkevä maata.',
        13: 'Levitän verkkoni hänen ylitseen, ja hän tarttuu pyydykseeni. Vien hänet Baabeliin, kaldealaisten maahan, mutta sitä hän ei saa nähdä, ja sinne hän kuolee.',
        14: 'Kaikki, keitä hänellä on ympärillään apunaan, ja kaikki hänen sotajoukkonsa hajotan kaikkiin tuuliin, ja minä ajan niitä takaa paljastetulla miekalla.',
        15: 'He tulevat tietämään, että minä olen Herra, kun hajotan heidät pakanoiden sekaan ja sirotan heidät heidän maihinsa.',
        16: 'Mutta minä jätän heitä jonkin määrän miekasta, nälästä ja rutosta jäljelle kertomaan pakanoiden seassa, siellä, minne he tulevat, kaikista kauhistuksistaan. He tulevat tietämään, että minä olen Herra."',
        17: 'Sitten minulle tuli tämä Herran sana:',
        18: '"Ihmislapsi, syö leipäsi vavisten ja juo vetesi täristen ja huolestuneena.',
        19: 'Sano maan kansalle: Näin sanoo Herra, Herra Jerusalemin asukkaista Israelin maassa: He tulevat syömään leipänsä huolestuneina ja juomaan vetensä kauhun vallassa, ja sen maa tulee autioksi kaikesta, mitä siinä on, kaikkien siinä asuvien väkivallan tähden.',
        20: 'Asutut kaupungit tulevat raunioiksi, ja maa tulee autioksi, ja te tulette tietämään, että minä olen Herra."',
        21: 'Minulle tuli tämä Herran sana ja se kuului:',
        22: '"Ihmislapsi, miksi teillä on tämä sananparsi Israelin maasta, kun sanotte: \'Aika venyy pitkälle, ja tyhjiin raukeavat kaikki näyt?\'',
        23: 'Sen tähden sano heille: Näin sanoo Herra, Herra: Minä teen lopun tästä sananparresta, niin ettei sitä enää lausuta Israelissa, vaan sano heille: Lähellä on aika ja kaikkien näkyjen täyttymys.',
        24: 'Sillä ei ole oleva enää petollista näkyä eikä mielistelevää ennustelua Israelin heimon keskuudessa.',
        25: 'Sillä minä, Herra, minä puhun; ja minkä sanan puhun, se tapahtuu eikä enää viivy. Sillä teidän päivinänne, kapinallinen suku, sanan puhun ja sen myös täytän, sanoo Herra, Herra."',
        26: 'Minulle tuli tämä Herran sana:',
        27: '"Ihmislapsi, katso, Israelin heimo sanoo: \'Niihin näkyihin, joita tämä näkee, on paljon päiviä, ja hän profetoi kaukaisista ajoista.\'',
        28: 'Sen tähden sano heille: Näin sanoo Herra, Herra: Ei viivy enää yksikään minun sanani: Minkä sanan minä puhun, se tapahtuu, sanoo Herra, Herra."',
    },
    13: {
        1: 'Minulle tuli tämä Herran sana ja se kuului:',
        2: '"Ihmislapsi, profetoi Israelin ennustavista profeetoista ja sano noille, jotka ovat profeettoja oman sydämensä johtamina: Kuulkaa Herran sana.',
        3: 'Näin sanoo Herra, Herra: voi profeettatyperyksiä, jotka seuraavat omaa henkeään ja sitä, mitä eivät ole nähneet!',
        4: 'Kuin ketut raunioissa ovat profeettasi, Israel.',
        5: 'Te ette ole nousseet muurin aukkoihin ettekä korjanneet muuria Israelin heimon ympäriltä, että se kestäisi sodassa, Herran päivänä.',
        6: "Se, mitä he ovat nähneet, on petosta, ja heidän ennustelunsa on valhetta, kun he sanovat: 'Näin sanoo Herra ', vaikka Herra ei ole heitä lähettänyt, niin he odottavat, että hän toteuttaisi heidän sanansa.",
        7: "Ettekö ole petollisia näkyjä nähneet ja valheellisia ennusteluja puhuneet, kun olette sanoneet: 'Näin sanoo Herra ', vaikka minä en ole puhunut?",
        8: 'Sen tähden, näin sanoo Herra, Herra: Koska olette puhuneet petosta ja nähneet valheellisia näkyjä, niin sen tähden, katso, minä olen teitä vastaan, sanoo Herra, Herra.',
        9: 'Käteni on profeettoja vastaan, jotka näkevät petosnäkyjä ja ennustavat valhetta. Heidän ei pidä olla kansani kokouksessa eikä heitä pidä kirjoittaa Israelin heimon kirjaan, eivätkä he tule Israelin maahan. Te tulette tietämään, että minä olen Herra, Herra.',
        10: "Koska he, koska he vievät kansani harhaan, sanoen: 'rauha!', vaikka ei rauhaa ole, ja katso, koska he, kun kansa rakentaa seinän, valkaisevat sen kalkilla,",
        11: 'niin sano noille kalkilla valkaisijoille, että se kaatuu. Tulee kaatosade, tulee suuria rakeita, jotka sen kaatavat, ja myrskynpuuska hajottaa sen,',
        12: "ja katso, seinä kaatuu! Eikö silloin teiltä kysytä: 'Missä on valkaisu, jolla sen valkaisitte?'",
        13: 'Sen tähden, näin sanoo Herra, Herra: Annan kiivaudessani puhjeta myrskynpuuskan, kaatosade tulee vihastani ja raekivet kiivaudestani tekemään siitä lopun.',
        14: 'Hajotan seinän, jonka olitte kalkilla valkaisseet, ja syöksen sen maahan, niin että sen perustus paljastuu. Se kaatuu, ja saatte siinä lopun. Mutta tulette tietämään, että minä olen Herra.',
        15: 'Minä panen kiivauteni täytäntöön seinässä ja niissä, jotka sen kalkilla valkaisivat, ja sanon teille: Ei ole enää seinää eikä sen valkaisijoita,',
        16: 'Israelin profeettoja, jotka ennustivat Jerusalemista ja näkivät sille rauhan näkyjä, vaikka ei rauhaa ollut, sanoo Herra, Herra.',
        17: 'Mutta sinä, ihmislapsi, käännä kasvosi kansasi tyttäriä vastaan, jotka joutuvat hurmoksiin oman sydämensä johtamina, ja profetoi heitä vastaan',
        18: 'ja sano: Näin sanoo Herra, Herra: Voi niitä naisia, jotka sitovat taikasiteitä kaikkiin ranteisiin ja tekevät huntuja kaikenkorkuisiin päihin pyydystääkseen sieluja! Toisia sieluja te pyydystätte kansaltani pois, toisten sielujen annatte elää omaksi eduksenne.',
        19: 'Häpäisette minut kansani edessä kourallisista ohria ja leipäpalasista, kun kuoletatte sieluja, joiden ei olisi kuoltava ja annatte elää sielujen, jotka eivät saisi elää ja kun valehtelette kansalleni, joka kuuntelee valhetta.',
        20: 'Sen tähden, näin sanoo Herra, Herra: Käyn käsiksi teidän taikasiteisiinne, joilla olette pyydystäneet sieluja kuin lintuja, ja revin ne käsivarsistanne ja lasken sielut lentoon – sielut, jotka te olette pyydystäneet.',
        21: 'Revin huntunne ja pelastan kansani käsistänne, niin etteivät he enää joudu kättenne saaliiksi; ja te tulette tietämään, että minä olen Herra.',
        22: 'Koska olette valheella murehduttaneet vanhurskaan sydämen, vaikka en tahtonut häntä murehduttaa, ja olette vahvistaneet jumalattoman käsiä, ettei hän kääntyisi pahalta tieltään ja eläisi,',
        23: 'sen tähden ette enää tule näkemään petosnäkyjä ettekä ennustelemaan ennustelujanne, vaan pelastan kansani käsistänne, ja tulette tietämään, että minä olen Herra."',
    },
    14: {
        1: 'Luokseni tuli miehiä Israelin vanhinten joukosta, ja he istuutuivat eteeni.',
        2: 'Minulle tuli tämä Herran sana, ja se kuului:',
        3: '"Ihmislapsi, nämä miehet ovat nostaneet epäjumalansa sydämeensä ja asettaneet kasvojensa eteen sen, mikä heille oli kompastukseksi syntiin. Antaisinko tosiaan heidän kysyä neuvoa itseltäni?',
        4: 'Sen tähden puhuttele heitä ja sano heille: Näin sanoo Herra, Herra: Kuka tahansa Israelin heimosta nostaa epäjumalansa sydämeensä ja asettaa kasvojensa eteen sen, mikä hänelle oli kompastukseksi syntiin, ja menee profeetan luo, hänelle minä, Herra, kyllä annan vastauksen – hänelle ja hänen monille epäjumalilleen,',
        5: 'ja tartun Israelin heimoa sydämeen, koska he ovat kääntyneet minusta pois kaikki seuraamalla epäjumaliaan.',
        6: 'Sen tähden sano Israelin heimolle: Näin sanoo Herra, Herra: Kääntykää, ja kääntykää pois epäjumalistanne ja kääntäkää kasvonne pois kaikista kauhistuksistanne.',
        7: 'Sillä kuka ikinä Israelin heimosta tai muukalainen, joka asuu Israelissa, luopuu minusta ja nostaa epäjumalansa sydämeensä ja asettaa kasvojensa eteen sen, mikä hänelle oli kompastukseksi syntiin, ja menee profeetan luo kysymään itselleen neuvoa minulta, hänelle minä, Herra, itse annan vastauksen.',
        8: 'Käännän kasvoni sitä miestä vastaan, teen hänet merkiksi ja sananparreksi ja hävitän hänet kansani keskeltä. Tulette tietämään, että minä olen Herra.',
        9: 'Mutta jos profeetta antaa viekoitella itsensä ja sanoo sanan, niin minä, Herra, olen sen profeetan viekoitellut. Ojennan käteni häntä vastaan ja hävitän hänet kansastani Israelista.',
        10: 'He tulevat kantamaan syntinsä – niin kuin kysyjän synti, on profeetankin synti –',
        11: 'etteivät he, Israelin heimo, enää eksyisi minusta pois eivätkä enää saastuttaisi itseään kaikilla rikkomisillaan, vaan olisivat kansani ja minä olisin heidän Jumalansa; sanoo Herra, Herra."',
        12: 'Minulle tuli tämä Herran sana ja se kuului:',
        13: '"Ihmislapsi! Jos maa tekisi syntiä minua vastaan olemalla uskoton ja ojentaisin sitä vastaan käteni ja murtaisin siltä leivän tuen ja lähettäisin siihen nälän ja hävittäisin siitä ihmiset ja eläimet,',
        14: 'ja sen keskellä olisivat nämä kolme miestä: Nooa, Daniel ja Job, he vanhurskaudellaan pelastaisivat oman henkensä, sanoo Herra, Herra.',
        15: 'Jos antaisin pahojen petoeläinten käydä halki maan ja ne riistäisivät siltä lapset ja se tulisi autioksi, niin ettei siellä olisi kulkijaa petoeläinten tähden,',
        16: 'niin nämä kolme miestä, jos olisivat sen keskellä, eivät voisi – niin totta kuin minä elän, sanoo Herra, Herra – pelastaa poikiaan eikä tyttäriään. Vain he itse pelastuisivat, mutta maa tulisi autioksi.',
        17: "Tai jos antaisin miekan tulla tämän maan yli ja sanoisin: 'Miekka, käy halki maan!' ja hävittäisin siitä ihmiset ja eläimet,",
        18: 'ja sen keskellä olisivat nämä kolme miestä, eivät he voisi – niin totta kuin minä elän, sanoo Herra, Herra – pelastaa poikiaan eikä tyttäriään, vaan vain he itse pelastuisivat.',
        19: 'Tai jos lähettäisin ruton tähän maahan ja vuodattaisin vihani sen yli verenä, niin että hävittäisin siitä ihmiset ja eläimet,',
        20: 'ja Nooa, Daniel ja Job olisivat sen keskellä, eivät he voisi – niin totta kuin minä elän, sanoo Herra, Herra – pelastaa poikaansa eikä tytärtään. Vain he vanhurskaudellaan pelastaisivat henkensä.',
        21: 'Sillä näin sanoo Herra, Herra: Mitä sitten, kun lähetän Jerusalemin päälle neljä kovaa tuomiotani: miekan, nälän, pahat petoeläimet ja ruton hävittämään siitä ihmiset ja eläimet!',
        22: 'Mutta katso, sinne on jäävä jäljelle pelastuneita, poikia ja tyttäriä, jotka viedään pois. Katso, he tulevat luoksenne, ja te näette heidän vaelluksensa ja tekonsa ja tulette lohdutetuiksi siitä onnettomuudesta, jonka olen tuottanut Jerusalemille, kaikesta, minkä olen sille tehnyt.',
        23: 'He lohduttavat teitä, kun näette heidän vaelluksensa ja tekonsa. Te tulette tietämään, etten syyttä suotta ole tehnyt sitä kaikkea, minkä olen sille tehnyt, sanoo Herra, Herra."',
    },
    15: {
        1: 'Minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Ihmislapsi, miksi viinipuu on parempi kuin kaikki muut puut, tuo köynnös, joka on metsän puiden seassa?',
        3: 'Otetaanko siitä puuta mihinkään tarkoitukseen? Tehdäänkö siitä tappiakaan, johon ripustetaan kaikkea tavaraa?',
        4: 'Katso, se annetaan tulen kulutettavaksi. Sen molemmat päät on tuli kuluttanut, ja sen keskiosa hiiltynyt. Kelpaako se tarve-esineeksi?',
        5: 'Katso, silloinkaan, kun se oli ehjä, siitä ei voinut valmistaa tarve-esinettä, saati sitten, kun tuli sen kulutti ja se hiiltyi – silloinko siitä tehtäisiin tarve-esine?',
        6: 'Sen tähden, näin sanoo Herra, Herra: Niin kuin metsän puiden seassa käy viinipuulle, jonka olen antanut tulen kulutettavaksi, niin annan käydä myös Jerusalemin asukkaille.',
        7: 'Käännän kasvoni heitä vastaan. Tulesta he ovat päässeet, mutta tuli heidät kuluttaa. Niin tulette tietämään, että minä olen Herra, kun käännän kasvoni heitä vastaan.',
        8: 'Teen maan autioksi, koska he ovat olleet uskottomat; sanoo Herra, Herra."',
    },
    16: {
        1: 'Minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Ihmislapsi, ilmoita Jerusalemille sen kauhistukset',
        3: 'ja sano: Näin sanoo Jerusalemille Herra, Herra: Sinun alkuperäsi ja syntysi on kanaanilaisten maasta. Isäsi oli amorilainen ja äitisi heettiläinen.',
        4: 'Näin oli syntymäsi: sinä päivänä, jona synnyit, sinulta ei leikattu napanuoraa, sinua ei pesty vedellä, että olisit puhdistunut, sinua ei hierottu suolalla eikä sinua kääritty kapaloihin.',
        5: 'Kukaan ei sinua säälinyt, niin että olisi tehnyt sinulle mitään tällaista ja armahtanut sinua, vaan sinut pantiin heitteille kedolle. Niin halpana pidettiin sinun henkesi sinä päivänä, jona synnyit.',
        6: "Mutta kuljin ohitsesi ja näin sinut, kun sätkyttelit verissäsi. Sanoin sinulle, kun olit siinä verissäsi: 'Sinun pitää elää' – niin sanoin sinulle, kun olit siinä verissäsi: 'Sinun pitää elää,",
        7: "teen sinut kymmeniksi tuhansiksi kuin pellon sadon.' Vartuit, tulit isoksi ja ehdit kauneimpaan kukoistukseesi, rintasi paisuivat, ja hiuksesi kasvoivat; mutta vielä sinä olit alaston ja paljas.",
        8: 'Kuljin ohitsesi ja näin sinut, ja katso, sinun aikasi oli lemmen aika. Levitin liepeeni ylitsesi ja peitin häpysi. Vannoin sinulle ja menin liittoon kanssasi, sanoo Herra, Herra. Tulit omakseni.',
        9: 'Pesin sinut vedellä, huuhtelin sinut verestäsi ja voitelin sinut öljyllä.',
        10: 'Puetin sinut kirjailtuihin vaatteisiin, panin jalkaasi tahašin nahasta tehdyt sandaalit, sidoin päähäsi hienopellavaisen siteen ja hunnutin sinut silkillä.',
        11: 'Koristin sinut koruilla, panin rannerenkaat käsiisi ja ketjut kaulaasi,',
        12: 'panin nenärenkaan nenääsi, korvarenkaat korviisi ja päähäsi kauniin kruunun.',
        13: 'Niin sinut koristeltiin kullalla ja hopealla, sinun pukusi oli hienoa pellavaa, silkkiä ja kirjailtua vaatetta, ja söit ydinjauhoja, hunajaa ja öljyä. Sinusta tuli erittäin kaunis, ja sinä kelpasit kuninkaalliseen arvoon.',
        14: 'Maineesi kulki pakanakansoihin kauneutesi tähden, sillä se oli täydellinen niiden kaunistusten takia, jotka puin yllesi, sanoo Herra, Herra.',
        15: "Mutta luotit kauneuteesi ja harjoitit haureutta maineesi nojalla ja vuodatit haureuttasi jokaiselle ohikulkijalle: 'Saakoon tuokin!'",
        16: 'Otit vaatteistasi kangasta ja teit itsellesi kirjavia uhrikukkuloita ja harjoitit haureutta niiden päällä. Sellaista ei ole tapahtunut eikä ole tapahtuva.',
        17: 'Otit korujasi, kultaani ja hopeaani, joita olin sinulle antanut, ja teit itsellesi miehenkuvia ja harjoitit haureutta niiden kanssa.',
        18: 'Otit kirjailtuja vaatteitasi ja verhosit ne niillä ja öljyni ja suitsukkeeni panit niiden eteen.',
        19: 'Ruokani, jota sinulle annoin –syötinhän sinua ydinjauhoilla, öljyllä ja hunajalla – sinä panit niiden eteen suloiseksi tuoksuksi. Näin tapahtui, sanoo Herra, Herra.',
        20: 'Otit poikasi ja tyttäresi, jotka olit minulle synnyttänyt, ja teurastit heidät niiden syödä. Oliko haureudessasi sinulle liian vähän,',
        21: 'kun vielä teurastit poikani ja annoit heidät poltettaviksi niille uhrina?',
        22: 'Kaikkien kauhistustesi ja haureutesi parissa et muistanut nuoruutesi päiviä, jolloin olit alaston ja paljas ja sätkyttelit verissäsi.',
        23: 'Kaiken muun pahuutesi lisäksi – voi, voi sinua! sanoo Herra, Herra –',
        24: 'rakensit itsellesi korokkeita ja teit itsellesi kumpuja kaikille toreille.',
        25: 'Kaikkiin kadunkulmiin rakensit kumpujasi ja häpäisit kauneutesi, levitit jalkasi jokaiselle ohikulkijalle ja yhä lisäsit haureuttasi.',
        26: 'Harjoitit haureutta naapuriesi, Egyptin isoelimisten poikien, kanssa ja yhä lisäsit haureuttasi ja niin vihoitit minut.',
        27: 'Katso, ojensin käteni sinua vastaan ja vähensin sinun määräosasi ja jätin sinut vihollistesi, filistealaisten tyttärien, raivon valtaan, jotka häpesivät sinun kauheaa vaellustasi.',
        28: 'Harjoitit haureutta Assurin poikien kanssa, koska et voinut saada kylliksesi. Vaikka harjoitit haureutta heidän kanssaan, et sittenkään saanut tarpeeksesi.',
        29: 'Lisäsit yhä haureuttasi Kanaanin maassa, Kaldeaan asti, mutta et siitäkään saanut tarpeeksesi.',
        30: 'Kuinka himosta voipuva olikaan sydämesi, sanoo Herra, Herra, kun teit tämän kaiken, niin kuin tekee portoista pahin,',
        31: 'kun rakensit korokkeesi kaikkiin kadunkulmiin ja teit kumpusi kaikille toreille! Mutta siinä et ollut porton kaltainen, että halveksit portonpalkkaa –',
        32: 'avionrikkojavaimo, joka miehensä sijaan ottaa vieraita!',
        33: 'Kaikille portoille annetaan lahja, mutta annoit portonlahjojasi kaikille rakastajillesi ja haureudessasi lahjoit heitä tulemaan luoksesi joka taholta.',
        34: 'Sinun laitasi oli haureudessasi päinvastoin kuin muiden naisten. Perässäsi ei juostu haureuteen, vaan sinä maksoit portonpalkkaa, mutta sinulle portonpalkkaa ei maksettu. Näin se oli päinvastoin.',
        35: 'Sen tähden, sinä portto, kuule Herran sana:',
        36: 'Näin sanoo Herra, Herra: Koska olet vuodattanut häpysi ja riisunut sen paljaaksi haureudessasi kaikille rakastajillesi ja kaikille kauhistaville epäjumalillesi, sekä lastesi veren tähden, jonka olet niille antanut,',
        37: 'sen tähden, katso, kokoan kaikki rakastajasi, jotka olivat sinulle mieleen, kaikki, joita rakastit, ja kaikki, joihin kyllästyit, ne kokoan sinua vastaan joka taholta ja paljastan heille alastomuutesi, niin että he näkevät koko alastomuutesi.',
        38: 'Tuomitsen sinut sen mukaan, mitä on säädetty avionrikkoja- ja verenvuodattajanaisista, ja annan vihassa ja kiivaudessa veresi vuotaa.',
        39: 'Annan sinut heidän käsiinsä, ja he hajottavat korokkeesi, kukistavat kumpusi, raastavat sinulta vaatteesi, ottavat korusi ja jättävät sinut alastomaksi ja paljaaksi.',
        40: 'He nostattavat kansanjoukon sinua vastaan, ja ne kivittävät sinut ja hakkaavat sinut maahan miekoillaan,',
        41: 'polttavat tulella talosi ja panevat sinussa toimeen tuomiot monien naisten silmien edessä. Teen lopun porttona olostasi, etkä enää sitten maksa portonpalkkoja.',
        42: 'Tyydytän vihani sinussa, niin että kiivauteni väistyy sinusta, ja tyynnyn enkä enää ole vihastunut.',
        43: 'Koska et ole muistanut nuoruutesi päiviä, vaan vihoitit minut kaikilla näillä – niin katso, minäkin annan vaelluksesi tulla oman pääsi päälle, sanoo Herra, Herra. Etkö sinä ole tehnyt näitä iljetyksiä kaikkien kauhistustesi lisäksi?',
        44: "Katso, jokainen, joka lausuu sananparsia, on tekevä sinusta sananparren: 'Tytär tulee äitiinsä.'",
        45: 'Sinä olet äitisi tytär, hänen, joka hyljeksi miestään ja lapsiaan, ja olet sisartesi sisar, heidän, jotka hyljeksivät miehiään ja lapsiaan. Äitinne oli heettiläinen ja isänne amorilainen.',
        46: 'Isosiskosi oli Samaria tyttärineen, joka asui vasemmalla puolellasi, ja pikkusiskosi, joka asui oikealla puolellasi, oli Sodoma tyttärineen.',
        47: 'Mutta et vaeltanut heidän teitään etkä tehnyt kauhistuksia samalla tavoin kuin he. Vähän aikaa vain, niin jo teit kaikilla teilläsi kelvottomammin kuin he.',
        48: 'Niin totta kuin minä elän, sanoo Herra, Herra: sisaresi Sodoma tyttärineen ei totisesti tehnyt sitä, mitä sinä tyttärinesi olet tehnyt.',
        49: 'Katso, tämä oli sisaresi Sodoman synti: ylpeys, leivän yltäkylläisyys ja huoleton lepo hänellä ja hänen tyttärillään. Mutta kurjaa ja köyhää hän ei kädestä tarttunut.',
        50: 'He ylpeilivät ja tekivät kauhistuksia edessäni, ja kun sen näin, toimitin heidät pois.',
        51: 'Samaria ei tehnyt puoltakaan syntiesi määrästä, mutta sinä olet tehnyt kauhistuksia paljon enemmän kuin he, niin että olet kaikilla kauhistuksillasi, joita olet tehnyt, saanut sisaresi näyttämään vanhurskailta.',
        52: 'Niinpä kanna myös häpeäsi, kun olet hankkinut tuollaisen hyvityksen sisarillesi. Syntiesi takia, kun olet menetellyt vielä kauhistavammin kuin he, he ovat vanhurskaampia kuin sinä. Häpeä sinäkin ja kanna häpeäsi, kun olet saanut sisaresi näyttämään vanhurskailta.',
        53: 'Mutta käännän heidän kohtalonsa: Sodoman ja hänen tyttäriensä kohtalon sekä Samarian ja hänen tyttäriensä kohtalon, ja käännän sinun kohtalosi, sinun, joka olet heidän keskellään,',
        54: 'että kantaisit häpeäsi ja olisit häpeissäsi kaikesta, mitä teit, kun lohdutit heidät.',
        55: 'Sisaresi, Sodoma tyttärineen, palaa entiselleen, ja Samaria tyttärineen palaa entiselleen. Myös sinä palaat tyttärinesi entisellesi.',
        56: 'Eikö sisaresi Sodoma ollut puheenaiheena suussasi ylpeytesi aikana,',
        57: 'ennen kuin oma pahuutesi paljastui, silloin kun jouduit Aramin tyttärien ja kaikkien heidän ympärillään asuvien, filistealaisten tyttärien, häväistäväksi, jotka joka taholta pilkkasivat sinua?',
        58: 'Sinä saat kantaa iljetyksesi ja kauhistuksesi, sanoo Herra.',
        59: 'Sillä näin sanoo Herra, Herra: Olen tehnyt sinulle sen mukaan, kuin sinä olet tehnyt, kun olet pitänyt valan halpana ja rikkonut liiton.',
        60: 'Mutta minä muistan liittoni, jonka tein kanssasi nuoruutesi päivinä, ja pystytän kanssasi iankaikkisen liiton.',
        61: 'Muistat vaelluksesi ja häpeät, kun otat vastaan sisaresi, ne, jotka ovat sinua isommat, sekä ne, jotka ovat sinua pienemmät, ja annan heidät sinulle tyttäriksi, mutta en sinun liittosi nojalla.',
        62: 'Minä pystytän liittoni kanssasi, ja tulet tietämään, että minä olen Herra.',
        63: 'Muistat ja häpeät etkä voi häpeäsi tähden enää avata suutasi, kun annan sinulle anteeksi kaiken, mitä tehnyt olet, sanoo Herra, Herra."',
    },
    17: {
        1: 'Minulle tuli tämä Herran sana ja se kuului:',
        2: '"Ihmislapsi, esitä arvoitus ja lausu sananparsi Israelin heimolle',
        3: 'ja sano: Näin sanoo Herra, Herra: Suuri kotka, suurisiipinen, pitkäsulkainen, täysihöyheninen, kirjava, tuli Libanonille ja otti latvuksen setripuusta.',
        4: 'Hän taittoi siitä latvalehvän ja vei sen Kanaanin maahan, asetti sen kauppiaiden kaupunkiin.',
        5: 'Hän otti siitä maasta taimen ja pani sen kylvöpeltoon. Hän otti sen ja istutti sen kuin pajun runsaan veden ääreen.',
        6: 'Se versoi, ja siitä tuli rehevä viinipuu, matalakasvuinen. Sen oksien tuli kääntyä kotkaan päin ja sen juurten olla hänen allaan. Siitä tuli viinipuu. Se teki haaroja ja työnsi oksia.',
        7: 'Mutta oli toinen suuri kotka, suurisiipinen, runsashöyheninen; ja katso, tämä viinipuu ojensi juurensa sitä kotkaa kohti ja työnsi oksansa siihen päin sen kasteltaviksi siitä penkereestä, johon se oli istutettu.',
        8: 'Se oli istutettu hyvään peltoon runsaan veden ääreen, että se tekisi lehviä, kantaisi hedelmää ja tulisi ihanaksi viinipuuksi.',
        9: 'Sano: Näin sanoo Herra, Herra: Menestyyköhän se? Eiköhän kotka kisko ylös sen juuria ja raasta sen hedelmiä, niin että kaikki siitä versoneet lehdet kuivuvat ja puu kuivuu? Eikä tarvita suurta voimaa eikä paljoa väkeä sen nostamiseksi juuriltaan.',
        10: 'Katso, se on istutettu – menestyyköhän se? Eikö se kuivu, kun siihen käy itätuuli, ja kuivu penkereessä, jossa se versoi?"',
        11: 'Sitten minulle tuli tämä Herran sana, ja se kuului:',
        12: '"Sano kapinoivalle suvulle: Ettekö tiedä, mitä tämä tarkoittaa? Sano: Katso, Baabelin kuningas tuli Jerusalemiin, otti sen kuninkaan ja ruhtinaat ja vei heidät luokseen Baabeliin.',
        13: 'Hän otti yhden kuninkaallisesta suvusta, teki hänen kanssaan liiton ja otti häneltä valan, mutta maan mahtavat hän vei mukanaan,',
        14: 'että valtakunta tulisi vähäpätöiseksi eikä kohoaisi, että se pitäisi liittonsa ja liitto pysyisi.',
        15: 'Mutta hän kapinoi häntä vastaan ja laittoi lähettiläänsä Egyptiin, että hänelle annettaisiin hevosia ja paljon väkeä. Menestyykö se, pelastuuko se, joka tekee tällaista? Pelastuuko se, joka rikkoo liiton?',
        16: 'Niin totta kuin minä elän, sanoo Herra, Herra: sen kuninkaan asuinpaikalla, joka hänet kuninkaaksi teki, jonka valan hän on halpana pitänyt ja jonka liiton hän on rikkonut, sen luona, keskellä Baabelia, hänen on totisesti kuoltava.',
        17: 'Mutta farao suurella sotajoukollaan ja paljolla väellään ei tee mitään hänen hyväkseen sodassa, kun luodaan valli ja rakennetaan saartovarusteet monien sielujen tuhoksi.',
        18: 'Hän piti halpana valan ja rikkoi liiton. Katso, vaikka hän oli kättä lyönyt, hän teki kaiken tämän – hän ei pelastu.',
        19: 'Sen tähden, näin sanoo Herra, Herra: Niin totta kuin minä elän, niin valani, jonka hän piti halpana, ja liittoni, jonka hän rikkoi, annan tulla hänen päänsä päälle.',
        20: 'Levitän verkkoni hänen ylitseen, ja hän takertuu pyydykseeni. Vien hänet Baabeliin ja käyn siellä oikeutta hänen kanssaan hänen uskottomuudestaan, jota hän on osoittanut minua kohtaan.',
        21: 'Kaikki hänen pakolaisensa kaikista hänen sotajoukoistaan kaatuvat miekkaan, ja jäljellejääneet hajotetaan kaikkiin tuuliin. Niin te tulette tietämään, että minä, Herra, olen puhunut.',
        22: 'Näin sanoo Herra, Herra: Mutta minä otan yhden latvuksen siitä korkeasta setripuusta ja istutan sen. Hennon latvalehvän minä siitä taitan ja istutan korkealle ja jyrkälle vuorelle.',
        23: 'Israelin vuoren korkeuteen sen istutan. Niin se kantaa lehviä ja tekee hedelmää, ja siitä tulee mahtava setri. Sen alla asuvat kaikki linnut, ja kaikki siivekkäät asuvat sen oksien varjossa.',
        24: 'Kaikki metsän puut tulevat tietämään, että minä olen Herra, joka teen korkean puun matalaksi ja matalan puun korkeaksi, tuoreen puun kuivaksi ja kuivan puun kukoistavaksi. Minä, Herra, Herra, olen puhunut ja sen teen."',
    },
    18: {
        1: 'Minulle tuli tämä Herran sana ja se kuului:',
        2: '"Mikä teillä on, kun te lausutte tätä sananpartta Israelin maasta: \'Isät söivät raakoja rypäleitä, lasten hampaat heltyivät\'?',
        3: 'Niin totta kuin minä elän, sanoo Herra, Herra, teidän ei tule enää lausua tätä sananpartta Israelissa.',
        4: 'Katso, kaikki sielut ovat minun: niin kuin isän sielu, niin pojankin sielu – ne ovat minun. Sen sielu, joka syntiä tekee – sen on kuoltava.',
        5: 'Jos mies on vanhurskas ja tekee oikeuden ja vanhurskauden:',
        6: 'ei syö uhrivuorilla, ei luo silmiään Israelin heimon epäjumaliin, ei saastuta lähimmäisensä vaimoa, ei lähesty vaimoaan, joka on kuukautistilassa,',
        7: 'ei sorra toista, vaan antaa takaisin velkapantin, ei riistä eikä raasta, vaan antaa leipäänsä nälkäiselle, verhoaa vaatteella alastonta,',
        8: 'ei anna rahaansa korolle, ei ota voittoa, vaan pidättää kätensä vääryydestä, tekee oikean tuomion miesten välillä,',
        9: 'vaeltaa käskyjeni mukaan ja noudattaa oikeuksiani, niin että tekee sitä, mikä on oikein – hän on vanhurskas, hän totisesti on elävä, sanoo Herra, Herra.',
        10: 'Mutta jos hänelle on syntynyt poika, väkivaltainen, verenvuodattaja, joka tekee yhtäkin näistä,',
        11: 'mitä hän itse ei ole tehnyt: syö uhrivuorilla, saastuttaa lähimmäisensä vaimon,',
        12: 'sortaa kurjaa ja köyhää, riistää ja raastaa, ei anna takaisin panttia, luo silmänsä epäjumaliin, tekee kauhistuksia,',
        13: 'antaa rahansa korolle ja ottaa voittoa – saisiko tämä elää? Hän ei tule elämään. Kaikkia näitä kauhistuksia hän on tehnyt, hänet on kuolemalla rangaistava. Hän on verivelan alainen.',
        14: 'Mutta katso, jos tälle on syntynyt poika ja hän näkee kaikki isänsä synnit, jotka tämä on tehnyt – näkee ne eikä tee sellaisia:',
        15: 'ei syö uhrivuorilla, ei luo silmiään Israelin heimon epäjumaliin, ei saastuta lähimmäisensä vaimoa,',
        16: 'ei sorra toista, ei ota panttia, ei riistä eikä raasta, vaan antaa leipäänsä nälkäiselle, verhoaa vaatteella alastonta,',
        17: 'pidättää kätensä koskemasta kurjaan, ei ota korkoa eikä voittoa, vaan tekee minun oikeuksieni mukaan, vaeltaa käskyjeni mukaan – hänen ei ole kuoltava isänsä syntivelan tähden, hän totisesti on elävä.',
        18: 'Hänen isänsä taas kun teki väkivallan töitä, riisti ja raastoi veljeltään ja teki kansansa keskuudessa sitä, mikä ei ole hyvää, niin katso, hänen oli kuoltava syntivelkansa tähden.',
        19: "Mutta vielä te kysytte: 'Minkä tähden poika ei kanna isän syntivelkaa?' Kun poika on tehnyt oikeuden ja vanhurskauden, noudattanut kaikkia käskyjäni ja tehnyt niiden mukaan, hän totisesti on elävä. Sen sielun, joka syntiä tekee – sen on kuoltava.",
        20: 'Poika ei kanna isän syntivelkaa, eikä isä kanna pojan syntivelkaa. Vanhurskaan ylle on tuleva hänen vanhurskautensa, ja jumalattoman ylle on tuleva hänen jumalattomuutensa.',
        21: 'Jos jumalaton kääntyy pois kaikesta synnistään, mitä hän on tehnyt, ja noudattaa kaikkia käskyjäni ja tekee oikeuden ja vanhurskauden, hän totisesti tulee elämään eikä hänen ole kuoltava.',
        22: 'Yhtään hänen synneistään, jotka hän on tehnyt, ei muisteta. Vanhurskautensa tähden, jota hän on noudattanut, hän on elävä.',
        23: 'Olisiko minulle mieleen jumalattoman kuolema, sanoo Herra, Herra, eikö se, että hän kääntyy pois teiltään ja elää?',
        24: 'Mutta jos vanhurskas kääntyy pois vanhurskaudestaan ja tekee vääryyttä, tekee kaikkien niiden kauhistusten kaltaisia, joita jumalaton tekee – hänkö on elävä? Ei yhtään hänen vanhurskasta tekoaan, jonka hän on tehnyt, muisteta. Uskottomuutensa tähden, johon hän on langennut, ja syntinsä tähden, jota hän on tehnyt, hänen on kuoltava.',
        25: "Vielä te sanotte: ' Herran tie ei ole oikea.' Kuulkaa siis, te Israelin heimo! Minunko tieni ei olisi oikea? Eikö niin: teidän omat tienne eivät ole oikeat!",
        26: 'Jos vanhurskas kääntyy pois vanhurskaudestaan ja tekee vääryyttä, sen tähden hänen on kuoltava. Vääryytensä tähden, jota hän on tehnyt, hänen on kuoltava.',
        27: 'Jos jumalaton kääntyy pois jumalattomuudestaan, jota hän on harjoittanut, ja tekee oikeuden ja vanhurskauden, hän säilyttää sielunsa elossa.',
        28: 'Koska hän näki ja kääntyi pois kaikista synneistään, joita oli tehnyt, hän totisesti tulee elämään. Hänen ei ole kuoltava.',
        29: "Mutta Israelin heimo sanoo: ' Herran tie ei ole oikea.' Minunko tieni eivät olisi oikeat, te Israelin heimo? Eikö niin: teidän omat tienne eivät ole oikeat!",
        30: 'Niinpä tuomitsen teidät, te Israelin heimo, itse kunkin hänen teittensä mukaan, sanoo Herra, Herra. Kääntykää, palatkaa pois kaikista synneistänne, ja älköön syntivelka tulko teille lankeemukseksi.',
        31: 'Heittäkää pois päältänne kaikki syntinne, joilla te olette rikkoneet, ja tehkää itsellenne uusi sydän ja uusi henki. Minkä tähden te kuolisitte, Israelin heimo?',
        32: 'Sillä ei ole minulle mieleen kuolevan kuolema, sanoo Herra, Herra. Kääntykää, niin elätte."',
    },
    19: {
        1: '"Mutta sinä, viritä itkuvirsi Israelin ruhtinaista',
        2: 'ja sano: Mikä naarasleijona äitisi olikaan leijonien joukossa! Se makasi nuorten leijonien keskellä ja kasvatti pentujaan',
        3: 'ja kasvatti isoksi yhden pennuistaan, ja siitä tuli nuori leijona. Se oppi saalistamaan ja söi ihmisiä.',
        4: 'Mutta kansat kuulivat siitä: se pyydystettiin heidän kuoppaansa ja vietiin koukusta vetäen Egyptin maahan.',
        5: 'Kun sen viipyessä emo näki, että hänen toivonsa oli mennyttä, se otti toisen pennuistaan, ja kasvatti sen nuoreksi leijonaksi.',
        6: 'Se käyskenteli leijonien keskellä, siitä tuli nuori leijona, se oppi saalistamaan, ja se söi ihmisiä.',
        7: 'Se yhtyi heidän leskiinsä ja teki autioiksi heidän kaupunkinsa, ja maa ja kaikki, mitä siinä on, kauhistui sen ärjynnän äänestä.',
        8: 'Silloin kansat sen ympärillä olevilta alueilta asettivat ja virittivät sille verkkonsa, ja se pyydystettiin heidän kuoppaansa.',
        9: 'Se pantiin häkkiin vetämällä koukusta ja vietiin Baabelin kuninkaan eteen. Se vietiin vuorilinnoihin, ettei sen ääni enää kuuluisi Israelin vuorille.',
        10: 'Äitisi oli sinulle kuin mehevä veden ääreen istutettu viinipuu. Se tuli runsaasta vedestä hedelmälliseksi ja siinä oli paljon oksia.',
        11: 'Siihen tuli vahvoja oksia hallitsijoiden valtikoiksi, ja sen runko kohosi korkealle tiheän oksaston keskellä ja näkyi kauas korkeana ja runsasoksaisena.',
        12: 'Mutta se temmattiin vihaisesti irti, heitettiin maahan, ja itätuuli kuivasi sen hedelmät. Ne revittiin hajalle, ja sen vahvat oksat kuivuivat, ja tuli kulutti ne.',
        13: 'Nyt se on istutettuna erämaahan, kuivaan ja janoiseen maahan.',
        14: 'Sen vahvasta oksasta on lähtenyt tuli. Se on kuluttanut sen hedelmät, ja vahvaa oksaa, josta olisi hallitusvaltikaksi, siinä ei enää ole." Itkuvirsi tämä oli oleva, ja itkuvirsi siitä on tullut.',
    },
    20: {
        1: 'Seitsemäntenä vuotena, viidennessä kuussa, kuukauden kymmenentenä päivänä tuli miehiä Juudan vanhinten joukosta kysymään neuvoa Herralta, ja he istuutuivat eteeni.',
        2: 'Minulle tuli tämä Herran sana ja se kuului:',
        3: '"Ihmislapsi, puhu Israelin vanhimmille ja sano heille: Näin sanoo Herra, Herra: Tekö tulette minulta kysymään neuvoa? Niin totta kuin minä elän, en anna teidän kysyä neuvoa itseltäni, sanoo Herra, Herra.',
        4: 'Etkö tuomitse heitä, etkö tuomitse, ihmislapsi? Tee heille tiettäviksi heidän isiensä kauhistukset',
        5: "ja sano heille: Näin sanoo Herra, Herra: Sinä päivänä, jona valitsin Israelin, kättä kohottaen lupasin Jaakobin heimon jälkeläisille, tein itseni heille tunnetuksi Egyptin maassa ja kättä kohottaen lupasin heille sanoen: 'Minä olen Herra, teidän Jumalanne.'",
        6: 'Sinä päivänä kohotin käteni, että vien heidät pois Egyptin maasta siihen maahan, jonka olin heille katsonut ja joka vuotaa maitoa ja hunajaa. Se on kaunistus kaikkien maiden joukossa.',
        7: "Sanoin heille: 'Heittäkää, itse kukin, pois silmienne iljetykset älkääkä saastuttako itseänne Egyptin epäjumalilla. Minä olen Herra, teidän Jumalanne.'",
        8: 'Mutta he kapinoivat minua vastaan, eivät tahtoneet kuulla minua eivätkä heittäneet pois itse kukin silmiensä iljetyksiä eivätkä hylänneet Egyptin epäjumalia. Sanoin vuodattavani kiivauteni heidän päälleen ja panevani vihani täytäntöön heissä keskellä Egyptin maata.',
        9: 'Mutta tein tekoni oman nimeni tähden, jotta se ei tulisi häväistyksi pakanoiden silmissä, joiden keskellä he olivat ja joiden silmien edessä olin tehnyt itseni heille tunnetuksi viemällä heidät pois Egyptin maasta.',
        10: 'Kun olin vienyt heidät pois Egyptin maasta ja tuonut heidät erämaahan,',
        11: 'annoin heille säädökseni ja tein heille tiettäviksi oikeuteni: ihminen, joka ne pitää, on niistä elävä.',
        12: 'Myös sapattini annoin heille olemaan merkkinä minun ja heidän välillään, että he tulisivat tietämään, että minä olen Herra, joka pyhitän heidät.',
        13: 'Mutta Israelin heimo kapinoi minua vastaan erämaassa. He eivät vaeltaneet käskyjeni mukaan ja halveksivat oikeuksiani, jotka ihmisen on pidettävä, että hän niistä eläisi, ja sapattini he rikkoivat kovin. Niin sanoin vuodattavani kiivauteni heidän päälleen erämaassa ja lopettavani heidät.',
        14: 'Mutta tein tekoni oman nimeni tähden, ettei se tulisi häväistyksi pakanoiden silmissä, joiden silmien edessä olin vienyt heidät pois.',
        15: 'Myös kättä kohottaen vannoin heille erämaassa, etten tuo heitä siihen maahan, jonka olin antanut heille, joka vuotaa maitoa ja hunajaa – se on kaunistus kaikkien maitten joukossa –',
        16: 'koska he pitivät oikeuteni halpoina, eivät vaeltaneet säädöksieni mukaan, vaan rikkoivat sapattini, sillä heidän sydämensä vaelsi heidän epäjumaliensa jäljessä.',
        17: 'Mutta säälin heitä, niin etten heitä hävittänyt enkä tehnyt heistä loppua erämaassa.',
        18: 'Sanoin heidän lapsilleen erämaassa: Älkää vaeltako isienne säädöksien mukaan, heidän oikeuksiansa älkää noudattako älkääkä saastuttako itseänne heidän epäjumalillaan.',
        19: 'Minä olen Herra, teidän Jumalanne; minun säädöksieni mukaan vaeltakaa, minun oikeuksiani noudattakaa, ne pitäkää',
        20: 'ja pyhittäkää sapattini. Ne olkoot merkkinä välillämme, minun ja teidän, että tulisitte tietämään, että minä olen Herra, teidän Jumalanne.',
        21: 'Mutta lapset kapinoivat minua vastaan, eivät vaeltaneet säädöksieni mukaan eivätkä noudattaneet oikeuksiani, niin että olisivat ne pitäneet, – jotka ihmisen on pidettävä, että hän niistä eläisi – ja rikkoivat sapattini. Sanoin vuodattavani kiivauteni heidän päälleen ja panevani vihani heissä täytäntöön erämaassa.',
        22: 'Mutta vedin käteni takaisin ja tein tekoni oman nimeni tähden, ettei se tulisi häväistyksi pakanoiden silmissä, joiden silmien edessä olin vienyt heidät pois.',
        23: 'Kättä kohottaen myös vannoin heille erämaassa, että hajotan heidät pakanoiden sekaan ja sirotan heidät muihin maihin,',
        24: 'koska he eivät pitäneet säädöksiäni, vaan halveksivat säädöksiäni, rikkoivat sapattini ja heidän silmänsä vilkuilivat heidän isiensä epäjumalien perään.',
        25: 'Minäkin annoin heille käskyjä, jotka eivät olleet hyviä, ja oikeuksia, joista he eivät voineet elää,',
        26: 'ja annoin heidän saastua lahjoistaan, siitä, että polttivat uhrina kaiken, mikä avasi äidinkohdun, jotta saattaisin heidät kauhun valtaan ja he tulisivat tietämään, että minä olen Herra.',
        27: 'Sen tähden puhu Israelin heimolle, ihmislapsi, ja sano heille: Näin sanoo Herra, Herra: Vielä niinkin ovat isänne minua herjanneet, että ovat olleet uskottomia minua kohtaan.',
        28: 'Kun toin heidät maahan, jonka olin kättä kohottaen luvannut heille antaa, niin missä vain he näkivät korkean kukkulan tai tuuhean puun, siinä he uhrasivat teurasuhrinsa ja antoivat vihastuttavat uhrilahjansa, siinä he panivat esiin suloisesti tuoksuvat uhrinsa ja siinä vuodattivat juomauhrinsa.',
        29: "Niin sanoin heille: 'Mikä tämä uhrikukkula on, jolle te menette?' Niin sellainen sai nimen uhrikukkula aina tähän päivään asti.",
        30: 'Sen tähden sano Israelin heimolle: Näin sanoo Herra, Herra: Ettekö te saastuta itseänne isienne tiellä? Ettekö kulje uskottomina heidän iljetystensä perässä?',
        31: 'Ettekö ole saastuttaneet itseänne kaikilla epäjumalillanne aina tähän päivään asti, kun tuotte lahjojanne ja panette lapsenne käymään tulen läpi? Minäkö antaisin teidän kysyä neuvoa itseltäni, te Israelin heimo? Niin totta kuin minä elän, sanoo Herra, Herra, en anna teidän kysyä neuvoa itseltäni.',
        32: "Se, mikä on tullut teidän mieleenne, ei totisesti tapahdu – se, mitä sanotte: 'Me tahdomme olla pakanoiden kaltaisia, muiden maiden sukukuntien kaltaisia, niin että palvelemme puuta ja kiveä.'",
        33: 'Niin totta kuin minä elän, sanoo Herra, Herra: totisesti olen hallitseva teitä väkevällä kädellä, ojennetulla käsivarrella ja vuodatetulla vihalla.',
        34: 'Vien teidät pois kansojen seasta ja kokoan teidät maista, joihin olitte hajotetut, väkevällä kädellä, ojennetulla käsivarrella ja vuodatetulla vihalla.',
        35: 'Tuon teidät kansakuntien erämaahan, ja käyn siellä oikeutta kanssanne kasvoista kasvoihin.',
        36: 'Niin kuin kävin oikeutta isienne kanssa Egyptin erämaassa, niin käyn oikeutta teidän kanssanne, sanoo Herra, Herra.',
        37: 'Panen teidät kulkemaan ruoskan ali ja saatan teidät liiton siteeseen.',
        38: 'Puhdistan teistä ne, jotka kapinoivat minua vastaan ja luopuvat minusta. Muukalaisuutensa maasta vien heidät pois, mutta Israelin maahan he eivät tule, ja te tulette tietämään, että minä olen Herra.',
        39: 'Mutta te, Israelin heimo! Näin sanoo Herra, Herra: Menkää vain ja palvelkaa itse kukin omia epäjumalianne. Mutta vastedes te totisesti kuulette minua ettekä enää häpäise pyhää nimeäni lahjoillanne sekä epäjumalillanne.',
        40: 'Sillä pyhällä vuorellani, Israelin korkealla vuorella, sanoo Herra, Herra, siellä he palvelevat minua, koko Israelin heimo, kaikki tyynni, mitä maassa on. Siellä miellyn heihin, siellä otan mielelläni vastaan antimenne, ensi sadon lahjanne ja teidän pyhät lahjanne.',
        41: 'Niin kuin suloisesti tuoksuvaan uhriin miellyn teihin, kun vien teidät pois kansojen seasta ja kokoan teidät maista, joihin olette hajotetut, ja osoitan teissä pyhyyteni pakanoiden silmien edessä.',
        42: 'Niin tulette tietämään, että minä olen Herra, kun tuon teidät Israelin maahan, siihen maahan, jonka kättä kohottaen olin luvannut antaa teidän isillenne.',
        43: 'Muistatte siellä vaelluksenne ja kaikki tekonne, joilla olette itsenne saastuttaneet, ja teitä inhottaa oma itsenne kaikkien pahojen tekojenne tähden, mitä olette tehneet.',
        44: 'Mutta tulette tietämään, että minä olen Herra, kun teen teille tekoni, oman nimeni tähden, en teidän pahan vaelluksenne enkä riettaiden tekojenne ansion mukaan, te Israelin heimo, sanoo Herra, Herra."',
    },
    21: {
        1: 'Sitten minulle tuli tämä Herran sana ja se kuului:',
        2: '"Ihmislapsi, käännä kasvosi etelää kohti, vuodata sanasi etelää vastaan ja profetoi kedon metsikköä vastaan, joka on Negevissä.',
        3: 'Sano Negevin metsikölle: Kuule Herran sana. Näin sanoo Herra, Herra: Katso, sytytän sinut tuleen, ja se kuluttaa kaikki tuoreet puusi ja kuivat puusi. Leimuava liekki ei sammu, ja siitä kärventyvät kaikki kasvot etelästä pohjoiseen asti.',
        4: 'Kaikki liha on näkevä, että minä, Herra, olen sen sytyttänyt: se ei sammu."',
        5: 'Minä sanoin: "Voi Herra, Herra! Ne sanovat minusta: \'Tämähän puhuu pelkkiä vertauksia.\'"',
        6: 'Sitten minulle tuli tämä Herran sana ja se kuului:',
        7: '"Ihmislapsi, käännä kasvosi Jerusalemia kohti, vuodata sanasi pyhäköitä vastaan ja profetoi Israelin maata vastaan ja sano Israelin maalle:',
        8: 'Näin sanoo Herra: Katso, käyn sinun kimppuusi, vedän miekkani tupesta ja hävitän sinusta vanhurskaan ja jumalattoman.',
        9: 'Koska hävitän sinusta vanhurskaan ja jumalattoman, sen tähden miekkani lähtee tupestaan kaiken lihan kimppuun etelästä pohjoiseen asti.',
        10: 'Kaikki liha tulee tietämään, että minä, Herra, olen vetänyt miekkani tupesta, eikä se siihen enää palaa.',
        11: 'Mutta sinä, ihmislapsi, huokaile! Lanteet murtuneina, katkerassa tuskassa huokaile heidän silmiensä edessä.',
        12: 'Kun he sinulta kysyvät: \'Minkä tähden sinä huokailet?\' niin sano: Sanoman tähden, sillä se saapuu, ja kaikki sydämet raukeavat, kaikki kädet herpoavat, kaikkien henki voipuu, kaikki polvet käyvät veltoiksi kuin vesi. Katso, se tulee, se tapahtuu; sanoo Herra, Herra."',
        13: 'Minulle tuli tämä Herran sana, ja se kuului:',
        14: '"Ihmislapsi, profetoi ja sano: Näin sanoo Herra. Sano: Miekka, miekka on teroitettu ja myös kirkkaaksi hiottu.',
        15: 'Sen tähden se on teroitettu teurastamaan, välkehtiväksi se on hiottu. Vai iloitsisimmeko? Vitsa, joka lyö poikaani, pitää halpana kaikkia puisia vitsoja.',
        16: 'Hän on antanut sen hioa käteen otettavaksi. Miekka on teroitettu ja hiottu annettavaksi surmaajan käteen.',
        17: 'Huuda ja valita, ihmislapsi, sillä tämä tapahtuu kansaani vastaan, kaikkia Israelin ruhtinaita vastaan. He ovat annetut alttiiksi miekalle, he ja kansani. Lyö sen vuoksi lanteisiisi.',
        18: 'Sillä vitsaa on jo koeteltu. Mutta entä, jos vitsa halveksiikin tätä kaikkea? Se ei tapahdu, sanoo Herra, Herra.',
        19: 'Mutta sinä, ihmislapsi, profetoi ja lyö käsiäsi yhteen. Tulkoon miekasta kaksi miekkaa, tulkoon kolme. Se on surmamiekka, miekka, joka surmaa suuretkin, joka kiertää heitä joka taholta,',
        20: 'että sydän menehtyisi pelkoon, että kompastuksia olisi paljon. Kaikille heidän porteillensa olen asettanut miekan välkkymään. Voi, se on tehty salamaksi ja on hiottu teurastusta varten!',
        21: 'Lyö terävästi oikealle, ojennu vasemmalle, mihin vain kasvosi käännät.',
        22: 'Minäkin lyön käsiäni yhteen ja tyydytän kiivauteni. Minä, Herra, olen puhunut."',
        23: 'Minulle tuli tämä Herran sana, ja se kuului:',
        24: '"Sinä, ihmislapsi, laita kaksi tietä, Baabelin kuninkaan miekan tulla. Samasta maasta lähtekööt molemmat. Veistä viitta. Veistä se kaupunkiin vievän tien alkuun.',
        25: 'Laita tie miekan tulla ammonilaisten Rabbaan sekä Juudaan, varustettuun Jerusalemiin.',
        26: 'Sillä Baabelin kuningas pysähtyy tienhaaraan, molempien teiden alkuun, taikojansa taikomaan. Hän pudistaa nuolia, kysyy kotijumalilta ja katsoo maksasta.',
        27: 'Hänen oikeaan käteensä tulee Jerusalemin arpa. Sinne on pantava muurinmurtajia, siellä hänen on kohotettava sotahuuto, pantava muurinmurtajat porteille, luotava valtausluiska ja rakennettava piiritysvalli.',
        28: 'Mutta Jerusalemin asukkaiden silmissä tämä on pettävää taikomista. Onhan heillä valojen valat. Mutta hän saattaa muistoon syntivelan, että he joutuisivat kiinni.',
        29: 'Sen tähden, näin sanoo Herra, Herra: Koska olette saattaneet muistoon syntivelkanne rikoksenne tultua julki, niin että teidän syntinne on näkyvissä kaikissa teidän teoissanne, niin – koska te olette saatetut muistoon – teidät otetaan kiinni käsin.',
        30: 'Sinä saastutettu, jumalaton Israelin ruhtinas, jonka päivä on silloin tullut, kun syntivelka on saavuttanut viimeisen määränsä!',
        31: 'Näin sanoo Herra, Herra: Ota pois turbaani ja riisu kruunu.',
        32: 'Tämä ei pysy samana: alhainen korotetaan, korkea alennetaan. Murskaksi, murskaksi, murskaksi panen tämän kruunun. Siitä ei ole jäävä mitään, kunnes tulee se, jolla on oikeus, ja annan sen hänelle.',
        33: 'Mutta sinä, ihmislapsi, profetoi ja sano: Näin sanoo Herra, Herra ammonilaisia ja heidän herjauksiaan vastaan: Sano näin: Miekka, miekka on paljastettu, teurastukseen hiottu, pantu kuntoon käyttöä varten ja välkehtimään,',
        34: 'silloin kun sinulle nähdään petollisia näkyjä ja ennustellaan valheita, että sinut muka pannaan tallaamaan saastaisten, jumalattomien niskaa, joiden päivä on silloin tullut, kun syntivelka on saavuttanut viimeisen määränsä.',
        35: 'Pane se tuppeensa takaisin. Paikassa, jossa olet luotu, synnyinmaassasi, minä sinut tuomitsen.',
        36: 'Vuodatan päällesi kiivauteni, puhallan sinuun vihani tulen ja annan sinut raakojen miesten ja tuhontekijöiden käsiin.',
        37: 'Tulen kulutettavaksi sinut annetaan, sinun veresi on oleva keskellä maata, eikä sinua enää muisteta. Sillä minä, Herra, olen puhunut."',
    },
    22: {
        1: 'Minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Sinä, ihmislapsi, etkö tuomitse, etkö tuomitse verivelkojen kaupunkia ja tee sille tiettäväksi kaikkia sen kauhistuksia?',
        3: 'Sano: Näin sanoo Herra, Herra: Voi kaupunkia, joka on vuodattanut keskuudessaan verta, että tulisi sen aika, ja joka on tehnyt saastuakseen itselleen epäjumalia!',
        4: 'Verestäsi, jonka olet vuodattanut, olet tullut syylliseksi, ja epäjumalistasi, jotka olet tehnyt, olet saastunut. Olet jouduttanut päiviäsi ja olet päässyt vuosiesi määrään. Sen tähden annan sinut pakanoiden häväistäväksi ja kaikkien maiden pilkattavaksi.',
        5: 'Läheiset ja kaukaiset pilkkaavat sinua, jonka nimi on saastutettu ja jossa on paljon sekasortoa.',
        6: 'Katso, Israelin ruhtinaat sinussa luottavat kukin omaan käsivarteensa vuodattaakseen verta.',
        7: 'Isää ja äitiä sinussa halveksitaan, muukalaiselle tehdään keskuudessasi väkivaltaa, orpoa ja leskeä sinussa sorretaan.',
        8: 'Mikä on minulle pyhitettyä, sitä halveksit ja rikot sapattini.',
        9: 'Sinussa on niitä, jotka panettelevat vuodattaakseen verta. Uhrivuorilla he syövät keskuudessasi, ja ilkitöitä tehdään keskelläsi.',
        10: 'Isän häpy sinussa paljastetaan. Naiselle, joka on saastainen kuukautistilansa tähden, tehdään keskuudessasi väkivaltaa.',
        11: 'Toinen harjoittaa kauhistusta lähimmäisensä vaimon kanssa, mies saastuttaa häpeällisesti miniänsä, ja mies tekee keskelläsi väkivaltaa sisarelleen, isänsä tyttärelle.',
        12: 'Keskuudessasi otetaan lahjuksia veren vuodattamiseksi, sinä otat korkoa ja voittoa, kiskot väkivaltaisesti lähimmäiseltäsi, mutta minut unohdat, sanoo Herra, Herra.',
        13: 'Mutta katso, lyön käsiäni yhteen sinun väärän voittosi tähden, jota olet hankkinut, ja sinun verivelkojesi tähden, joita keskuudessasi on.',
        14: 'Kestääköhän rohkeutesi, pysyvätköhän kätesi lujina niinä päivinä, joina teen sinulle tekoni? Minä, Herra, olen puhunut, ja minä sen teen.',
        15: 'Hajotan sinut pakanoiden sekaan ja sirottelen sinut muihin maihin ja poistan sinusta saastaisuutesi.',
        16: 'Tulit saastaiseksi oman itsesi takia kansojen silmissä, mutta tulet tietämään, että minä olen Herra."',
        17: 'Sitten minulle tuli tämä Herran sana, ja se kuului:',
        18: '"Ihmislapsi, Israelin heimo on kuonaksi tullut. He ovat kaikki vaskea, tinaa, rautaa ja lyijyä ahjossa. Heistä on tullut hopean kuonaa.',
        19: 'Sen tähden, näin sanoo Herra, Herra: Koska te kaikki olette tulleet kuonaksi, sen tähden, katso, kokoan teidät keskelle Jerusalemia.',
        20: 'Niin kuin hopea, vaski, rauta, lyijy ja tina kootaan keskelle ahjoa, että niihin lietsottaisiin tulta ja ne sulatettaisiin, niin vihassani ja kiivaudessani kokoan teidät ja asetan ahjoon ja sulatan.',
        21: 'Kerään teidät ja lietson teihin vihani tulta, ja sulatte keskellä Jerusalemia.',
        22: 'Niin kuin hopea sulatetaan keskellä ahjoa, niin sulatetaan teidät sen keskellä. Tulette tietämään, että minä, Herra, olen vuodattanut kiivauteni teidän päällenne."',
        23: 'Minulle tuli tämä Herran sana, ja se kuului:',
        24: '"Ihmislapsi, sano sille: Sinä olet maa, jota ei ole puhdistettu, joka ei ole saanut sadetta vihan päivänä.',
        25: 'Profeettojen salaliitto sen keskellä on kuin ärjyvä, saalista raateleva leijona. He syövät sieluja, ottavat aarteet ja kalleudet ja lisäävät sen keskuudessa sen leskien lukua.',
        26: 'Sen papit tekevät väkivaltaa lailleni ja häpäisevät sitä, mikä on minulle pyhitettyä, eivät tee erotusta pyhän ja epäpyhän välillä, eivät tee tiettäväksi, mikä on saastaista, mikä puhdasta, ja sulkevat silmänsä sapateiltani, niin että tulen häväistyksi heidän keskellään.',
        27: 'Sen ruhtinaat siellä ovat kuin saalista raatelevat sudet. He vuodattavat verta ja hukuttavat sieluja kiskoakseen väärää voittoa.',
        28: "Sen profeetat valkaisevat heille kaiken kalkilla, kun näkevät petollisia näkyjä ja ennustelevat heille valheita sanoen: 'Näin sanoo Herra, Herra ', vaikka Herra ei ole puhunut.",
        29: 'Maan kansa harjoittaa väkivaltaa, riistää ja raastaa. Kurjaa ja köyhää he sortavat ja tekevät muukalaiselle väkivaltaa oikeudesta välittämättä.',
        30: 'Etsin heidän joukostaan miestä, joka korjaisi muurin ja seisoisi muurinaukossa edessäni maan puolesta, etten sitä hävittäisi, mutta en löytänyt.',
        31: 'Sen tähden vuodatan heidän päälleen kiivauteni, hukutan heidät vihani tulella ja annan heidän vaelluksensa tulla heidän päänsä päälle, sanoo Herra, Herra."',
    },
    23: {
        1: 'Minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Ihmislapsi, oli kaksi naista, saman äidin tyttäriä.',
        3: 'He harjoittivat haureutta Egyptissä. Nuoruudessaan he haureutta harjoittivat. Siellä heidän rintojaan likisteltiin ja heidän neitseellisiä nännejään puristeltiin.',
        4: 'Heidän nimensä olivat: vanhemman Ohola ja hänen sisarensa Oholiba. He tulivat omikseni ja synnyttivät poikia ja tyttäriä. – Heidän nimensä: Samaria on Ohola ja Jerusalem Oholiba.',
        5: 'Mutta Ohola harjoitti haureutta, vaikka oli minun, ja himoitsi rakastajiaan, assurilaisia, naapureita,',
        6: 'jotka olivat sinipunaiseen purppuraan puettuja ja olivat käskynhaltijoita ja päälliköitä, komeita nuorukaisia kaikki, ratsumiehiä ja hevosella ratsastajia.',
        7: 'Hän antautui haureuteen näiden kanssa, jotka olivat kaikki Assurin valioita. Keitä vain hän himoitsi, niiden kaikkien kanssa hän saastutti itsensä kaikilla heidän epäjumalillaan.',
        8: 'Mutta egyptinaikaista haureuttaan hän ei jättänyt, sillä he olivat maanneet hänen kanssaan hänen nuoruudessaan, olivat puristelleet hänen neitseellisiä nännejään ja vuodattaneet hänen päälleen haureuttaan.',
        9: 'Sen tähden annoin hänet rakastajiensa käsiin, assurilaisten käsiin, joita hän oli himoinnut.',
        10: 'He paljastivat hänen häpynsä ja ottivat hänen poikansa ja tyttärensä ja tappoivat hänet itsensä miekalla, niin että hänestä tuli varoittava esimerkki muille naisille, ja panivat hänessä toimeen tuomiot.',
        11: 'Mutta hänen sisarensa Oholiba, vaikka näki tämän, oli himossaan häntäkin riettaampi ja oli haureudessaan riettaampi, kuin hänen sisarensa oli ollut haureudessaan.',
        12: 'Hän himoitsi Assurin poikia, jotka olivat käskynhaltijoita, päälliköitä, naapureita, loisteliaasti puettuja, ratsumiehiä, hevosella ratsastajia, komeita nuorukaisia kaikki.',
        13: 'Silloin näin, että hän saastutti itsensä. Sama tie oli kummallakin.',
        14: 'Mutta hän meni haureudessaan vielä pidemmälle. Kun hän näki seinään piirrettyjä miehiä, kaldealaisten kuvia, punavärillä piirrettyjä,',
        15: 'vyö vyötettynä vyötäisillä, päässä hieno turbaani, kaikki päälliköiden näköisiä, Baabelin poikien muotoisia, joiden synnyinmaa on Kaldea,',
        16: 'niin hän silmän näkemältä sai himon heihin ja lähetti lähettiläitä heidän luokseen Kaldeaan.',
        17: 'Baabelin pojat tulivat ja makasivat hänen kanssaan hekumassa ja saastuttivat hänet haureudellaan, niin että hän saastui heistä. Sitten hänen sielunsa vieraantui heistä.',
        18: 'Mutta kun hän paljasti haureutensa ja paljasti häpynsä, niin sieluni vieraantui hänestä, niin kuin sieluni oli vieraantunut hänen sisarestaan.',
        19: 'Mutta hän yhä lisäsi haureuttaan, kun muisti nuoruutensa päivät, jolloin oli haureutta harjoittanut Egyptin maassa.',
        20: 'Hän sai himon heidän rakastajiinsa, joiden liha on kuin aaseilla ja vuoto kuin oriilla.',
        21: 'Sinä etsit nuoruutesi iljettävyyttä, jolloin egyptiläiset puristelivat nännejäsi nuoruutesi rintojen tähden.',
        22: 'Sen tähden, Oholiba, näin sanoo Herra, Herra: Katso, nostatan kimppuusi rakastajasi, joista sielusi on vieraantunut, ja tuon heidät kimppuusi joka taholta:',
        23: 'Baabelin pojat ja kaikki kaldealaiset, Pekodin, Sooan ja Kooan ja heidän kanssaan kaikki Assurin pojat – kaikki komeita nuorukaisia, käskynhaltijoita ja päälliköitä, aseenkantajia ja mainioita miehiä, kaikki he ratsastavat hevosella.',
        24: 'He tulevat kimppuusi aseineen, vaunuineen ja rattaineen ja suurine kansanjoukkoineen. Suurine ja pienine kilpineen ja kypärineen he käyvät sinua vastaan joka taholta. Annan heille tuomiovallan, ja he tuomitsevat sinut oikeuksiensa mukaan.',
        25: 'Osoitan sinussa kiivauteni, niin että he kohtelevat sinua ankarasti. He leikkaavat sinulta nenän ja korvat, ja jälkeläisesi kaatuvat miekkaan. He ottavat poikasi ja tyttäresi, ja jälkeläisesi kuluttaa tuli.',
        26: 'He riisuvat sinulta vaatteesi ja ottavat korusi.',
        27: 'Niin teen lopun iljettävyydestäsi ja Egyptin haureudestasi, etkä sitten luo silmiäsi heihin etkä enää muistele Egyptiä.',
        28: 'Sillä näin sanoo Herra, Herra: Katso, annan sinut niiden käsiin, joita vihaat, niiden käsiin, joista sielusi on vieraantunut.',
        29: 'He kohtelevat sinua vihamielisesti, ottavat kaiken vaivannäkösi ja jättävät sinut alastomaksi ja paljaaksi, ja haureellinen häpysi ja iljettävyytesi ja haureutesi paljastuu.',
        30: 'Näin sinulle tehdään sen tähden, että uskottomana juoksit pakanoiden perässä ja että saastutit itsesi heidän epäjumalillaan.',
        31: 'Vaelsit sisaresi tietä, ja annan hänen maljansa käteesi.',
        32: 'Näin sanoo Herra, Herra: Sisaresi maljan sinä juot, syvän ja leveän. Tulet nauruksi ja pilkaksi. Malja vetää paljon.',
        33: 'Tulet juopumusta ja murhetta täyteen. Kauhun ja häviön malja on sisaresi Samarian malja.',
        34: 'Sen juot kuiviin, sen sirpaleita kaluat ja revit niillä rintasi. Sillä minä olen puhunut, sanoo Herra, Herra.',
        35: 'Sen tähden, näin sanoo Herra, Herra: Koska olet minut unohtanut ja heittänyt minut selkäsi taakse, niin kanna myös iljettävyytesi ja haureutesi."',
        36: 'Herra sanoi minulle: "Ihmislapsi, tuomitsetko Oholan ja Oholiban? Ilmoita siis heille heidän kauhistuksensa.',
        37: 'Sillä he ovat rikkoneet avion, ja heidän käsissään on verta. Epäjumalillaan he ovat avion rikkoneet, lapsensakin, jotka he minulle synnyttivät, he ovat polttaneet niiden ruuaksi.',
        38: 'Vielä tämänkin he ovat minulle tehneet: ovat samana päivänä saastuttaneet pyhäkköni ja rikkoneet sapattini.',
        39: 'Teurastettuaan lapsiaan epäjumalilleen he samana päivänä tulivat pyhäkkööni ja häpäisivät sen. Katso, näin he ovat tehneet keskellä huonettani.',
        40: 'Vieläpä he lähettivät noutamaan miehiä, jotka tulivat kaukaa. Katso, kun he saapuivat, sinä peseydyit heitä varten, maalasit silmäluomesi ja panit päällesi korut.',
        41: 'Istuit komealle vuoteelle, sen ääressä oli katettu pöytä, ja sille panit suitsukkeeni ja öljyni.',
        42: 'Sitten sieltä kuului ilohuuto. Ihmisjoukosta otettujen miesten lisäksi tuotiin erämaasta juomareita, ja he panivat naisten käsiin rannerenkaat ja heidän päähänsä kauniit kruunut.',
        43: "Mutta sanoin: 'Aviorikoksesta kuihtuneen kanssa he harjoittavat haureutta ja hän heidän kanssaan.'",
        44: 'Hänen luokseen tultiin, aivan kuin tullaan porttonaisen luo. Niin tultiin Oholan ja Oholiban luo – noiden julkeiden naisten luo.',
        45: 'Mutta vanhurskaat miehet tulevat tuomitsemaan heidät avionrikkojille säädetyllä tuomiolla ja verenvuodattajille määrätyllä tuomiolla, sillä he ovat rikkoneet avion ja heidän käsissään on verta.',
        46: 'Sillä näin sanoo Herra, Herra: Nostatettakoon kansanjoukko heitä vastaan, ja heidät pantakoon kauhistukseksi ja ryöstettäköön.',
        47: 'Kansanjoukko kivittäköön heidät ja hakatkoon kappaleiksi miekoillaan, tappakoon heidän poikansa ja tyttärensä ja polttakoon heidän talonsa tulella.',
        48: 'Lopetan iljettävän menon maasta, ja kaikki naiset ottavat siitä ojentuakseen, niin etteivät harjoita iljettävää menoa, kuten te.',
        49: 'Teidän iljettävyytenne pannaan teidän päällenne, ja saatte kantaa epäjumalienne kanssa tehdyt syntinne. Tulette tietämään, että minä olen Herra, Herra."',
    },
    24: {
        1: 'Tämä Herran sana tuli minulle yhdeksäntenä vuotena, kymmenennessä kuussa, kuukauden kymmenentenä päivänä ja kuului:',
        2: '"Ihmislapsi, kirjoita muistiisi päivän nimi – juuri tämän päivän nimi: Baabelin kuningas rynnistää Jerusalemia vastaan juuri tänä päivänä.',
        3: 'Lausu kapinoivalle suvulle vertaus ja sano heille: Näin sanoo Herra, Herra: Pane pata [tulelle], pane. Kaada myös siihen vettä.',
        4: 'Kokoa siihen lihankappaleet – kaikki hyvät kappaleet, reittä ja lapaa – ja täytä se valituilla luilla.',
        5: 'Ota parasta lammasta, pane padan alle tuli. Anna sen kiehua kiehumistaan, niin että luutkin tulevat siinä keitetyiksi.',
        6: 'Sen tähden, näin sanoo Herra, Herra: Voi verivelkojen kaupunkia, pataa, joka on ruostunut ja josta sen ruoste ei lähde! Tyhjennä se kappale kappaleelta: sille ei ole langennut arpaosaa.',
        7: 'Sillä sen vuodattama veri on sen keskellä, paljaalle kalliolle se on sen koonnut, eikä ole vuodattanut sitä maahan tomun peitettäväksi.',
        8: 'Nostattaakseni kiivauden ja tuottaakseni koston olen pannut sen veren paljaalle kalliolle, ettei se peittyisi.',
        9: 'Sen tähden, näin sanoo Herra, Herra: Voi verivelkojen kaupunkia! Minäkin panen lisää puita tuleen.',
        10: 'Lisää puita, sytytä tuli, kypsennä liha, sekoita pataa, kunnes luut hiiltyvät.',
        11: 'Anna sen sitten olla tyhjänä hiiltensä päällä, niin että se kuumenee, sen vaski hehkuu ja sen saastat siitä sulavat ja sen ruosteesta tulee loppu.',
        12: 'Siitä on ollut vaivaa väsymykseen asti, mutta sen ruosteen paljous ei ole lähtenyt siitä. Tuleen sen ruoste!',
        13: 'Sinun iljettävän saastaisuutesi takia – koska puhdistin sinua, mutta et puhdistunut saastaisuudestasi – et enää puhdistu, ennen kuin tyydytän kiivauteni sinussa.',
        14: 'Minä, Herra, olen puhunut. Se tapahtuu, ja minä teen sen. En luovu, en säästä enkä kadu: teittesi ja tekojesi mukaan sinut tuomitaan, sanoo Herra, Herra."',
        15: 'Minulle tuli tämä Herran sana, ja se kuului:',
        16: '"Ihmislapsi, katso, otan sinulta äkkiä pois silmiesi ihastuksen, mutta älä valita, älä itke, älköönkä sinulta tulko kyyneleitä.',
        17: 'Huokaile hiljaa, mutta älä pane toimeen kuolleelle valittajaisia. Sido turbaani päähäsi, pane sandaalit jalkaasi, älä peitä partaasi äläkä syö murehtivien leipää."',
        18: 'Puhuin kansalle aamulla, mutta illalla vaimoni kuoli. Sitten aamulla tein, niin kuin minun oli käsketty tehdä.',
        19: 'Kansa sanoi minulle: "Etkö ilmoita meille, mitä se tietää meille, kun sinä noin toimit?"',
        20: 'Sanoin heille: "Minulle tuli tämä Herran sana, ja se kuului: Sano Israelin heimolle:',
        21: 'Näin sanoo Herra, Herra: Katso, häpäisen pyhäkköni, joka on varustuksenne ja ylpeytenne, silmienne ihastus ja sielujenne mieltymys. Poikanne ja tyttärenne, jotka teidän on jätettävä, kaatuvat miekkaan.',
        22: 'Teette, niin kuin olen tehnyt: ette peitä partaanne ettekä syö surevien leipää,',
        23: 'turbaanin pidätte päässänne ja sandaalit jaloissanne, ette valita ettekä itke, mutta te voivutte syntivelkanne tähden ja huokailette toinen toisellenne.',
        24: 'Hesekiel on oleva teille ennusmerkki: aivan niin, kuin hän on tehnyt, niin tekin teette. Kun tämä tapahtuu, tulette tietämään, että minä olen Herra, Herra.',
        25: 'Mutta sinä, ihmislapsi! Sinä päivänä, jona otan heiltä heidän varustuksensa, ihanan ilonsa, silmiensä ihastuksen, elämänsä toivon, heidän poikansa ja tyttärensä,',
        26: 'sinä päivänä tulee pakolainen luoksesi ilmoittamaan tämän korviesi kuullen.',
        27: 'Sinä päivänä avaat suusi yhdessä pakolaisen kanssa, ja puhut etkä enää ole mykkänä ja olet oleva heille ennusmerkki, ja he tulevat tietämään, että minä olen Herra."',
    },
    25: {
        1: 'Minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Ihmislapsi, käännä kasvosi ammonilaisia kohti ja profetoi heitä vastaan',
        3: 'ja sano ammonilaisille: Kuulkaa Herran, Herran sana: Näin sanoo Herra, Herra: Sinä sanoit: pyhäköstäni, kun se häväistiin, ja Israelin maasta, kun se hävitettiin, ja Juudan heimosta, kun he menivät karkotukseen: "Kas noin!"',
        4: 'Koska niin sanoit, sen tähden, katso, annan sinut Idän miesten omaksi, ja he laittavat sinuun leiripaikkansa ja asettavat sinuun asuntonsa. He syövät hedelmäsi ja juovat maitosi.',
        5: 'Rabban panen kamelien laitumeksi ja ammonilaisten maan lampaiden levähdyspaikaksi. Tulette tietämään, että minä olen Herra.',
        6: 'Sillä näin sanoo Herra, Herra: Koska sinä taputit käsiä ja poljit jalkaa ja sielu täynnä halveksuntaa pidit iloa Israelin maasta,',
        7: 'sen tähden, katso, ojennan käteni sinua vastaan ja annan sinut pakanoiden ryöstettäväksi ja hävitän sinut kansakuntien joukosta ja hukutan sinut maiden luvusta ja tuhoan sinut. Tulet tietämään, että minä olen Herra.',
        8: "Näin sanoo Herra, Herra: Koska Mooab ja Seir ovat sanoneet: 'Katso, Juudan heimon käy kuin kaikkien muiden kansojen',",
        9: 'sen tähden, katso, teen avonaiseksi pääsyn Mooabin sivustan kaupungeista – sen rajoille kaupungeista, jotka ovat maan kaunistus: Beet-Jesimot, Baal-Meon ja Kirjataim.',
        10: 'Idän miesten omaksi annan sen ammonilaisten kanssa, niin ettei ammonilaisia enää muisteta kansojen joukossa,',
        11: 'ja Mooabissa panen toimeen tuomiot. He tulevat tietämään, että minä olen Herra.',
        12: 'Näin sanoo Herra, Herra: Koska Edom menetteli kovin kostonhimoisesti Juudan heimoa kohtaan ja rikkoi raskaasti kostaessaan heille,',
        13: 'sen tähden, näin sanoo Herra, Herra: Ojennan käteni Edomia vastaan ja hävitän siitä ihmiset ja eläimet. Teemanista lähtien teen sen raunioiksi, ja Dedania myöten he kaatuvat miekkaan.',
        14: 'Mutta kostoni, joka Edomia kohtaa, annan kansani Israelin käteen, ja he tekevät Edomia kohtaan vihani ja kiivauteni mukaan. Edom saa tuntea kostoni, sanoo Herra, Herra.',
        15: 'Näin sanoo Herra, Herra: Koska filistealaiset menettelivät kostonhimoisesti ja halveksunta sielussaan, kostivat kovasti, ikivihassa tuottaakseen tuhon,',
        16: 'sen tähden, näin sanoo Herra, Herra: Katso, ojennan käteni filistealaisia vastaan, hävitän kreetit, hukutan, mitä on jäljellä meren rannikolla,',
        17: 'ja teen heille suuret kostoteot rangaisten kiivaudessa. He tulevat tietämään, että minä olen Herra, kun annan kostoni kohdata heitä',
    },
    26: {
        1: 'Yhdentenätoista vuotena, kuukauden ensimmäisenä päivänä tuli minulle tämä Herran sana:',
        2: '"Ihmislapsi, koska Tyyro sanoi Jerusalemista: \'Kas noin! Murrettu on kansojen ovi, minuun päin se on kääntynyt, tulen täyteen – se on raunioina!\'',
        3: 'sen tähden, näin sanoo Herra, Herra: Katso, käyn kimppuusi, Tyyro, ja nostatan monet kansat sinua vastaan, niin kuin meri nostaa aaltonsa.',
        4: 'Ne hävittävät Tyyron muurit, repivät maahan sen tornit, ja lakaisen siitä pois sen tomutkin ja panen sen paljaaksi kallioksi.',
        5: 'Siitä tulee verkkojen kuivauspaikka keskelle merta. Sillä minä olen puhunut, sanoo Herra, Herra; ja se joutuu kansojen ryöstettäväksi.',
        6: 'Sen tytärkaupungit, jotka ovat mantereella, surmataan miekalla, ja he tulevat tietämään, että minä olen Herra.',
        7: 'Sillä näin sanoo Herra, Herra: Katso, tuon Tyyron kimppuun Nebukadressarin, Baabelin kuninkaan pohjoisesta, kuninkaitten kuninkaan, hevosten ja vaunujen ja ratsumiesten ja suuren väenpaljouden kanssa.',
        8: 'Sinun tytärkaupunkisi, jotka ovat mantereella, hän surmaa miekalla ja asettaa sinua vastaan saartovarusteet, rakentaa sinua vastaan vallin, asettaa sinua vastaan kilvet,',
        9: 'suuntaa muureihisi murtajansa iskut ja kukistaa tornisi aseillaan.',
        10: 'Hänen hevostensa paljous peittää sinut pölyyn. Ratsumiesten, pyörien ja vaunujen ryskeestä sinun muurisi vapisevat, kun hän hyökkää sisälle porteistasi, niin kuin valloitettuun kaupunkiin hyökätään.',
        11: 'Hevostensa kavioilla hän tallaa rikki kaikki katusi, surmaa miekalla kansasi, ja mahtavat patsaasi kaatuvat maahan.',
        12: 'He riistävät rikkautesi ja ryöstävät kauppatavarasi, repivät muurisi maahan ja kukistavat kauniit talosi, sekä kivesi, puusi ja tomusi he heittävät mereen.',
        13: 'Lakkautan laulujesi helinän, eikä kuulu enää lyyrojesi soitto.',
        14: 'Teen sinut paljaaksi kallioksi, sinusta tulee verkkojen kuivauspaikka, eikä sinua enää rakenneta. Sillä minä, Herra, olen puhunut, sanoo Herra, Herra.',
        15: 'Näin sanoo Herra, Herra Tyyrolle: Eivätkö saaret vapise kukistumisesi pauhusta, kun haavoitetut voihkivat, kun surman omat surmataan keskelläsi?',
        16: 'Valtaistuimiltaan astuvat alas kaikki meren ruhtinaat. He heittävät pois viittansa ja riisuvat kirjaillut vaatteensa, he pukeutuvat kauhuun ja istuvat maahan, vapisevat joka hetki, murheissaan tähtesi.',
        17: "He virittävät sinusta itkuvirren ja sanovat sinulle: 'Kuinka olet sinä, joka olit asuttu, hävinnyt meriltä, sinä ylistetty kaupunki, väkevä merellä, sinä ja asukkaasi, jotka levittivät kauhuaan kaikkiin siellä asuviin.",
        18: "Nyt saaret värisevät häviösi päivänä, merensaaret kauhistuvat loppuasi.'",
        19: 'Sillä näin sanoo Herra, Herra: Kun teen sinusta aution kaupungin, niin kuin asumattomat kaupungit ovat, kun annan syvyyden käydä ylitsesi ja paljot vedet peittävät sinut,',
        20: 'silloin syöksen sinut alas hautaan vaipuneiden pariin, ennen eläneen kansan luo, ja annan sinulle asunnon maan syvyyksissä, niin kuin siellä ovat vanhat rauniot, hautaan vaipuneiden parissa, ettei sinussa asuttaisi. Mutta ihanuuden annan elävien maahan.',
        21: 'Panen sinut kauhuksi, sinua ei sitten enää ole. Jos sinua etsitään, sinua ei enää koskaan löydy, sanoo Herra, Herra."',
    },
    27: {
        1: 'Minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Sinä, ihmislapsi! Viritä itkuvirsi Tyyrosta',
        3: "ja sano Tyyrolle, joka asuu meren porteilla ja käy kauppaa kansojen kanssa, monilukuisilla saarilla: Näin sanoo Herra, Herra: Tyyro, sinä sanot: 'Minä olen kauneuden täydellisyys!'",
        4: 'Meren sydämessä on alueesi, rakentajasi tekivät sinun kauneutesi täydelliseksi,',
        5: 'Senirin sypresseistä he rakensivat sinuun kaiken, mikä laudoista on, ottivat Libanonin setrin tehdäkseen sinuun maston,',
        6: 'tekivät Baasanin tammista airosi, kansilankkusi tekivät norsunluusta ja kittiläisten saarten puusta.',
        7: 'Kirjailtua Egyptin pellavaa oli purjeesi, ja se oli sinulla lippuna. Katoksesi oli sinipunaista ja purppuranpunaista Elisa-saarten kangasta.',
        8: 'Siidonin ja Arvadin asukkaat olivat sinulla soutajina. Omat viisaasi, Tyyro, olivat sinussa – he olivat päällikköinä.',
        9: 'Gebalin vanhimmat ja viisaat olivat sinulla vuotokohtien korjaajia. Meren kaikki laivat merimiehineen olivat sinussa tavaroitasi vaihtamassa.',
        10: 'Persia, Luud ja Puut olivat sotajoukossasi sotureinasi. He ripustivat sinuun kypäriä ja kilpiä. Ne sinua koristivat.',
        11: 'Arvadilaiset ja muu sotajoukkosi olivat muureillasi ympäriinsä ja gammadilaiset torneissasi. He ripustivat varustuksensa pitkin ympäri muurejasi. Ne tekivät kauneutesi täydelliseksi.',
        12: 'Tarsis oli kauppatuttavasi kaikkinaisten rikkauksiesi runsauden takia: hopealla, raudalla, tinalla ja lyijyllä he maksoivat tavarasi.',
        13: 'Jaavan, Tuubal ja Mesek kävivät kauppaa kanssasi. Elävillä ihmisillä ja vaskiesineillä he maksoivat vaihtotavarasi.',
        14: 'Toogarman heimo maksoi tavarasi hevosilla, ratsuilla ja muuleilla.',
        15: 'Dedanilaiset kävivät kauppaa kanssasi. Monilukuisten rannikkojen asukkaat olivat kauppatuttaviasi ja alaisiasi. Norsunluuta ja ebenpuuta ne toivat sinulle maksuksi.',
        16: 'Aram oli kauppatuttavasi tuotteittesi runsauden takia. Rubiineilla, purppuralla, kirjaillulla kankaalla, valkopellavalla, koralleilla ja jaspiksella he maksoivat tavarasi.',
        17: 'Juuda ja Israelin maa kävivät kauppaa kanssasi: Minnitin vehnällä, leivoksilla, hunajalla, öljyllä ja balsamilla he maksoivat vaihtotavarasi.',
        18: 'Damasko oli kauppatuttavasi tuotteittesi runsauden ja kaikenlaisten rikkauksiesi runsauden takia: Helbonin viiniä ja Saharin villoja.',
        19: 'Vedan ja Jaavan Usalasta maksoivat ostoksesi taotulla raudalla. Kassiaa ja kalmoruokoa tuli sinulle vaihtotavarana.',
        20: 'Dedan kävi kauppaa kanssasi ratsastussatuloiden loimilla.',
        21: 'Arabia ja kaikki Keedarin ruhtinaat kävivät kanssasi kauppaa. Lampaita, pässejä ja vuohipukkeja he myivät sinulle.',
        22: 'Saban ja Raman kauppiaat kävivät kauppaa kanssasi. Kaikenlaisilla parhailla balsameilla, kaikilla kalliilla kivillä ja kullalla he maksoivat tavarasi.',
        23: 'Haaran ja Kanne ja Eden, Saban kauppiaat, Assur ja Kilmad kävivät kauppaa kanssasi.',
        24: 'He kävivät kanssasi kauppaa markkinoillasi kauniilla vaatteilla, punasinisillä ja kirjailluilla viitoilla, kirjavakuteisilla matoilla ja punotuilla, kestävillä köysillä.',
        25: 'Tarsiin laivat kuljettivat vaihtotavaroitasi. Niin sinä tulit täyteen ja olit hyvin kuulu merten sydämessä.',
        26: 'Soutajasi vievät sinut suurille vesille, ja itätuuli särkee sinut merten sydämessä.',
        27: 'Sinun rikkautesi, tavarasi, vaihtotavarasi, merimiehesi ja laivurisi, vuotokohtien korjaajasi, tavaranvaihtajasi ja kaikki sotamiehesi, jotka ovat sinussa ja koko suuressa joukossasi, joka on keskuudessasi, painuvat merten sydämeen kukistumisesi päivänä.',
        28: 'Laivan päälliköiden itkun äänestä vapisevat tantereet.',
        29: 'Alas laivoistaan astuvat kaikki soutajat, merimiehet ja kaikki merilaivan päälliköt astuvat maihin,',
        30: 'huutavat tähtesi suurella äänellä ja itkevät katkerasti, heittävät tomua päänsä päälle ja kieriskelevät tuhkassa.',
        31: 'He ajavat tähtesi päänsä paljaaksi, kääriytyvät säkkeihin ja itkevät tähtesi mieli murheellisena ja valittaen katkerasti.',
        32: "Valittaessaan he virittävät sinusta itkuvirren ja laulavat sinusta: 'Kuka oli Tyyron vertainen, hänen, joka on nyt niin hiljaa meren keskellä?",
        33: 'Kun tavarasi saapuivat meriltä, sinä ravitsit monet kansat. Rikkauksiesi ja vaihtotavaroittesi runsaudella sinä teit rikkaiksi maan kuninkaita.',
        34: "Nyt, kun jouduit haaksirikkoon, vetten syvyyksiin, mukanasi vajosivat sinne vaihtotavarasi ja koko suuri joukkosi.'",
        35: 'Sinun tähtesi tulivat murheellisiksi kaikki saarten asukkaat, ja heidän kuninkaansa ovat kauhun vallassa vapina kasvoillaan.',
        36: 'Kansojen kauppiaat viheltävät sinulle. Kauhuksi olet tullut, eikä sinua enää koskaan ole."',
    },
    28: {
        1: 'Sitten minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Ihmislapsi, sano Tyyron ruhtinaalle: Näin sanoo Herra, Herra: Koska sydämesi on ylpistynyt ja sanot: \'Minä olen jumala ja istun jumalien istuimella merten sydämessä\', ja olet kuitenkin ihminen, et jumala, vaikka sydämeltäsi olet viisaudessa jumalan vertainen –',
        3: 'ja katso, Danielia viisaampi sinä oletkin, mikään salaisuus ei ole sinulta pimitetty.',
        4: 'Viisaudessasi ja ymmärtäväisyydessäsi olet hankkinut itsellesi rikkautta, hankkinut kultaa ja hopeaa aarreaittoihisi,',
        5: 'ja suuressa viisaudessasi olet kaupankäynnillä kartuttanut rikkautesi, ja sydämesi on ylpistynyt rikkaudestasi –',
        6: 'sen tähden, näin sanoo Herra, Herra: Koska vertaat sydäntäsi Jumalan sydämeen,',
        7: 'sen tähden, katso, tuon kimppuusi muukalaiset, julmimmat pakanoista. He paljastavat miekkansa viisautesi kauneutta vastaan ja saattavat häpeään ihanuutesi.',
        8: 'He syöksevät sinut alas kuoppaan, ja kuolet, niin kuin surmatut kuolevat merten sydämessä.',
        9: "Sanotko surmaajasi edessä: 'Minä olen Jumala', kun kuitenkin kaatajiesi käsissä olet ihminen etkä Jumala?",
        10: 'Niin kuin ympärileikkaamattomat kuolevat, sinä kuolet muukalaisten käden kautta. Sillä minä olen puhunut, sanoo Herra, Herra."',
        11: 'Sitten minulle tuli tämä Herran sana, ja se kuului:',
        12: '"Ihmislapsi, viritä itkuvirsi Tyyron kuninkaasta ja sano hänelle: Näin sanoo Herra, Herra: Sinä olet sopusuhtaisuuden sinetti, täynnä viisautta, täydellinen kauneudessa.',
        13: 'Eedenissä, Jumalan puutarhassa, sinä olit. Peitteenäsi olivat kaikenlaiset kalliit kivet. Karneolia, topaasia ja jaspista, krysoliittia, onyksia ja berylliä, safiiria, rubiinia ja smaragdia sekä kultaa olivat upotus- ja syvennystyöt sinussa, valmistetut sinä päivänä, jona sinut luotiin.',
        14: 'Olit kerubi, joka suojasi laajalti, ja minä asetin sinut Jumalan pyhälle vuorelle käyskentelemään tulisten kivien keskellä.',
        15: 'Sinä olit nuhteeton vaellukseltasi siitä päivästä, jona sinut luotiin, siihen saakka, kunnes sinussa löydettiin vääryys.',
        16: 'Suuressa kaupankäynnissäsi tuli sydämesi täyteen väkivaltaa, ja teit syntiä. Karkotan sinut häväistynä Jumalan vuorelta ja hävitän sinut, suojaava kerubi, pois tulisten kivien keskeltä.',
        17: 'Sydämesi ylpistyi kauneudestasi, ihanuutesi tähden kadotit viisautesi. Heitän sinut maahan, annan sinut häpeään kuninkaille heidän silmiensä edessä.',
        18: 'Paljoilla synneilläsi ja tekemällä vääryyttä kaupoissasi olet häväissyt pyhäkkösi. Annan keskeltäsi puhjeta tulen. Se kuluttaa sinut. Panen sinut tuhkaksi maahan kaikkien silmien edessä, jotka sinut näkivät.',
        19: 'Kaikki tuttavasi kansojen seassa hämmästyvät tähtesi. Kauhuksi sinä tulet, eikä sinua enää koskaan ole oleva."',
        20: 'Minulle tuli tämä Herran sana, ja se kuului:',
        21: '"Ihmislapsi, käännä kasvosi Siidonia kohti ja profetoi sitä vastaan',
        22: 'ja sano: Näin sanoo Herra, Herra: Katso, käyn kimppuusi, Siidon, ja näytän kunniani keskuudessasi. He tulevat tietämään, että minä olen Herra, kun panen siinä toimeen tuomiot ja näytän siinä pyhyyteni.',
        23: 'Lähetän sinne ruton ja verta kaduille, ja kaatuneita on viruva sen keskellä, miekkaan kaatuneita. Se käy sen kimppuun joka taholta. Niin he tulevat tietämään, että minä olen Herra.',
        24: 'Israelin heimolle ei enää ole pistävänä orjantappurana eikä vaivaavana ohdakkeena yksikään sen naapureista, jotka ovat heitä halveksineet. He tulevat tietämään, että minä olen Herra, Herra.',
        25: 'Näin sanoo Herra, Herra: Kun kokoan Israelin heimon kansakunnista, joiden sekaan heidät on hajotettu, silloin näytän pyhyyteni heissä pakanakansojen silmien edessä, ja he saavat asua maassaan, jonka annoin palvelijalleni Jaakobille.',
        26: 'He asuvat siinä turvallisesti ja rakentavat taloja ja istuttavat viinitarhoja. Turvassa he asuvat, kun panen toimeen tuomiot kaikille heidän naapureilleen, jotka ovat heitä halveksineet. Silloin he tulevat tietämään, että minä olen Herra, heidän Jumalansa."',
    },
    29: {
        1: 'Kymmenentenä vuotena, kymmenennessä kuussa, kuukauden kahdentenatoista päivänä minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Ihmislapsi, käännä kasvosi faraota, Egyptin kuningasta, kohti ja profetoi häntä ja koko Egyptiä vastaan.',
        3: "Puhu ja sano: Näin sanoo Herra, Herra: Katso, käyn kimppuusi, farao, Egyptin kuningas, suuri krokotiili, joka makaat virtojesi keskellä, joka sanot: 'Niilivirtani on minun, ja olen sen itselleni tehnyt.'",
        4: 'Panen koukut leukoihisi, tartutan virtojesi kalat suomuihisi ja nostan sinut ylös virtojesi keskeltä sekä kaikki virtojesi kalat, jotka ovat suomuihisi tarttuneet.',
        5: 'Heitän erämaahan sinut ja kaikki virtojesi kalat. Putoat kedolle, sinua ei korjata eikä koota. Metsän pedoille ja taivaan linnuille annan sinut ruuaksi.',
        6: 'Kaikki Egyptin asukkaat tulevat tietämään, että minä olen Herra. Sillä he ovat ruokosauva Israelin heimolle:',
        7: 'kun he kädellä tarttuvat sinuun, sinä säryt ja lävistät heiltä kaikki olkapäät. Kun he nojaavat sinuun, sinä murrut ja jäykistät heiltä kaikki lanteet.',
        8: 'Sen tähden, näin sanoo Herra, Herra: Katso, minä tuon kimppuusi miekan ja hävitän sinusta ihmiset ja eläimet.',
        9: "Egyptin maa tulee autioksi ja raunioiksi. He tulevat tietämään, että minä olen Herra. Sillä hän on sanonut: 'Niilivirta on minun, ja minä olen sen tehnyt.'",
        10: 'Sen tähden, katso, käyn sinun ja virtojesi kimppuun ja teen Egyptin maan raunioiksi, kuivaksi ja autioksi Migdolista Seveneen ja aina Kuusin rajaan saakka.',
        11: 'Siellä ei kulje ihmisen jalka, eikä siellä kulje karjaeläimen jalka, eikä siellä asuta neljäänkymmeneen vuoteen.',
        12: 'Autioksi teen Egyptin maan autioitettujen maiden joukossa, ja sen kaupungit tulevat olemaan autioina raunioitettujen kaupunkien joukossa neljäkymmentä vuotta, ja egyptiläiset hajotan kansojen sekaan ja sirottelen heidät muihin maihin.',
        13: 'Sillä näin sanoo Herra, Herra: Neljänkymmenen vuoden kuluttua kokoan egyptiläiset kansakunnista, joiden sekaan he olivat hajotetut,',
        14: 'käännän Egyptin kohtalon ja tuon heidät takaisin Patroksen maahan, josta he ovat lähtöisin. Siellä he tulevat olemaan vähäpätöinen valtakunta.',
        15: 'He tulevat olemaan vähäpätöisin valtakunnista, eivätkä enää kohoa kansakuntien yläpuolelle. Vähennän heidät niin, etteivät he enää vallitse kansoja.',
        16: 'He eivät ole enää Israelin heimon turvana. He saattavat muistoon Israelin syntivelan, kun se kääntyi heidän puoleensa. He tulevat tietämään, että minä olen Herra, Herra."',
        17: 'Kahdentenakymmenentenä seitsemäntenä vuotena, ensimmäisessä kuussa, kuukauden ensimmäisenä päivänä tuli minulle tämä Herran sana:',
        18: '"Ihmislapsi, Baabelin kuningas Nebukadressar on teettänyt sotajoukoillaan suuren työn Tyyroa vastaan. Kaikki päät ovat käyneet kaljuiksi ja kaikki hartiat ovat hiertyneet. Mutta palkkaa ei Tyyrosta ole tullut hänelle eikä hänen sotajoukoilleen työstä, jota he ovat tehneet sitä vastaan.',
        19: 'Sen tähden, näin sanoo Herra, Herra: Katso, minä annan Baabelin kuninkaalle Nebukadressarille Egyptin maan. Hän vie sen rikkaudet, saa sen saaliikseen, ryöstää sen ryöstettävät, ja se on oleva hänen sotajoukkojensa palkka.',
        20: 'Palkaksi, jonka toivossa hän on työtä tehnyt, annan hänelle Egyptin maan, sillä minun hyväkseni he ovat sitä tehneet, sanoo Herra, Herra.',
        21: 'Sinä päivänä annan puhjeta Israelin heimolle sarven, ja avaan suusi heidän keskellään. He tulevat tietämään, että minä olen Herra."',
    },
    30: {
        1: 'Sitten minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Ihmislapsi, profetoi ja sano: Näin sanoo Herra, Herra: Valittakaa: \'Voi sitä päivää!\'',
        3: 'Sillä lähellä on päivä, lähellä Herran päivä. Se on pilvinen päivä, pakanakansojen aika.',
        4: 'Miekka tulee Egyptiin, ja kauhu leviää Kuusiin, kun surmattuja kaatuu Egyptissä, kun siltä viedään sen rikkaudet ja revitään perustukset.',
        5: 'Kuus, Puut ja Luud, kaikki sekakansa, Kuub ja liittoutuneen maan miehet kaatuvat heidän kanssaan miekkaan.',
        6: 'Näin sanoo Herra: Egyptin tuet kaatuvat, ja sen ylpeä mahti alenee. Migdolista Seveneen asti he siellä kaatuvat miekkaan, sanoo Herra, Herra.',
        7: 'Autioiksi he joutuvat autioiksi tehtyjen maitten joukkoon, ja heidän kaupunkinsa tulevat olemaan raunioiksi pantujen kaupunkien joukossa.',
        8: 'He tulevat tietämään, että minä olen Herra, kun sytytän Egyptin tuleen ja kaikki sen auttajat sortuvat.',
        9: 'Sinä päivänä lähtee luotani laivoilla lähettiläitä pelästyttämään turvassa elävää Kuusia. Heille tulee tuska kuin Egyptin päivänä, sillä katso, se tulee.',
        10: 'Näin sanoo Herra, Herra: Teen lopun Egyptin joukoista Baabelin kuninkaan Nebukadressarin kädellä.',
        11: 'Hän ja hänen väkensä hänen kanssaan, julmimmat pakanoista, tuodaan hävittämään maata, ja he paljastavat miekkansa Egyptiä vastaan ja täyttävät maan surmatuilla.',
        12: 'Teen virrat kuiviksi ja myyn maan pahojen käsiin ja teen autioksi maan ja kaiken, mitä siinä on, muukalaisten kädellä. Minä, Herra, olen puhunut.',
        13: 'Näin sanoo Herra, Herra: Tuhoan epäjumalat ja lopetan epäjumalat Noofista ja ruhtinaat Egyptistä. Niitä ei ole enää oleva, ja saatan Egyptin maan pelon valtaan.',
        14: 'Teen Patroksen autioksi, sytytän Sooanin tuleen ja panen toimeen tuomiot Noossa.',
        15: 'Vuodatan kiivauteni Siiniin, Egyptin linnoitukseen, ja hävitän Noon meluavat joukot',
        16: 'ja sytytän Egyptin tuleen. Siin kieriskelee tuskasta, Noo murskataan, ja Noofiin ahdistajat hyökkäävät keskellä päivää!',
        17: 'Aavenin ja Piibesetin nuorukaiset kaatuvat miekkaan, ja muut menevät vankeuteen.',
        18: 'Tehafneheessa päivä pimenee, kun särjen siellä Egyptin ikeen, ja siinä saa lopun sen ylpeä mahti. Sen itsensä peittää pilvi, ja sen tyttäret menevät vankeuteen.',
        19: 'Panen tuomiot toimeen Egyptissä, ja he tulevat tietämään, että minä olen Herra."',
        20: 'Yhdentenätoista vuotena, ensimmäisessä kuussa, kuukauden seitsemäntenä päivänä tuli minulle tämä Herran sana, ja se kuului:',
        21: '"Ihmislapsi, olen murskannut faraon, Egyptin kuninkaan, käsivarren, ja katso, sitä ei sidota, ei hoideta eikä panna kääreeseen, että se sidottuna vahvistuisi tarttuakseen miekkaan.',
        22: 'Sen tähden, näin sanoo Herra, Herra: Katso, käyn faraon, Egyptin kuninkaan, kimppuun ja murskaan häneltä käsivarret, sekä voimakkaan että murskatun käden, ja pudotan miekan hänen kädestään.',
        23: 'Hajotan egyptiläiset kansojen sekaan ja sirottelen heidät muihin maihin.',
        24: 'Baabelin kuninkaan käsivarret vahvistan ja annan miekkani hänen käteensä. Mutta faraolta murskaan käsivarret, ja hän voihkii hänen edessään, niin kuin nujerrettu voihkii.',
        25: 'Vahvistan Baabelin kuninkaan käsivarret, mutta faraon käsivarret vaipuvat alas. He tulevat tietämään, että minä olen Herra, kun annan miekkani Baabelin kuninkaan käteen, että hän ojentaisi sen Egyptin maata vastaan.',
        26: 'Hajotan egyptiläiset kansojen sekaan ja sirottelen heidät muihin maihin. He tulevat tietämään, että minä olen Herra."',
    },
    31: {
        1: 'Yhdentenätoista vuotena, kolmannessa kuussa, kuukauden ensimmäisenä päivänä tuli minulle tämä Herran sana ja se kuului:',
        2: '"Ihmislapsi, sano faraolle, Egyptin kuninkaalle, ja hänen meluaville joukoilleen: Kenen kaltainen olet suuruudessasi?',
        3: 'Katso, Assur oli setri Libanonilla, kauniine oksineen, varjoisine lehvineen, korkeakasvuinen, ja sen latva oli tiheän oksaston keskellä.',
        4: 'Vedet olivat kasvattaneet sen suureksi, korkeaksi sen oli saanut syvyys, joka virtoineen kiersi sen istutusmaata ja lähetti ojiaan kaikille metsän puille.',
        5: 'Sen tähden siitä tuli korkeakasvuisin kaikista kedon puista. Se sai paljon haaroja, ja oksat, joita se levitti, tulivat pitkiksi runsaista vesistä.',
        6: 'Sen lehvillä pesivät kaikki taivaan linnut, sen oksien alla synnyttivät kaikki kedon eläimet, ja sen varjossa asuivat kaikki suuret kansat.',
        7: 'Kaunis se oli suuruudessaan ja oksiensa pituudessa, sillä sen juuri oli runsaiden vetten ääressä.',
        8: 'Setrit eivät olleet sen vertaisia Jumalan puutarhassa, eivät sypressit sen oksien veroisia, eivät plataanit niin kuin sen haarat. Ei yksikään puu Jumalan puutarhassa ollut kauneudessa sen veroinen.',
        9: 'Minä tein sen niin kauniiksi oksien runsaudessa, että kaikki Eedenin puut Jumalan puutarhassa sitä kadehtivat.',
        10: 'Sen tähden, näin sanoo Herra, Herra: Koska se tuli korkeakasvuiseksi ja sen latva oli tiheän lehvästön keskellä ja sen sydän ylpistyi sen korkeudesta,',
        11: 'annoin sen pakanoista mahtavimman käsiin, ja hän teki sille, mitä teki. Jumalattomuutensa tähden karkotin sen.',
        12: 'Sen hakkasivat muukalaiset, julmimmat pakanoista, ja heittivät maahan. Vuorille ja kaikkiin laaksoihin kaatuivat sen haarat, ja sen oksat murskaantuivat kaikkiin maan puroihin. Kaikki maan kansat laskeutuivat alas sen varjosta ja jättivät sen.',
        13: 'Sen kaatuneella rungolla asuvat kaikki taivaan linnut, ja sen oksien ääressä oleskelevat kaikki kedon eläimet –',
        14: 'ettei yksikään puu vesien äärellä kasvaisi niin korkeaksi eikä nostaisi latvaansa paksujen oksien keskeltä ja etteivät mahtavimmatkaan niistä, ei mitkään, jotka juovat vettä, olisi korkeudessaan pysyviä, sillä ne ovat kaikki annetut alttiiksi kuolemalle, menemään maan syvyyteen, hautaan vaipuneiden pariin yhdessä ihmislasten kanssa.',
        15: 'Näin sanoo Herra, Herra: Sinä päivänä, jona hän astui alas hautaan, verhosin syvyyden suruun hänen tähtensä, pidätin virrat, niin että paljot vedet pysähtyivät juoksussaan, ja puin Libanonin hänen tähtensä mustiin, ja kaikki kedon puut olivat näännyksissä hänen tähtensä.',
        16: 'Hänen kaatumisensa ryskeestä panin kansakunnat vapisemaan, kun syöksin sen alas hautaan, hautaan vaipuneiden pariin. Mutta lohdutetuiksi tulivat maan syvyydessä kaikki Eedenin puut, Libanonin valiot ja parhaat, kaikki, jotka juovat vettä.',
        17: 'Myös ne astuivat alas hänen kanssaan hautaan, miekalla kaadettujen pariin, samoin hänen auttajansa, ne, jotka istuivat hänen varjossaan kansojen joukossa.',
        18: 'Oliko yksikään Eedenin puista vertaisesi kunniassa ja suuruudessa? Mutta sinut syöstiin Eedenin puiden kanssa alas maan syvyyteen. Ympärileikkaamattomien keskellä makasit miekalla kaadettujen kanssa. Samoin käy faraon ja koko hänen meluavan joukkonsa, sanoo Herra, Herra."',
    },
    32: {
        1: 'Kahdentenatoista vuotena, kahdennessatoista kuussa, kuukauden ensimmäisenä päivänä tuli minulle tämä Herran sana:',
        2: '"Ihmislapsi, viritä itkuvirsi faraosta, Egyptin kuninkaasta, ja sano hänelle: Olet kuin nuori leijona kansojen joukossa, sinä olet kuin lohikäärme meressä, joka pärskyttelet vettä virroissasi, loiskutat vettä jaloillasi ja sotket sen virtoja.',
        3: 'Näin sanoo Herra, Herra: Minä levitän verkkoni päällesi monien kansojen suurella joukolla, ja ne vetävät sinut ylös pyydykselläni.',
        4: 'Heitän sinut maahan kedolle ja panen asumaan päälläsi kaikenlaiset taivaan linnut ja teen sinusta kylläisiksi kaiken maan eläimet.',
        5: 'Annan lihasi vuorille ja täytän suurella ruumiillasi laaksot,',
        6: 'juotan maan sillä, mikä sinusta valuu, verelläsi aina vuorille asti, ja purojen uomat tulevat sinusta täyteen.',
        7: 'Peitän taivaan, kun sinut sammutan, ja pimennän sen tähdet. Auringon peitän pilviin, eikä kuu anna valonsa loistaa.',
        8: 'Kaikki taivaan loistavat valot pimennän takiasi ja teen maasi pimeäksi, sanoo Herra, Herra.',
        9: 'Murehdutan monien kansojen sydämet, kun saatan tiedoksi sinun murskaamisesi kansakunnille, maihin, joita et tuntenut.',
        10: 'Saatan kauhun valtaan sinun tähtesi monet kansat, ja heidän kuninkaansa ovat suuresti peloissaan tähtesi, kun heilutan miekkaani heidän nähtensä, ja he vapisevat joka hetki kukin oman henkensä tähden kukistumisesi päivänä.',
        11: 'Sillä näin sanoo Herra, Herra: Baabelin kuninkaan miekka tulee päällesi.',
        12: 'Kaadan meluisan joukkosi sankarien miekoilla. He kaikki ovat pakanoista julmimpia. He kukistavat Egyptin ylpeyden. Koko sen meluisa joukko tuhotaan.',
        13: 'Hävitän siitä kaiken karjan runsaiden vetten ääreltä. Niitä ei enää tallaa ihmisen jalka eivätkä niitä sotke karjan sorkat.',
        14: 'Silloin annan sen vesien laskeutua kirkkaiksi, ja panen sen virrat juoksemaan kuin öljyn, sanoo Herra, Herra.',
        15: 'Teen Egyptin maan autioksi ja maa tulee autioksi kaikesta, mitä siinä on. Surmaan kaikki sen asukkaat. He tulevat tietämään, että minä olen Herra.',
        16: 'Itkuvirsi tämä on, ja sitä kyllä viritetään. Pakanakansojen tyttäret sitä virittävät. Ne virittävät sitä Egyptistä ja kaikesta sen meluisasta joukosta, sanoo Herra, Herra."',
        17: 'Kahdentenatoista vuotena, kuukauden viidentenätoista päivänä minulle tuli tämä Herran sana:',
        18: '"Ihmislapsi, veisaa kuolinvalitus Egyptin meluisasta joukosta, saata se ja mahtavien pakanakansojen tyttäret alas maan syvyyksiin, hautaan vaipuneiden pariin.',
        19: 'Oletko vielä kaikkia muita ihanampi? Astu alas ja anna laittaa makuusijasi ympärileikkaamattomien pariin.',
        20: 'He kaatuvat miekalla surmattujen joukkoon. Miekka on jo annettu! Temmatkaa pois Egypti kaikkine meluisine joukkoineen.',
        21: "Mahtavimmat sankareista puhuvat hautojen keskeltä sille ja sen auttajille: 'Alas ovat astuneet, siellä makaavat ympärileikkaamattomat, miekalla surmatut.'",
        22: 'Siellä on Assur kaikkine joukkoineen. Niiden haudat ovat hänen ympärillään. Kaikki he ovat surmattuja, miekkaan kaatuneita.',
        23: 'Hänen hautansa ovat pohjimmaisessa kuopassa, ja hänen joukkonsa on hänen hautansa ympärillä. He ovat kaikki surmattuja, miekkaan kaatuneita, nuo, jotka levittivät kauhua elävien maassa.',
        24: 'Siellä on Eelam, ja koko hänen meluisa joukkonsa on hänen hautansa ympärillä. Kaikki he ovat surmattuja, miekkaan kaatuneita, jotka ympärileikkaamattomina astuivat alas maan syvyyksiin, nuo, jotka levittivät kauhuaan elävien maassa, mutta kantavat häpeäänsä hautaan vaipuneiden parissa.',
        25: 'Surmattujen keskellä on makuusija annettu hänelle sekä kaikelle hänen meluisalle joukolleen. Niiden haudat ovat hänen ympärillään. Kaikki tyynni ne ovat ympärileikkaamattomia, miekalla surmattuja, sillä he olivat kauhuna elävien maassa, mutta saavat kantaa häpeänsä hautaan vaipuneitten parissa. Surmattujen keskelle on hänet pantu.',
        26: 'Siellä on Mesek-Tuubal kaikkine meluisine joukkoineen. Niiden haudat ovat hänen ympärillään. He ovat kaikki ympärileikkaamattomia, miekalla surmattuja, sillä ne levittivät kauhuaan elävien maassa.',
        27: 'He eivät makaa sankarien parissa, jotka ovat kaatuneet ympärileikkaamattomien joukosta, jotka ovat astuneet alas hautaan sota-aseineen, joiden pään alle on pantu heidän miekkansa ja joiden luiden päällä on heidän syntivelkansa, sillä sankarien kauhu oli elävien maassa.',
        28: 'Sinutkin muserretaan ympärileikkaamattomien joukossa, ja saat maata miekalla surmattujen parissa.',
        29: 'Siellä on Edom, sen kuninkaat ja kaikki sen ruhtinaat, jotka sankaruudessaan pantiin miekalla surmattujen pariin. He makaavat ympärileikkaamattomien ja hautaan vaipuneiden parissa.',
        30: 'Siellä ovat kaikki pohjoisen maan ruhtinaat ja kaikki siidonilaiset, jotka ovat astuneet surmattujen pariin kauhistavuudessaan, ovat tulleet häpeään sankaruudessaan ja makaavat ympärileikkaamattomina miekalla surmattujen parissa ja saavat kantaa häpeänsä hautaan vaipuneiden parissa.',
        31: 'Heidät on farao näkevä ja tuleva lohdutetuksi kaikesta meluisasta joukostaan. Miekalla on surmattu farao kaikkine sotaväkineen, sanoo Herra, Herra.',
        32: 'Sillä levitin hänen kauhuaan elävien maassa, mutta faraolle ja kaikelle hänen meluisalle joukolleen laitetaan makuusija ympärileikkaamattomien sekaan, miekalla surmattujen pariin, sanoo Herra, Herra."',
    },
    33: {
        1: 'Minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Ihmislapsi, puhu kansasi lapsille ja sano heille: Jos annan miekan tulla maan kimppuun ja maan kansa on ottanut yhden miehen joukostaan ja asettanut hänet vartijakseen',
        3: 'ja jos hän näkee miekan tulevan maan kimppuun ja puhaltaa torveen ja varoittaa kansaa,',
        4: 'ja joku kuulee torven äänen, mutta ei ota varoituksesta vaarin, ja miekka tulee ja ottaa hänet pois, niin hänen verensä tulee hänen oman päänsä päälle:',
        5: 'hän kuuli torven äänen, mutta ei ottanut varoituksesta vaarin; hänen verensä tulee hänen päälleen. Jos hän olisi ottanut varoituksesta vaarin, hän olisi pelastanut sielunsa.',
        6: 'Jos taas vartija näkee miekan tulevan, mutta ei puhalla torveen eikä kansa saa varoitusta, ja miekka tulee ja ottaa pois jonkun sielun heistä, hänet otettiin pois synnissään, mutta hänen verensä vaadin vartijan kädestä.',
        7: 'Mutta sinä, ihmislapsi! Olen asettanut sinut Israelin heimolle vartijaksi. Kun kuulet sanan suustani, sinun on varoitettava heitä minun puolestani.',
        8: 'Jos sanon jumalattomalle: jumalaton, sinun on kuolemalla kuoltava, mutta et puhu varoittaaksesi jumalatonta hänen tiestään, niin jumalaton kuolee synnissään, mutta hänen verensä vaadin sinun kädestäsi.',
        9: 'Mutta jos varoitat jumalatonta hänen tiestään, että hän kääntyisi siltä pois, eikä hän tieltään käänny, hän kuolee synnissään, mutta sinä olet sielusi pelastanut.',
        10: "Sinä, ihmislapsi! Sano Israelin heimolle: Näin te sanotte: 'Niin, rikoksemme ja syntimme ovat päällämme, ja riudumme niiden tähden. Kuinka voisimme pysyä elossa?'",
        11: 'Sano heille: Niin totta kuin minä elän, sanoo Herra, Herra, minulle ei ole mieleen jumalattoman kuolema, vaan se, että jumalaton kääntyy tieltään ja elää. Kääntykää, kääntykää pois pahoilta teiltänne, ja minkä tähden te kuolisitte, Israelin heimo!',
        12: 'Mutta sinä, ihmislapsi! Sano kansasi lapsille: Vanhurskasta ei pelasta hänen vanhurskautensa sinä päivänä, jona hän rikkoo, ja jumalaton pääsee suistumasta turmioon jumalattomuutensa tähden sinä päivänä, jona hän kääntyy pois jumalattomuudestaan, ja vanhurskas ei voi elää vanhurskautensa turvin sinä päivänä, jona hän syntiä tekee.',
        13: 'Jos sanon vanhurskaalle, että hän totisesti on elävä, mutta hän luottaa vanhurskauteensa ja tekee vääryyttä, hänen vanhurskauttaan ei muisteta, vaan hän kuolee vääryydessään, jota on tehnyt.',
        14: 'Mutta jos sanon jumalattomalle, että hänen totisesti on kuoltava, mutta hän kääntyy pois synnistään ja tekee oikeuden ja vanhurskauden,',
        15: 'antaa takaisin, tuo jumalaton, pantin, korvaa riistämänsä ja vaeltaa elämän käskyjen mukaan, niin ettei tee vääryyttä, totisesti hän tulee elämään, hänen ei ole kuoltava.',
        16: 'Hänen syntejään, jotka hän on tehnyt, ei lainkaan muisteta: hän on tehnyt oikeuden ja vanhurskauden, hän totisesti on elävä.',
        17: "Mutta vielä sinun kansasi lapset sanovat: ' Herran tie ei ole oikea.' Juuri heidän omat tiensä eivät ole oikeat.",
        18: 'Jos vanhurskas kääntyy pois vanhurskaudestaan ja tekee vääryyttä, hänen on sen tähden kuoltava.',
        19: 'Jos taas jumalaton kääntyy pois jumalattomuudestaan ja tekee oikeuden ja vanhurskauden, hän on sen tähden elävä.',
        20: 'Mutta sanotte: \' Herran tie ei ole oikea\': minä tuomitsen teidät, te Israelin heimo, itse kunkin hänen teittensä mukaan."',
        21: 'Kahdentenatoista karkotuksemme vuotena, kymmenennessä kuussa, kuukauden viidentenä päivänä tuli luokseni pakolainen Jerusalemista ja sanoi: "Kaupunki on vallattu."',
        22: 'Herran käsi oli tullut päälleni jo illalla ennen pakolaisen tuloa, ja hän avasi suuni ennen tämän tuloa aamulla. Suuni avautui, enkä enää ollut mykkänä.',
        23: 'Minulle tuli tämä Herran sana, ja se kuului:',
        24: '"Ihmislapsi, ne, jotka asuvat noilla raunioilla Israelin maassa, sanovat näin: \'Aabraham oli vain yksi, ja hän peri maan. Meitä on paljon, meille on annettu maa perinnöksi.\'',
        25: 'Sano sen tähden heille: Näin sanoo Herra, Herra: Te syötte lihaa verineen, luotte silmänne epäjumaliinne ja vuodatatte verta. Tekö perisitte maan?',
        26: 'Seisotte miekkanne varassa, harjoitatte kauhistuksia ja saastutatte toistenne vaimoja, ja tekö perisitte maan?',
        27: 'Näin on sinun heille sanottava: Näin sanoo Herra, Herra: Niin totta kuin minä elän, niin ne, jotka ovat raunioilla, kaatuvat miekkaan, ja ne, jotka ovat kedolla, annan eläinten syötäväksi, ja ne, jotka ovat vuorenhuipuilla ja luolissa, kuolevat ruttoon.',
        28: 'Teen maan autioksi ja hävitetyksi, ja heidän ylpeästä mahdistaan tulee loppu, ja Israelin vuoret joutuvat autioiksi, niin ettei siellä kulje kukaan.',
        29: 'He tulevat tietämään, että minä olen Herra, kun teen maan autioksi ja hävitetyksi kaikkien kauhistusten tähden, joita he ovat harjoittaneet.',
        30: "Sinä, ihmislapsi! Sinun kansasi lapset puhuvat sinusta seinänvierustoilla ja talojen ovilla ja sanovat keskenään toisilleen, näin: 'Lähtekää kuulemaan, millainen sana nyt on tullut Herralta.'",
        31: 'He tulevat luoksesi joukoittain, istuvat edessäsi kansanani ja kuuntelevat sanojasi, mutta he eivät tee niiden mukaan, sillä he osoittavat rakkautta suullaan, mutta heidän sydämensä kulkee väärän voiton perässä.',
        32: 'Katso, sinä olet heille kuin ilolaulu, kauniisti laulettu ja hyvin soitettu. He tosin sanojasi kuuntelevat, mutta eivät tee niiden mukaan.',
        33: 'Mutta kun se toteutuu – ja katso, se toteutuu – he tulevat tietämään, että heidän keskuudessaan on ollut profeetta."',
    },
    34: {
        1: 'Minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Ihmislapsi, profetoi Israelin paimenia vastaan, profetoi ja sano heille, paimenille: Näin sanoo Herra, Herra: Voi Israelin paimenia, jotka ovat olleet itsensä paimenia! Eikö paimenten ole kaittava lampaita?',
        3: 'Te olette syöneet rasvat, pukeneet päällenne villat, teurastaneet lihavat; mutta lampaita ette ole kainneet,',
        4: 'ette ole vahvistaneet heikkoja, ette ole parantaneet sairaita, sitoneet haavoittuneita, tuoneet takaisin eksyneitä ettekä etsineet kadonneita, vaan olette vallinneet niitä tylysti ja väkivaltaisesti.',
        5: 'Ne ovat hajaantuneet paimenta vailla ja joutuneet kaikkien kedon eläinten syötäviksi. Hajaantuneet ne ovat.',
        6: 'Lampaani harhailevat kaikilla vuorilla ja kaikilla korkeilla kukkuloilla. Pitkin koko maata lampaani ovat hajallaan, eikä kukaan välitä niistä eikä etsi niitä.',
        7: 'Sen tähden, paimenet, kuulkaa Herran sana:',
        8: 'Niin totta kuin minä elän, sanoo Herra, Herra, totisesti, koska lampaani ovat ryöstettävinä ja koska lampaani ovat kaikkien kedon eläinten syötävinä, kun paimenta ei ole ja kun paimeneni eivät etsi lampaitani, vaan paimeneni kaitsevat itseään, eivätkä kaitse minun lampaitani,',
        9: 'sen tähden, paimenet, kuulkaa Herran sana:',
        10: 'Näin sanoo Herra, Herra: Katso, minä olen paimenia vastaan, vaadin lampaani heidän kädestään ja teen lopun heidän lammasten kaitsennastaan, eivätkä paimenet saa enää kaita itseään. Minä pelastan lampaani heidän suustaan, eivätkä ne sitten enää ole heidän syötävinään.',
        11: 'Sillä näin sanoo Herra, Herra: Katso, minä itse etsin lampaani ja pidän niistä huolen',
        12: 'Niin kuin paimen pitää huolen laumastaan, kun hän on lampaittensa keskellä ja ne ovat hajallaan, niin minä pidän huolen lampaistani ja pelastan ne joka paikasta, minne ne ovat hajaantuneet pilvisenä ja pimeänä päivänä.',
        13: 'Vien ne pois kansakuntien joukosta ja kokoan ne kaikista maista, tuon ne maahansa ja kaitsen niitä Israelin vuorilla, purojen varsilla ja kaikissa maan asuttavissa paikoissa.',
        14: 'Hyvillä laitumilla niitä kaitsen, ja Israelin korkeilla vuorilla niillä on oleva laitumensa. Siellä ne saavat levätä hyvällä laitumella, ja lihava ruokamaa niillä on oleva Israelin vuorilla.',
        15: 'Minä itse kaitsen lampaani ja vien itse ne lepäämään, sanoo Herra, Herra.',
        16: 'Etsin kadonneet, eksyneet tuon takaisin, haavoittuneet sidon, heikkoja vahvistan, mutta lihavat ja väkevät minä hävitän. Kaitsen niitä niin, kuin oikein on.',
        17: 'Mutta te, minun lampaani! Näin sanoo Herra, Herra: Katso, tuomitsen lampaan ja lampaan, pässien ja vuohipukkien välillä.',
        18: 'Eikö teille riitä, että olette hyvällä laitumella, kun vielä tallaatte jaloillanne loput laitumestanne, ja se, että juotte kirkasta vettä, kun vielä sekoitatte jaloillanne loput?',
        19: 'Lampaani käyvät laitumella siinä, mitä jalkanne ovat tallanneet, ja juovat sitä, minkä jalkanne ovat sotkeneet.',
        20: 'Sen tähden sanoo Herra, Herra niille näin: Katso, minä, minä tuomitsen lihavan lampaan ja laihan lampaan välillä.',
        21: 'Koska te sysitte kyljillänne ja hartioillanne sekä puskette sarvillanne kaikkia heikkoja, kunnes olette saaneet ne ajetuiksi ulos ja hajalle,',
        22: 'niin pelastan lampaani, etteivät ne enää ole ryöstettävinä, ja tuomitsen lampaan ja lampaan välillä.',
        23: 'Herätän heille yhden paimenen heitä kaitsemaan, palvelijani Daavidin. Hän on kaitseva heitä ja oleva heidän paimenensa.',
        24: 'Minä, Herra, olen heidän Jumalansa, ja palvelijani Daavid on ruhtinas heidän keskellään. Minä, Herra, olen puhunut.',
        25: 'Teen heidän kanssaan rauhan liiton. Lopetan maasta pahat eläimet, niin että he asuvat turvallisesti erämaassa ja nukkuvat metsiköissä.',
        26: 'Teen siunatuiksi heidät ja kaiken, mitä on kukkulani ympärillä, ja vuodatan sateen ajallaan. Ne ovat siunauksen sateita.',
        27: 'Kedon puut kantavat hedelmänsä, ja maa antaa satonsa, ja he saavat olla turvassa maassaan. He tulevat tietämään, että minä olen Herra, kun särjen heidän ikeensä puut ja pelastan heidät heidän orjuuttajiensa käsistä.',
        28: 'Eivätkä he enää ole pakanoiden ryöstettävinä, eivätkä maan eläimet heitä syö, vaan he asuvat turvassa, kenenkään pelottelematta.',
        29: 'Annan nousta heille istutuksen, joka on oleva kunniaksi, niin etteivät he menehdy siinä maassa nälkään eivätkä enää kärsi pakanoiden pilkkaa.',
        30: 'He tulevat tietämään, että minä, Herra, heidän Jumalansa, olen heidän kanssaan ja että he, Israelin heimo, ovat kansani, sanoo Herra, Herra.',
        31: 'Te olette lampaani, laitumeni lampaat, te ihmiset. Minä olen Jumalanne, sanoo Herra, Herra."',
    },
    35: {
        1: 'Minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Ihmislapsi, käännä kasvosi Seirin vuorta kohti ja profetoi sitä vastaan',
        3: 'ja sano sille: Näin sanoo Herra, Herra: Katso, minä käyn kimppuusi, Seirin vuori, ojennan käteni sinua vastaan ja teen sinut autioksi ja hävitetyksi.',
        4: 'Kaupunkisi teen raunioiksi ja sinä itse tulet autioksi. Tulet tietämään, että minä olen Herra.',
        5: 'Koska pidit ikuista vihaa ja annoit israelilaiset alttiiksi miekalle heidän onnettomuutensa aikana, aikana, jolloin syntivelka tuli viimeiseen määräänsä,',
        6: 'sen tähden, niin totta kuin minä elän, sanoo Herra, Herra, teen sinut verta vuotavaksi, ja veri on sinua vainoava. Koska totisesti et kammonnut verta, veri on vainoava sinua.',
        7: 'Teen Seirin vuoren tyhjäksi ja autioksi ja hävitän sieltä menijän ja tulijan.',
        8: 'Sen vuoret täytän sen surmatuilla. Miekalla surmattuja kaatuu kukkuloillasi ja laaksoissasi ja kaikilla purojesi varsilla.',
        9: 'Teen sinut ikuisesti autioksi, ja kaupunkisi jäävät asumattomiksi. Tulette tietämään, että minä olen Herra.',
        10: "Koska sinä olet sanonut: 'Ne kaksi kansaa ja kaksi maata ovat minun, otamme ne omiksemme', vaikka siellä on Herra,",
        11: 'sen tähden, niin totta kuin minä elän, sanoo Herra, Herra, teen vihasi ja kiivautesi mukaan, teen sen, minkä sinä vihassasi olet heille tehnyt. Teen itseni heille tunnetuksi, kun tuomitsen sinut,',
        12: "ja sinä tulet tietämään, että minä olen Herra. Olen kuullut kaikki pilkkaamisesi, jotka olet puhunut Israelin vuoria vastaan, kun olet sanonut: 'Ne ovat autioina, ne ovat annetut meille syötäviksi.'",
        13: 'Te suurentelitte minua vastaan suullanne, ja ylenpalttiset olivat teidän puheenne minua vastaan. Olen ne kuullut.',
        14: 'Näin sanoo Herra, Herra: Iloksi kaikelle maalle teen sinut autioksi.',
        15: 'Niin kuin iloitsit Israelin heimon perintöosasta, kun se tuli autioksi, niin teen minäkin sinulle. Autioksi tulet sinä, Seirin vuori, samoin koko Edom kaikkineen. He tulevat tietämään, että minä olen Herra."',
    },
    36: {
        1: '"Sinä, ihmislapsi, profetoi Israelin vuorista ja sano:',
        2: "Israelin vuoret, kuulkaa Herran sana: Näin sanoo Herra, Herra: Koska vihollinen on sanonut teistä: 'Kas noin!' ja: 'Ikuiset kukkulat ovat tulleet omistukseemme',",
        3: 'sen tähden profetoi ja sano: Näin sanoo Herra, Herra: Koska – niin, koska teitä on hävitetty ja poljettu joka taholta, että joutuisitte muiden kansojen omaisuudeksi, ja koska olette joutuneet pahojen kielten ja kansan panettelun alaisiksi, –',
        4: 'sen tähden, Israelin vuoret, kuulkaa Herran, Herran sana: Näin sanoo Herra, Herra vuorille ja kukkuloille, puronvarsille ja laaksoille, autioille raunioille ja hylätyille kaupungeille, jotka ovat joutuneet saaliiksi ja pilkaksi muille kansoille, mitä ympärillä on.',
        5: 'Sen tähden sanoo Herra, Herra näin: Totisesti, kiivauteni tulessa puhun muita kansoja vastaan ja koko Edomia vastaan, jotka ovat kaikesta sydämestään iloiten ja sielu täynnä halveksuntaa ottaneet omakseen maani karkottaakseen siitä ihmiset ja ryöstääkseen sen.',
        6: 'Sen tähden profetoi Israelin maasta ja sano vuorille ja kukkuloille, puronvarsille ja laaksoille: Näin sanoo Herra, Herra: Katso, puhun kiivaudessani ja vihassani, koska teidän täytyy kärsiä pakanoiden pilkkaa.',
        7: 'Sen tähden, näin sanoo Herra, Herra: Minä kohotan käteni. Totisesti pakanakansat ympärillänne itse kärsivät oman pilkkansa.',
        8: 'Mutta te, Israelin vuoret, teette lehvänne ja kannatte hedelmänne kansalleni Israelille, sillä he ovat aivan lähellä tulossa.',
        9: 'Sillä katso, tulen luoksenne ja käännyn puoleenne, ja teidät viljellään ja teihin kylvetään.',
        10: 'Lisään teille ihmisiä runsaasti – koko Israelin heimolle kokonaan – ja kaupungit asutetaan ja rauniot rakennetaan.',
        11: 'Lisään teille ihmisiä ja karjaa runsaasti, ja ne lisääntyvät ja ovat hedelmälliset. Teen teidät asutuiksi, niin kuin olitte entisinä päivinänne, ja teen hyvää vielä enemmän kuin alkuaikoina. Tulette tietämään, että minä olen Herra.',
        12: 'Tuon luoksenne, kansaani Israeliin, ihmisiä, ja he ottavat sinut omakseen, ja tulet heille perintöosaksi, etkä enää tästä lähin riistä heidän lapsiaan.',
        13: "Näin sanoo Herra, Herra: Koska teille on sanottu: 'Sinä olet ihmissyöjä ja oman kansasi lasten riistäjä',",
        14: 'sen tähden et ole enää syövä ihmisiä etkä enää riistävä lapsia omalta kansaltasi, sanoo Herra, Herra.',
        15: 'Enkä enää anna sinun joutua kuulemaan pakanakansojen pilkkaa, etkä kärsi kansojen herjauksia, etkä enää myöskään pane omaa kansaasi kompastumaan, sanoo Herra, Herra."',
        16: 'Minulle tuli tämä Herran sana, ja se kuului:',
        17: '"Ihmislapsi, kun Israelin heimo asui maassaan, he saastuttivat sen vaelluksellaan ja teoillaan. Heidän vaelluksensa oli edessäni kuin kuukautistilan saastaisuus.',
        18: 'Vuodatin kiivauteni heidän päälleen veren tähden, jota he olivat vuodattaneet maassa, ja heidän epäjumaliensa tähden, joilla he olivat sen saastuttaneet.',
        19: 'Hajotin heidät pakanakansojen sekaan, ja heidät siroteltiin kaikkiin maihin. Vaelluksensa ja tekojensa mukaan heidät tuomitsin.',
        20: "He tulivat pakanakansojen sekaan. Minne tulivatkin, he häpäisivät pyhän nimeni, kun heistä sanottiin: 'Nämä ovat Herran kansa, mutta he ovat lähteneet pois hänen maastaan.'",
        21: 'Minun tuli sääli pyhää nimeäni, jonka Israelin heimo saastutti pakanakansojen seassa, minne tulivatkin.',
        22: 'Sen tähden sano Israelin heimolle: Näin sanoo Herra, Herra: Minä en tee teidän tähtenne, Israelin heimo, sitä minkä teen, vaan oman pyhän nimeni tähden, jonka olette häväisseet pakanakansojen seassa, minne tulittekin.',
        23: 'Pyhitän suuren nimeni, joka on häväisty pakanakansojen keskuudessa, jonka olette häväisseet heidän keskellään. Pakanakansat tulevat tietämään, että minä olen Herra, sanoo Herra, Herra, kun osoitan teissä pyhyyteni heidän silmiensä edessä.',
        24: 'Otan teidät pois pakanakansoista ja kokoan teidät kaikista maista ja tuon teidät maahanne.',
        25: 'Vihmon päällenne puhdasta vettä, niin että puhdistutte. Kaikista saastaisuuksistanne ja kaikista epäjumalistanne teidät puhdistan.',
        26: 'Annan teille uuden sydämen, ja uuden Hengen annan teidän sisimpäänne. Poistan ruumiistanne kivisydämen ja annan teille lihasydämen.',
        27: 'Henkeni annan sisimpäänne ja vaikutan sen, että vaellatte käskyjeni mukaan, noudatatte oikeuksiani ja pidätte ne.',
        28: 'Asutte maassa, jonka annoin teidän isillenne, ja olette kansani, ja minä olen Jumalanne.',
        29: 'Vapautan teidät kaikista saastaisuuksistanne. Kutsun esiin viljan ja teen sen runsaaksi enkä anna teille nälänhätää.',
        30: 'Teen runsaaksi puiden hedelmän ja pellon sadon, niin ettette enää tule herjatuiksi kansojen seassa nälän takia.',
        31: 'Muistatte väärät tienne ja tekonne, jotka eivät olleet hyvät, ja teitä inhottaa oma itsenne rikostenne ja kauhistustenne tähden.',
        32: 'En tee sitä teidän tähtenne, sanoo Herra, Herra. Se olkoon teille tiettävä. Hävetkää ja punastukaa vaelluksenne tähden, te Israelin heimo.',
        33: 'Näin sanoo Herra, Herra: Sinä päivänä, jona teidät puhdistan kaikista pahoista teoistanne, asutan kaupungit, ja rauniot rakennetaan,',
        34: 'ja autiomaa viljellään, sen sijaan että se on ollut autiona jokaisen ohikulkijan silmien edessä.',
        35: "Silloin sanotaan: 'Tästä maasta, joka oli autiona, on tullut kuin Eedenin puutarha. Raunioina olleet, autiot ja maahan revityt kaupungit ovat varustettuja ja asuttuja.'",
        36: 'Pakanakansat tulevat, joita on jäljellä ympärillänne, tietämään, että minä, Herra, rakennan jälleen alasrevityn ja istutan aution: minä, Herra, olen puhunut, ja minä teen sen.',
        37: 'Näin sanoo Herra, Herra: Vielä tätäkin annan Israelin heimon minulta anoa, että tekisin heille sen. Lisään heille ihmisiä runsaasti kuin lammaslaumaa.',
        38: 'Niin kuin on pyhitettyjen uhrilammasten laumaa, niin kuin on Jerusalemin lammaslaumaa sen kokouksissa, niin tulevat raunioina olleet kaupungit täyteen ihmislaumoja. He tulevat tietämään, että minä olen Herra."',
    },
    37: {
        1: 'Herran käsi oli päälläni ja vei minut pois Herran Hengessä ja laski minut keskelle laaksoa, joka oli täynnä luita.',
        2: 'Hän kuljetti minua ympäriinsä niiden ohi, ja katso, niitä oli hyvin paljon laaksossa maan päällä, ja katso, ne olivat hyvin kuivia.',
        3: 'Hän sanoi minulle: "Ihmislapsi, voivatkohan nämä luut tulla eläviksi?" Mutta minä sanoin: "Herra, Herra, sinä sen tiedät."',
        4: 'Niin hän sanoi minulle: "Profetoi näistä luista ja sano niille: Kuivat luut, kuulkaa Herran sana.',
        5: 'Näin sanoo Herra, Herra näille luille: Katso, minä annan tulla teihin hengen, ja te tulette eläviksi.',
        6: 'Panen teihin jänteet, kasvatan teihin lihan, vedän yllenne nahan ja annan teihin hengen, ja te tulette eläviksi. Tulette tietämään, että minä olen Herra."',
        7: 'Sitten lausuin profetian, kuten minua oli käsketty. Kuului ääni, kun profetoin. Katso, järinää, ja luut lähestyivät toisiaan, luu luuta.',
        8: 'Näin, ja katso: niihin tulivat jänteet ja kasvoi liha, ja niiden päälle kasvoi nahka, mutta henkeä niissä ei ollut.',
        9: 'Hän sanoi minulle: "Profetoi Hengestä, profetoi, ihmislapsi, ja sano Hengelle: Näin sanoo Herra, Herra: Tule, Henki, neljästä tuulesta ja puhalla näihin surmattuihin, että ne tulisivat eläviksi."',
        10: 'Profetoin, niin kuten hän oli minua käskenyt, ja niihin tuli henki, ja ne tulivat eläviksi ja nousivat ylös jaloilleen. Niitä oli tavattoman suuri joukko.',
        11: 'Hän sanoi minulle: "Ihmislapsi, nämä luut ovat koko Israelin heimo. Katso, he sanovat: \'Meidän luumme ovat kuivettuneet, toivomme on mennyttä, olemme hukassa.\'',
        12: 'Sen tähden profetoi ja sano heille: Näin sanoo Herra, Herra: Katso, minä avaan hautanne ja nostan teidät, kansani, ylös haudoistanne ja vien teidät Israelin maahan.',
        13: 'Siitä te tulette tietämään, että minä olen Herra, kun minä avaan hautanne ja nostan teidät, kansani, ylös haudoistanne.',
        14: 'Annan teihin Henkeni, niin että te tulette eläviksi, ja sijoitan teidät maahanne. Te tulette tietämään, että minä olen Herra. Olen puhunut, ja sen teen, sanoo Herra."',
        15: 'Minulle tuli tämä Herran sana, ja se kuului:',
        16: '"Sinä, ihmislapsi, ota puusauva ja kirjoita siihen: \'Juudalle ja häneen liittyneille israelilaisille.\' Ota sitten toinen puusauva ja kirjoita siihen: \'Joosefille; Efraimin ja kaiken häneen liittyneen Israelin heimon sauva.\'',
        17: 'Yhdistä ne toisiinsa, niin että ne tulevat yhdeksi kädessäsi.',
        18: "Kun sitten kansasi lapset sanovat sinulle näin: 'Etkö ilmoita meille, mitä tällä tarkoitat?'",
        19: 'puhu heille: Näin sanoo Herra, Herra: Katso, minä otan Joosefin sauvan, joka on Efraimin kädessä, ja häneen liittyneet Israelin sukukunnat, ja asetan ne yhteen Juudan sauvan kanssa ja teen niistä yhden sauvan, niin että ne tulevat yhdeksi minun kädessäni.',
        20: 'Kun sauvat, joihin olet kirjoittanut, ovat kädessäsi, heidän silmiensä edessä,',
        21: 'puhu heille: Näin sanoo Herra, Herra: Katso, minä otan israelilaiset pois pakanoiden keskuudesta, minne vain he ovat kulkeneet, kokoan heidät joka taholta ja tuon heidät maahansa.',
        22: 'Teen heidät yhdeksi kansaksi siinä maassa, Israelin vuorilla, ja yksi kuningas on oleva kuninkaana heillä kaikilla. Eivätkä he enää ole kahtena kansana eivätkä enää jakaantuneina kahdeksi valtakunnaksi.',
        23: 'He eivät myöskään enää saastuta itseään epäjumalillaan, iljetyksillään eivätkä millään rikoksillaan, vaan pelastan heidät heidän kaikista asuinpaikoistaan, joissa he ovat syntiä tehneet, ja puhdistan heidät. He ovat kansani, ja minä olen heidän Jumalansa.',
        24: 'Palvelijani Daavid on oleva heidän kuninkaansa, ja heillä kaikilla on oleva yksi paimen. Silloin he vaeltavat oikeuksieni mukaan ja noudattavat käskyjäni ja pitävät ne.',
        25: 'He asuvat maassa, jonka annoin palvelijalleni Jaakobille ja jossa teidän isänne ovat asuneet. He, heidän lapsensa ja lastensa lapset asuvat siinä iankaikkisesti, ja palvelijani Daavid on oleva heidän ruhtinaansa iankaikkisesti.',
        26: 'Teen heidän kanssaan rauhan liiton – se on oleva iankaikkinen liitto heidän kanssaan – istutan ja runsaasti kartutan heidät ja asetan pyhäkköni olemaan heidän keskellään iankaikkisesti.',
        27: 'Asumukseni on oleva heidän luonaan, ja olen heidän Jumalansa, ja he ovat kansani.',
        28: 'Pakanat tulevat tietämään, että minä olen Herra, joka pyhitän Israelin, kun pyhäkköni on heidän keskellään iankaikkisesti."',
    },
    38: {
        1: 'Minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Ihmislapsi, käännä kasvosi kohti Googia Maagogin maassa, Roosin, Mesekin ja Tuubalin ruhtinasta, ja profetoi häntä vastaan',
        3: 'ja sano: Näin sanoo Herra, Herra: Katso, käyn kimppuusi, Goog, sinä Roosin, Mesekin ja Tuubalin ruhtinas.',
        4: 'Kuljetan sinua, panen koukut leukaasi ja nostatan sotaan sinut ja kaiken sotaväkesi: hevoset ja ratsumiehet, kaikki loisteliaasti puettuja, suuren joukon suurine ja pienine kilpineen, miekankantajia kaikki.',
        5: 'Persia, Kuus ja Puut ovat heidän kanssaan, heillä kaikilla on kilvet ja kypärät.',
        6: 'Goomer ja kaikki sen sotajoukot, Toogarman heimo pohjoisesta ja kaikki sen sotajoukot – lukuisat kansat ovat kanssasi.',
        7: 'Ole valmis, varustaudu, sinä ja kaikki joukkosi, jotka ovat kokoontuneet luoksesi, ja ole sinä niiden vartija.',
        8: 'Monien päivien jälkeen saat määräyksen tulla vuosien lopulla maahan, joka on palautunut miekan jäljiltä ja koottu monien kansojen seasta, – mennä Israelin vuorille, jotka kauan aikaa ovat olleet raunioina. Se on tuotu pois kansojen seasta, ja he kaikki asuvat turvassa.',
        9: 'Käyt päälle kuin rajuilma ja tulet kuin pilvi peittääksesi maan, sinä ja kaikki sotajoukkosi ja lukuisat kansat, jotka ovat kanssasi.',
        10: 'Näin sanoo Herra, Herra: Mutta sinä päivänä nousee mieleesi jotakin, ja mietit pahan juonen',
        11: 'ja sanot: Hyökkään avoimeen maahan, käyn rauhallisten ihmisten kimppuun, jotka asuvat turvallisina – asuvat ilman muuria kaikki tyynni, ja joilla ei ole salpoja eikä ovia.',
        12: 'Etsit saalista ja ryöstettävää sekä ojennat kätesi raunioita kohti, jotka on saatu asutuiksi, ja kansaa kohti, joka on koottu pakanoiden seasta, joka on hankkinut karjaa ja omaisuutta ja asuu keskellä maata.',
        13: "Saba ja Dedan ja Tarsiin kauppiaat ja kaikki heidän nuoret leijonansa kyselevät sinulta: 'Oletko sinä menossa saalista saamaan, ryöstettävää ryöstämään? Oletko koonnut joukkosi kantamaan hopeaa ja kultaa, ottamaan karjaa ja omaisuutta, saamaan suurta saalista?'",
        14: 'Sen tähden profetoi, ihmislapsi, ja sano Googille: Näin sanoo Herra, Herra: Eikö niin? Sinä päivänä sinä huomaat, että kansani Israel asuu turvassa,',
        15: 'ja lähdet asuinpaikastasi pohjoisesta, sinä ja monet kansat kanssasi, jotka kaikki ratsastavat hevosilla: suuri joukko, monilukuinen sotajoukko.',
        16: 'Hyökkäät kansani Israelin kimppuun kuin pilvi peittääksesi maan. Päivien lopulla tämä tapahtuu. Annan sinun karata maahani, että pakanakansat tulisivat tuntemaan minut, kun osoitan pyhyyteni sinussa, Goog, heidän silmiensä edessä.',
        17: 'Näin sanoo Herra, Herra: Etkö se ole sinä, josta muinaisina päivinä puhuin palvelijoitteni, Israelin profeettojen, kautta, jotka niinä päivinä profetoivat vuodesta toiseen, että annan sinun käydä heidän kimppuunsa?',
        18: 'Mutta sinä päivänä, jona Goog menee Israelin maahan, sanoo Herra, Herra, nousee vihani hehku.',
        19: 'Kiivaudessani, vihani tulessa sanon: Totisesti sinä päivänä tulee suuri maanjäristys Israelin maahan.',
        20: 'Minun edessäni vapisevat meren kalat ja taivaan linnut ja kedon eläimet ja kaikki maassa liikkuvat matelijat ja kaikki ihmiset, jotka maan pinnalla ovat. Vuoret luhistuvat, ja vuorenrinteet sortuvat, ja kaikki muurit sortuvat maahan.',
        21: 'Kutsun häntä vastaan kaikille vuorilleni miekan, sanoo Herra, Herra. Toisen miekka on oleva toista vastaan.',
        22: 'Käyn oikeutta hänen kanssaan rutolla ja verellä. Annan sataa kaatosadetta, raekiviä, tulta ja laavaa hänen päälleen, hänen sotajoukkojensa päälle ja lukuisten kansojen päälle, jotka ovat hänen kanssaan.',
        23: 'Osoitan suuruuteni ja pyhyyteni sekä teen itseni tunnetuksi monien pakanakansojen silmien edessä. He tulevat tietämään, että minä olen Herra."',
    },
    39: {
        1: '"Sinä, ihmislapsi, profetoi Googia vastaan ja sano: Näin sanoo Herra, Herra: Katso, tulen luoksesi, Goog, sinä Roosin, Mesekin ja Tuubalin ruhtinas.',
        2: 'Tuon sinut, talutan sinua, nostatan sinut pohjoisen puolelta ja annan sinun tulla Israelin vuorille.',
        3: 'Mutta lyön pois jousesi vasemmasta kädestäsi ja pudotan nuolesi oikeasta kädestäsi.',
        4: 'Israelin vuorille sinä olet kaatuva, samoin kaikki sotajoukkosi ja kansat, jotka ovat kanssasi: annan sinut ruuaksi petolinnuille, kaikille siivekkäille ja kedon eläimille.',
        5: 'Kedolle sinä kaadut. Sillä minä olen puhunut, sanoo Herra, Herra.',
        6: 'Lähetän tulen Maagogiin ja rannikolla turvassa asuvien keskuuteen. Silloin he tulevat tietämään, että minä olen Herra.',
        7: 'Pyhän nimeni teen tunnetuksi kansani Israelin keskuudessa enkä enää salli häväistä pyhää nimeäni. Pakanat tulevat tietämään, että minä olen Herra, Israelin Pyhä.',
        8: 'Katso, se tulee, se tapahtuu, sanoo Herra, Herra. Se tapahtuu sinä päivänä, josta olen puhunut.',
        9: 'Israelin kaupunkien asukkaat menevät ulos ja sytyttävät ja polttavat aseita, pieniä ja suuria kilpiä, jousia, nuolia, nuijia ja keihäitä. He pitävät niitä polttopuina seitsemän vuotta.',
        10: 'He eivät kanna puita kedolta eivätkä hakkaa metsistä, vaan pitävät polttopuinaan aseita. Näin he saalistavat saalistajiaan ja ryöstävät ryöstäjiään, sanoo Herra, Herra.',
        11: "Sinä päivänä annan Googille siellä, Israelissa, hautapaikan, 'Kulkijain laakson', itää kohden merestä. Se sulkee tien noilta kulkijoilta. Sinne haudataan Goog ja koko hänen meluisa joukkonsa, ja sille pannaan nimeksi: 'Googin meluisan joukon laakso.'",
        12: 'Israelin heimo hautaa heitä seitsemän kuukautta puhdistaakseen maan.',
        13: 'Koko maan kansa hautaa heitä, ja se on koituva heille kiitokseksi sinä päivänä, jona näytän kunniani, sanoo Herra, Herra.',
        14: 'Valitaan vakinaiset miehet, jotka kulkevat maata ja hautaavat noita kulkijoita, mitä heitä vielä on jäljellä maan pinnalla, puhdistaakseen sen. Seitsemässä kuukaudessa he saavat sen tutkituksi läpikotaisin.',
        15: "Kun nämä kulkijat kulkevat maata ja joku heistä näkee ihmisen luut, hän panee niille kiven merkiksi, siihen asti kunnes haudankaivajat ovat ne haudanneet 'Googin meluisan joukon laaksoon.'",
        16: 'Erään kaupungin nimenäkin on Hamona. – Niin he puhdistavat maan.',
        17: 'Mutta sinä, ihmislapsi! Näin sanoo Herra, Herra: Käske lintuja, kaikkia siivekkäitä, ja kaikkia kedon eläimiä: Kokoontukaa, tulkaa, yhtykää joka taholta teurasuhrilleni, jonka teitä varten uhraan, suurelle teurasuhrille Israelin vuorille. Syökää lihaa ja juokaa verta.',
        18: 'Syökää sankarien lihaa ja juokaa maan ruhtinaiden verta – pässejä, lampaita, vuohia ja härkiä, kaikki Baasanissa syötettyjä.',
        19: 'Syökää itsenne kylläisiksi rasvasta ja juokaa itsenne juovuksiin verestä, teurasuhrista, jonka teitä varten uhraan.',
        20: 'Tulkaa kylläisiksi pöydässäni ratsuista ja vaunuhevosista, sankareista ja kaikenlaisista sotamiehistä, sanoo Herra, Herra.',
        21: 'Asetan kunniani pakanoiden keskuuteen, ja kaikki pakanakansat saavat nähdä tuomioni, jonka panen toimeen, ja käteni, jonka lasken heidän päälleen.',
        22: 'Mutta Israelin heimo tulee tietämään, että minä, Herra, olen heidän Jumalansa siitä päivästä lähtien ja aina eteenpäin.',
        23: 'Pakanakansat tulevat tietämään, että Israelin heimo joutui karkotukseen syntivelkansa tähden, koska olivat olleet minulle uskottomat, ja kätkin heiltä kasvoni, ja annoin heidät heidän vihollistensa käsiin, ja he kaikki kaatuivat miekkaan.',
        24: 'Tein heille heidän saastaisuutensa ja rikostensa mukaan ja kätkin heiltä kasvoni.',
        25: 'Sen tähden, näin sanoo Herra, Herra: Nyt käännän Jaakobin kohtalon ja armahdan kaikkea Israelin heimoa ja kiivailen pyhän nimeni puolesta.',
        26: 'Häpeänsä ja kaiken uskottomuutensa, jota he ovat minulle osoittaneet, he kantavat asuessaan nyt turvassa maassaan kenenkään pelottelematta.',
        27: 'Kun tuon heidät takaisin kansojen seasta ja kokoan heidät heidän vihamiestensä maista, niin osoitan heissä pyhyyteni monien pakanakansojen silmien edessä.',
        28: 'He tulevat tietämään, että minä, Herra, olen heidän Jumalansa, kun minä vietyäni heidät karkotukseen pakanoiden keskuuteen kokoan heidät maahansa, en jätä niihin jäljelle ainoatakaan heistä,',
        29: 'enkä enää kätke heiltä kasvojani, sillä vuodatan Henkeni Israelin heimon päälle, sanoo Herra, Herra."',
    },
    40: {
        1: 'Meidän karkotuksemme kahdentenakymmenentenä viidentenä vuotena, vuoden alussa, kuukauden kymmenentenä päivänä, neljäntenätoista vuotena kaupungin valloituksen jälkeen, juuri sinä päivänä tuli minun päälleni Herran käsi, ja hän vei minut sinne.',
        2: 'Jumalan näyissä hän vei minut Israelin maahan ja laski minut hyvin korkealle vuorelle, jolla oli ikään kuin kaupunki rakennettuna etelään päin.',
        3: 'Hän vei minut sinne. Katso, oli mies, näöltään vasken kaltainen, ja pellavanuora oli hänellä kädessä sekä mittaruoko, ja hän seisoi portilla.',
        4: 'Mies puhui minulle: "Ihmislapsi, katso silmilläsi, kuule korvillasi ja ota huomioosi kaikki, mitä minä sinulle näytän. Sitä varten näet sinut on tuotu tänne, että nämä sinulle näytettäisiin. Ilmoita kaikki, mitä näet, Israelin heimolle.',
        5: 'Katso, temppelin ulkopuolella sen ympäri oli muuri. Miehen kädessä oli mittaruoko, kuusikyynäräinen, kyynärään luettuna kyynärä ja kämmenenleveys. Hän mittasi muurirakennuksen leveyden, joka oli yksi ruoko, ja korkeuden, joka oli yksi ruoko.',
        6: 'Hän meni portille, jonka etupuoli oli itää kohden, nousi ylös sen portaita ja mittasi portin kynnyksen: se oli yhden ruovon levyinen. Ensimmäinen kynnys oli yhden ruovon levyinen.',
        7: 'Sivuhuone oli aina yhden ruovon pituinen ja yhden ruovon levyinen, ja sivuhuoneiden väliä oli viisi kyynärää. Portin kynnys porttieteisen laidassa, sisäpuolella oli yksi ruoko.',
        8: 'Hän mittasi porttieteisen, joka oli sisäpuolella. Se oli yksi ruoko.',
        9: 'Hän mittasi porttieteisen, joka oli kahdeksan kyynärää, ja sen pilasterit, jotka olivat kaksi kyynärää. Porttieteinen oli sisemmällä puolella.',
        10: 'Itää kohden antavan portin sivuhuoneita oli kolme kummallakin puolella. Ne kolme olivat yhtä suuria, ja niiden pilasterit kummallakin puolella olivat yhtä suuria.',
        11: 'Hän mittasi portin oviaukon leveyden, joka oli kymmenen kyynärää, ja portin pituuden, joka oli kolmetoista kyynärää.',
        12: 'Mutta sivuhuoneiden edessä oli aitaus, joka oli yhden kyynärän korkuinen, samoin toisella puolella oleva aitaus oli yhden kyynärän korkuinen, ja kukin sivuhuone kummallakin puolella oli suuntaansa kuusi kyynärää.',
        13: 'Hän mittasi portin, sivuhuoneen katosta toisen kattoon: leveys oli kaksikymmentä viisi kyynärää, ovelta ovelle.',
        14: 'Hän otti mitan pilasterista: kaksikymmentä kyynärää. Seinän pilastereihin ulottui esipiha portin ympärillä.',
        15: 'Sisäänkäyntiportin edestä sisäportin eteisen eteen oli viisikymmentä kyynärää.',
        16: 'Portissa oli sisäänpäin ympäriinsä sivuhuoneisiin ja niiden seinien pilastereihin päin ikkuna-aukkoja, samoin eteisissä. Ikkuna-aukot ympäriinsä laajenivat sisäänpäin. Seinien pilastereissa oli palmukoristeita.',
        17: 'Sitten hän vei minut ulompaan esipihaan. Katso: ympäri esipihan oli kammioita ja kivillä päällystetty lattia. Kivillä päällystetyn lattian laidassa oli kolmekymmentä kammiota.',
        18: 'Kivillä päällystetty lattia oli porttien sivuseinillä, porttien pituuden mukaisesti. Tämä oli alempi kivillä päällystetty lattia.',
        19: 'Hän mittasi leveyden alemman portin edestä sisemmän esipihan edustalle, sen ulkopuolelle: sata kyynärää sekä itä- että pohjoispuolella.',
        20: 'Hän mittasi sen portin pituuden ja leveyden, jonka etupuoli oli pohjoista kohden ja joka vei ulompaan esipihaan.',
        21: 'Siinä oli kolme sivuhuonetta kummallakin puolella, ja sen pilasterit ja eteinen olivat yhtä suuret kuin ensimmäisessä portissa. Sen pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.',
        22: 'Sen ikkunat, eteinen ja palmukoristeet olivat yhtä suuret kuin portin, jonka etupuoli oli itää kohden, ja sinne noustiin seitsemää porrasta, ja niistä eteenpäin oli sen eteinen.',
        23: 'Sisemmällä esipihalla oli portit vastakkain pohjoista ja itää kohden. Hän mittasi portista porttiin: sata kyynärää.',
        24: 'Hän kuljetti minua etelää kohden, ja katso, tuli portti, joka antoi etelään. Hän mittasi sen pilasterit ja eteisen: ne olivat yhtä suuret kuin nuo toiset.',
        25: 'Siinä ja sen eteisessä oli ikkuna-aukkoja ympäriinsä, samanlaisia kuin nuo toiset ikkuna-aukot. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.',
        26: 'Sen ylös menevässä käytävässä oli seitsemän porrasta, ja niistä eteenpäin oli sen eteinen. Siinä oli palmukoristeet, yksi kummallakin puolella, sen pilastereissa.',
        27: 'Sisemmässä esipihassa oli portti etelää kohden. Hän mittasi portista porttiin etelää kohden: sata kyynärää.',
        28: 'Sitten hän vei minut sisempään esipihaan eteläportin kautta. Hän mittasi eteläportin. Se oli yhtä suuri kuin nuo toiset.',
        29: 'Sen sivuhuoneet, pilasterit ja eteinen olivat yhtä suuret kuin nuo toiset. Siinä ja sen eteisessä oli ikkuna-aukkoja ympäriinsä. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.',
        30: 'Eteisiä oli ympäriinsä. Niiden pituus oli kaksikymmentä viisi kyynärää, leveys viisi kyynärää.',
        31: 'Sen eteinen oli ulompaan esipihaan päin, ja sen pilastereissa oli palmukoristeita. Sen portaissa oli kahdeksan porrasta.',
        32: 'Hän vei minut sisempään esipihaan itää kohden. Hän mittasi portin. Se oli yhtä suuri kuin nuo toiset.',
        33: 'Sen sivuhuoneet, pilasterit ja eteinen olivat yhtä suuret kuin nuo toiset. Siinä ja sen eteisessä oli ikkuna-aukkoja ympäriinsä. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.',
        34: 'Sen eteinen oli ulompaan esipihaan päin, ja sen pilastereissa oli palmukoristeita kummallakin puolella. Sen portaissa oli kahdeksan porrasta.',
        35: 'Sitten hän vei minut pohjoisportille ja mittasi. Yhtä suuret kuin nuo toiset',
        36: 'olivat sen sivuhuoneet, pilasterit ja eteinen. Ikkuna-aukkoja oli siinä ympäriinsä. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.',
        37: 'Sen eteinen oli ulompaan esipihaan päin, ja sen pilastereissa oli palmukoristeita kummallakin puolella. Sen portaissa oli kahdeksan porrasta.',
        38: 'Sitten oli kammio, jonka ovi oli pilastereissa, porteissa. Siellä oli polttouhri huuhdottava.',
        39: 'Portin eteisessä oli kaksi pöytää kummallakin puolella. Niillä oli polttouhri, syntiuhri ja vikauhri teurastettava.',
        40: 'Ulkopuolisella sivuseinällä, portin ovelle noustaessa, pohjoispuolella, oli kaksi pöytää, samoin porttieteisen toisella sivuseinällä kaksi pöytää:',
        41: 'neljä pöytää portin sivuseinillä kummallakin puolella, siis kahdeksan pöytää. Niillä oli teurastettava.',
        42: 'Ylös johtavan käytävän ääressä oli neljä pöytää hakatuista kivistä. Ne olivat puolentoista kyynärän pituisia, puolentoista kyynärän levyisiä ja yhden kyynärän korkuisia. Niille oli laskettava ne välineet, joilla teurastettiin polttouhri ja teurasuhri.',
        43: 'Haarukkakoukkuja, yhden kämmenenleveyden pituisia, oli kiinnitetty ympäri huonetta, mutta uhriliha pantiin pöydille.',
        44: 'Sisemmän portin ulkopuolella oli kaksi huonetta sisemmässä esipihassa, toinen pohjoisen portin sivuseinällä, etupuoli etelää kohden, ja toinen eteläisen portin sivuseinällä, etupuoli pohjoista kohden.',
        45: 'Hän puhui minulle: "Tämä huone, jonka etupuoli on etelää kohden, on pappeja varten, jotka hoitavat temppelitehtäviä.',
        46: 'Huone, jonka etupuoli on pohjoista kohden, on pappeja varten, jotka hoitavat alttaritehtäviä. Heitä ovat Saadokin jälkeläiset, ne leeviläisistä, jotka saavat lähestyä Herraa häntä palvellakseen."',
        47: 'Hän mittasi esipihan: pituus oli sata kyynärää ja leveys sata kyynärää. Se oli neliön muotoinen. Alttari oli temppelin edustalla.',
        48: 'Hän vei minut temppelin eteiseen ja mittasi eteisen pilasterin: viisi kyynärää kummallakin puolella, ja portin leveyden: kolme kyynärää kummallakin puolella.',
        49: 'Eteisen pituus oli kaksikymmentä kyynärää ja leveys yksitoista kyynärää. Sinne noustiin kymmentä porrasta. Pilastereiden ääressä oli pylväät, yksi kummallakin puolella.',
    },
    41: {
        1: 'Hän vei minut temppelisaliin ja mittasi pilasterit. Ne olivat kuusi kyynärää leveitä kummallakin puolella: ilmestysmajan leveys.',
        2: 'Oviaukko oli kymmenen kyynärää leveä, ja oviaukon sivuseinät kummallakin puolella olivat viisi kyynärää. Hän mittasi temppelisalin pituuden: neljäkymmentä kyynärää, ja leveyden: kaksikymmentä kyynärää.',
        3: 'Hän meni sisimpään ja mittasi oviaukon pilasterin: kaksi kyynärää, oviaukon: kuusi kyynärää, ja oviaukon leveyden: seitsemän kyynärää.',
        4: 'Hän mittasi sen pituuden, joka oli kaksikymmentä kyynärää, ja leveyden: kaksikymmentä kyynärää temppelisalin puolelta. Hän sanoi minulle: "Tämä on kaikkeinpyhin."',
        5: 'Sitten hän mittasi temppelin seinän: kuusi kyynärää, ja sivukammion leveyden, joka oli neljä kyynärää, yltympäri temppelin.',
        6: 'Sivukammioita oli: kolme sivukammiota päällekkäin, kolmeenkymmeneen kertaan. Ne kulkivat ympäri sen temppeliseinän varassa, joka oli sivukammioihin päin, niin että pysyivät siinä kiinni, mutta ne eivät olleet kiinnitetyt temppeliseinän sisään.',
        7: 'Sivukammiot olivat aina sitä leveämpiä kiertäessään, mitä ylempänä ne olivat, sillä temppelin ympäryskammiot ulottuivat ylemmäksi ja ylemmäksi ympäri temppelin, ollen siten ylhäällä leveämmät sisäänpäin. Alakerrasta noustiin yläkertaan keskikerroksen kautta.',
        8: 'Näin, että temppelillä oli koroke ympäriinsä: sivukammioiden perustukset, koko ruovon korkuiset, kuusi kyynärää, reunustaan asti.',
        9: 'Sivukammioiden ulkoseinän paksuus oli viisi kyynärää; yhtä leveä oli avoin tila sivukammiorakennuksen ääressä, joka kuului temppeliin.',
        10: 'Välimatkaa pihakammiorakennuksiin oli kaksikymmentä kyynärää leveälti ympäri temppelin – yltympäri.',
        11: 'Sivukammioista vei ovi avoimeen tilaan: yksi ovi pohjoista kohden ja toinen ovi etelää kohden. Avoimen tilan leveys oli viisi kyynärää yltympäri.',
        12: 'Rakennus, joka oli eristetyn alueen laidassa lännen puoleisella sivulla, oli seitsemänkymmentä kyynärää leveä. Rakennuksen seinän paksuus oli viisi kyynärää, ympäriinsä, ja sen pituus oli yhdeksänkymmentä kyynärää.',
        13: 'Hän mittasi temppelin: pituus oli sata kyynärää, sekä eristetyn alueen ja rakennuksen seinineen: pituus sata kyynärää.',
        14: 'Temppelin etupuolen ja eristetyn alueen leveys itään päin oli sata kyynärää.',
        15: 'Sitten hän mittasi sen rakennuksen pituuden, joka oli eristetyn alueen laidassa, sen takana, sekä sen käytävät, kummallakin puolella: sata kyynärää; ja sisemmän temppelisalin, esipihan eteiset,',
        16: 'kynnykset, sisäänpäin avartuvat ikkunat, käytävät niiden kolmen ympärillä – kynnyksen edessä oli puulaudoitus yltympäri – ja välin maasta ikkuna-aukkoihin. Ikkuna-aukot olivat peitetyt.',
        17: 'Oviaukkojen yläpuolelta lähtien sekä sisempään temppeliin asti että ulos asti, koko seinällä yltympäri, sisä- ja ulkopuolella, olivat mitatut alat,',
        18: 'ja niihin oli tehty kerubeja ja palmuja, palmu aina kahden kerubin väliin. Kullakin kerubilla oli kahdet kasvot:',
        19: 'ihmisen kasvot palmuun päin toisaalle ja leijonan kasvot palmuun päin toisaalle. Niin oli tehty koko temppelissä yltympäri:',
        20: 'maasta alkaen ja aina oviaukkojen yläpuolelle oli tehty kerubeja ja palmuja, samoin temppelisalin seinälle.',
        21: 'Temppelisalissa oli nelikulmaiset ovenpielet. Mutta pyhimmän edessä näkyi',
        22: 'ikään kuin alttari, puinen, kolme kyynärää korkea, ja sen pituus oli kaksi kyynärää. Siinä oli nurkkaukset, ja sen jalusta ja seinät olivat puuta. Hän sanoi minulle: "Tämä on pöytä, joka on Herran edessä',
        23: 'Sekä temppelisalissa että pyhimmässä oli kaksoisovet.',
        24: 'Ovissa oli kaksi ovipuoliskoa, kaksi kääntyvää ovipuoliskoa: kumpaisessakin ovessa oli kaksi ovipuoliskoa.',
        25: 'Niihin, temppelisalin oviin, oli tehty kerubeja ja palmuja, samoin kuin oli tehty seiniin. Ulkona, eteisen edessä, oli puinen porraskatos.',
        26: 'Eteisen sivuseinissä, kummallakin puolella, oli sisäänpäin avartuvia ikkuna-aukkoja ja palmuja, samoin temppelin sivukammioissa ja porraskatoksissa.',
    },
    42: {
        1: 'Hän vei minut ulompaan esipihaan pohjoista kohden vievää tietä myöten. Hän vei minut pihakammiorakennuksen luo, joka oli vastapäätä eristettyä aluetta ja pohjoisen puoleista rakennusta,',
        2: 'satakyynärää pitkän sivun edustalle, jossa oli oviaukko pohjoiseen päin. Sen leveys taas oli viisikymmentä kyynärää.',
        3: 'Sen kaksikymmentäkyynäräisen paikan edustalla, joka kuului sisempään esipihaan, ja vastapäätä sitä kiveystä, joka oli ulommassa esipihassa, oli käytävä käytävää vastassa, kolmessa kerroksessa.',
        4: 'Kammioiden editse meni kulkutie, kymmenen kyynärää leveä, sisempään esipihaan, ja tie oville yhden kyynärän leveä, ja oviaukot olivat pohjoiseen päin.',
        5: 'Mutta ylimmät kammiot olivat kapeimmat, sillä käytävät veivät niiltä tilaa enemmän kuin alimmilta ja keskimmäisiltä kammioilta rakennuksessa.',
        6: 'Sillä nämä olivat kolminkertaiset, mutta niissä ei ollut pylväitä, niin kuin esipihoissa oli pylväät. Sen vuoksi ne tulivat olemaan kapeammat kuin alimmat ja keskimmäiset maasta lukien.',
        7: 'Oli myös muuri, joka ulkopuolella kulki samaan suuntaan kammioiden kanssa ulompaa esipihaa kohden kammioiden editse. Sen pituus oli viisikymmentä kyynärää.',
        8: 'Sillä niiden kammioiden pituus, jotka olivat ulompaan esipihaan päin, oli yhteensä viisikymmentä kyynärää, mutta, katso, temppelisalin puolella sata kyynärää.',
        9: 'Näiden kammioiden alapuolella oli sisäänkäynti idästä, kun tultiin niiden luo uloimmasta esipihasta.',
        10: 'Esipihaa ympäröivän muurin leveällä puolella itää kohden, eristetyn alan edustalla ja rakennuksen edustalla, oli kammioita.',
        11: 'Niiden editse kulki tie. Ne olivat samanmuotoisia kuin ne kammiot, jotka olivat pohjoista kohden: yhtä pitkiä ja leveitä. Samanlaisia olivat kaikki näiden ulos johtavat käytävät, rakennelmat ja oviaukot.',
        12: 'Samoin kuin olivat niiden kammioiden oviaukot, jotka olivat etelää kohden, oli se oviaukko, joka oli tien päässä – tien, joka kulki senpuolisen muurin viertä itää kohden, sinne tultaessa.',
        13: 'Hän sanoi minulle: "Pohjoiskammiot ja eteläkammiot, jotka ovat eristetyn alan edustalla, ovat pyhiä kammioita, joissa papit, jotka lähestyvät Herraa, syövät sitä, mikä on korkeasti pyhää. Sinne he pankoot korkeasti pyhän: ruokauhrin, syntiuhrin ja vikauhrin; sillä se paikka on pyhä.',
        14: 'Kun papit ovat tulleet, älkööt he menkö pyhäköstä ulos esipihaan muuten, kuin että panevat sinne vaatteensa, joissa toimittavat virkaansa, sillä ne ovat pyhät, ja pukeutuvat toisiin vaatteisiin. Sitten lähestykööt paikkaa, mikä on kansaa varten."',
        15: 'Kun hän oli saanut loppuun sisemmän temppelin mittaamisen, hän vei minut ulos sille portille, jonka etupuoli oli itää kohden. Hän mittasi sen ympärysmitan.',
        16: 'Hän mittasi idän puolelta mittaruovolla: viisisataa ruokoa mittaruovon mukaan ympäriinsä.',
        17: 'Hän mittasi pohjoisen puolelta: viisisataa ruokoa mittaruovon mukaan ympäriinsä.',
        18: 'Hän mittasi etelän puolelta: viisisataa ruokoa mittaruovon mukaan ympäriinsä.',
        19: 'Hän mittasi lännen puolelta: viisisataa ruokoa mittaruovon mukaan.',
        20: 'Neljältä ilmansuunnalta hän sen mittasi. Siinä oli muuri yltympäri: pituutta viisisataa ja leveyttä viisisataa. Sen tuli erottaa pyhä epäpyhästä.',
    },
    43: {
        1: 'Sitten hän kuljetti minut portille – sille portille, joka antoi itään.',
        2: 'Katso: Israelin Jumalan kunnia tuli idän tietä. Sen kohina oli kuin paljojen vetten kohina, ja maa tuli valoisaksi hänen kunniastaan.',
        3: 'Näky, jonka näin, oli samanlainen kuin se näky, jonka olin nähnyt tullessani hävittämään kaupungin. Samanlaiset olivat näyt kuin se näky, jonka olin nähnyt Kebar-joen varrella. Silloin lankesin kasvoilleni.',
        4: 'Herran kunnia kulki temppeliin sen portin kautta, jonka etupuoli oli itään.',
        5: 'Henki nosti minut ja vei minut sisempään esipihaan. Katso: Herran kunnia täytti temppelin.',
        6: 'Kuulin jonkun puhuttelevan minua temppelistä, mutta mies seisoi vieressäni.',
        7: 'Hän sanoi minulle: "Ihmislapsi, tämä on valtaistuimeni paikka ja jalkapohjieni sija, jossa asun israelilaisten keskellä iankaikkisesti. Israelin heimo ei ole enää saastuttava pyhää nimeäni – eivät he eivätkä heidän kuninkaansa – haureudellaan, kuninkaittensa ruumiilla ja uhrikukkuloillaan.',
        8: 'Kun he asettivat kynnyksensä kynnykseni vierelle, ovenpielensä ovenpielteni viereen, niin että muuri vain oli minun ja heidän välillään, niin he saastuttivat pyhän nimeni kauhistuksillaan, joita he harjoittivat, ja tein heistä lopun vihassani.',
        9: 'Nyt he vievät haureutensa ja kuninkaittensa ruumiit minusta kauas, ja asun heidän keskellään iankaikkisesti.',
        10: 'Sinä, ihmislapsi, saata Israelin heimolle sanoma tästä temppelistä, että he häpeäisivät rikoksiaan, ja he ottakoot siitä mallia.',
        11: 'Jos he häpeävät kaikkea, mitä ovat tehneet, niin tee heille tiettäväksi temppelin muoto sekä sen sisustus, uloskäytävät, sisäänkäytävät, kaikki muodot, kaikki säädökset, kaikki muodot ja kaikki lait. Kirjoita ne heidän silmiensä eteen, että he ottaisivat vaarin sen koko muodosta ja kaikista säädöksistä ja tekisivät niiden mukaan.',
        12: 'Tämä on temppelin laki: sen koko alue vuoren laella yltympäri on korkeasti pyhä. Katso, tämä on temppelin laki."',
        13: 'Nämä olivat alttarin mitat kyynäröinä, kyynärään luettuna kyynärä ja kämmenenleveys: sen alusta oli kyynärän korkuinen ja kyynärän levyinen, ja sen reunusta ympäri sen laidan oli yhden vaaksan mittainen. Tämä oli alttarin koroke.',
        14: 'Alustasta, joka oli maassa, alimmalle välireunalle: kaksi kyynärää sekä leveyttä yksi kyynärä; ja pienemmältä välireunalta suuremmalle välireunalle: neljä kyynärää sekä leveyttä kyynärä.',
        15: 'Jumalan lieteen oli neljä kyynärää, ja Jumalan liedestä ylöspäin oli neljä sarvea.',
        16: 'Jumalan lieden pituus oli kaksitoista kyynärää ja leveys kaksitoista, niin että sen neljästä sivusta tuli neliö.',
        17: 'Välireunan pituus oli neljätoista kyynärää ja leveys neljätoista, sen neljältä sivulta. Sitä ympäröivä reunusta oli puoli kyynärää, ja sen alusta oli kyynärän ympäriinsä. Sen portaat olivat idän puolella.',
        18: 'Hän sanoi minulle: "Ihmislapsi, näin sanoo Herra, Herra: Nämä ovat alttaria koskevat säädökset: Sinä päivänä, jona se on saatu tehdyksi, niin että sillä voidaan uhrata polttouhri ja vihmoa sille verta,',
        19: 'anna mulli syntiuhriksi papeille, leeviläisille, jotka ovat Saadokin jälkeläisiä ja saavat lähestyä minua palvellakseen minua, sanoo Herra, Herra.',
        20: 'Ota sen verta ja sivele alttarin neljään sarveen ja välireunan neljään kulmaan ja reunustaan yltympäri. Sinun on puhdistettava se ja toimitettava sen sovitus.',
        21: 'Ota sitten syntiuhrimulli ja polta se säädetyssä, temppelille kuuluvassa paikassa, pyhäkön ulkopuolella.',
        22: 'Tuo seuraavana päivänä virheetön vuohipukki syntiuhriksi. Alttari on puhdistettava, samoin kuin se puhdistettiin mullin verellä.',
        23: 'Suoritettuasi loppuun puhdistuksen tuo virheetön mulli ja virheetön pässi pikkukarjasta.',
        24: 'Tuo ne Herran eteen, ja papit heittäkööt niiden päälle suolaa ja uhratkoot ne polttouhriksi Herralle.',
        25: 'Uhraa joka päivä, seitsemänä päivänä, syntiuhripukki. Myös on uhrattava virheettömät mulli ja pässi pikkukarjasta.',
        26: 'Seitsemänä päivänä toimitettakoon alttarin sovitus ja puhdistettakoon ja vihittäköön se.',
        27: 'Niiden päivien kuluttua papit kahdeksantena päivänä ja aina edelleen uhratkoot alttarilla polttouhrejaan ja rauhanuhrejaan, ja minä mielistyn teihin, sanoo Herra, Herra."',
    },
    44: {
        1: 'Hän vei minut takaisin pyhäkön ulommalle portille, sille, joka antoi itään, mutta joka oli suljettu.',
        2: 'Herra sanoi minulle: "Tämä portti on oleva suljettuna. Sitä ei saa avata, eikä kukaan saa käydä siitä sisälle, sillä Herra, Israelin Jumala, on käynyt siitä sisälle. Se on oleva suljettu.',
        3: 'Ruhtinas ainoastaan ruhtinaana istukoon siellä ja syököön leipää Herran edessä. Hän käyköön sisään porttieteisen kautta ja tulkoon ulos samaa tietä."',
        4: 'Hän toi minut pohjoisportin kautta temppelin edustalle, ja näin, ja katso: Herran kunnia täytti Herran huoneen. Lankesin kasvoilleni.',
        5: 'Herra sanoi minulle: "Ihmislapsi, pane sydämeesi, katso silmilläsi ja kuule korvillasi kaikki, mitä sinulle puhun kaikista Herran huoneen säädöksistä ja kaikista sen laeista, ja ota huomioosi, kuinka temppeliin on mentävä kustakin pyhäkön uloskäytävästä.',
        6: 'Sano niille kapinoiville, sano Israelin heimolle: Näin sanoo Herra, Herra: Jo riittävät kaikki teidän kauhistuksenne, te Israelin heimo,',
        7: 'kun olette tuoneet muukalaisia, sydämeltään ja ruumiiltaan ympärileikkaamattomia, pyhäkkööni olemaan siellä ja häpäisemään huoneeni, samalla kun olette uhranneet leipääni ja rasvaa ja verta. Olette rikkoneet liittoni – kaikkien muiden kauhistustenne lisäksi.',
        8: 'Ette ole hoitaneet minulle suoritettavia pyhiä tehtäviä, vaan olette panneet heitä puolestanne hoitamaan minulle pyhäkössäni suoritettavia tehtäviä.',
        9: 'Näin sanoo Herra, Herra: Yksikään muukalainen, sydämeltään ja ruumiiltaan ympärileikkaamaton, ei saa tulla pyhäkkööni, olkoon kuka tahansa israelilaisten keskuudessa oleva muukalainen.',
        10: 'Vaan ne leeviläiset, jotka menivät minusta kauas, silloin kun Israel oli joutunut eksyksiin, nuo, jotka eksyivät pois minusta epäjumaliensa perään, kantakoot syntinsä.',
        11: 'He toimittakoot pyhäkössäni vartioinnin temppelin porteilla ja toimittakoot temppelipalveluksen. He teurastakoot polttouhrit ja teurasuhrit kansalle ja seisokoot heidän edessään heitä palvelemassa.',
        12: 'Koska he ovat heitä palvelleet heidän epäjumaliensa edessä ja olleet Israelin heimolle kompastuksena syntiin, sen tähden olen kohottanut käteni heitä vastaan, sanoo Herra, Herra, ja heidän on kannettava syntinsä.',
        13: 'He eivät saa lähestyä minua, niin että toimittaisivat edessäni papinvirkaa ja lähestyisivät mitään minulle pyhitettyä, mitään korkeasti pyhää, vaan heidän on kannettava häpeänsä ja kauhistuksensa, joita ovat tehneet.',
        14: 'Panen heidät hoitamaan temppelissä suoritettavia tehtäviä, mitä siellä on palvelijantyötä ja muuta toimitettavaa.',
        15: 'Mutta ne leeviläiset papit, Saadokin jälkeläiset, jotka hoitivat pyhäkössäni suoritettavat tehtävät silloin, kun israelilaiset olivat eksyneet minusta pois, he saavat lähestyä minua, palvella minua ja seisoa edessäni uhraamassa minulle rasvaa ja verta, sanoo Herra, Herra.',
        16: 'He saavat tulla pyhäkkööni ja saavat lähestyä pöytääni palvellen minua ja hoitaen minulle suoritettavat tehtävät.',
        17: 'Tullessaan sisemmän esipihan porteille he pukeutukoot pellavavaatteisiin älköötkä pitäkö päällään villaista vaatetta toimittaessaan virkaansa sisemmän esipihan porteissa ja sisällä temppelissä.',
        18: 'Pellavaiset turbaanit olkoot heillä päässä ja pellavaiset housut lanteilla. Älkööt he panko vyötäisilleen mitään hiostuttavaa.',
        19: 'Kun he menevät pois ulompaan esipihaan, kansan luo ulompaan esipihaan, riisukoot vaatteensa, joissa ovat virkaa toimittaneet, jättäkööt ne pyhäkön kammioihin ja pukekoot päälleen toiset vaatteet, etteivät pyhittäisi kansaa vaatteillaan.',
        20: 'Älkööt ajako päätänsä paljaaksi, mutta älkööt myöskään antako tukkansa kasvaa valtoimenaan. Heidän on leikattava hiuksensa.',
        21: 'Viiniä älköön kukaan pappi juoko tultuaan sisempään esipihaan.',
        22: 'Leskeä ja hylättyä älkööt ottako vaimokseen, vaan ottakoot neitsyen Israelin heimon jälkeläisistä tai lesken, joka on leskenä papin jälkeen.',
        23: 'Opettakoot he kansalleni erotuksen pyhän ja epäpyhän välillä sekä tehkööt heille tiettäväksi, mikä on saastaista, mikä puhdasta.',
        24: 'Riita-asioissa seisokoot tuomitsemassa ja tuomitkoot niissä oikeuksieni mukaan. Lakejani ja säädöksiäni noudattakoot kaikkien juhlieni vietossa ja pyhittäkööt sapattini.',
        25: 'Älköön menkö kuolleen ihmisen luo ja siten tulko saastaiseksi. Ainoastaan isästä ja äidistä, pojasta ja tyttärestä, veljestä ja sisaresta, jos tämä ei ollut naitu, hän saa saastua.',
        26: 'Mutta puhdistuksensa jälkeen luettakoon hänelle vielä seitsemän päivää.',
        27: 'Sinä päivänä, jona hän tulee pyhäkköön, sisempään esipihaan, toimittamaan virkaansa pyhäkössä, hän uhratkoon syntiuhrinsa, sanoo Herra, Herra.',
        28: 'Tämä on oleva heidän perintöosansa: minä olen heidän perintöosansa. Teidän ei tule antaa heille perintömaata Israelissa: minä olen heidän perintömaansa.',
        29: 'Ruokauhrin, syntiuhrin ja vikauhrin he saavat syödä, ja kaikki tuhoon vihitty Israelissa on tuleva heille.',
        30: 'Paras kaikesta ensisadosta, kaikenlaatuisesta, ja kaikki annit, mitä laatua hyvänsä antinne ovatkin, tulevat papeille. Parhaat ryyneistänne teidän on annettava papille, että tuottaisit siunauksen huoneellesi.',
        31: 'Papit älkööt syökö mitään itsestään kuollutta tai kuoliaaksi raadeltua, ei lintua eikä nautaa."',
    },
    45: {
        1: '"Kun arvotte maata perintöosiksi, niin antakaa Herralle anti, pyhä osa maasta, kaksikymmentäviisi tuhatta kyynärää pitkä ja kymmenen tuhatta kyynärää leveä. Se olkoon pyhä koko alueeltaan, yltympäri.',
        2: 'Siitä tulkoon pyhäkölle neliö, viisisataa ja viisisataa kyynärää joka taholta, ja sen lisäksi avointa tilaa viisikymmentä kyynärää joka taholta.',
        3: 'Mittaa tästä mitatusta alueesta kaksikymmentäviisi tuhatta kyynärää pituutta ja kymmenentuhatta kyynärää leveyttä, ja siinä olkoon pyhäkkö, korkeasti pyhä.',
        4: 'Se olkoon pyhä osa maasta papeille, jotka palvelevat pyhäkössä, jotka lähestyvät ja palvelevat Herraa. Se olkoon talojen sijaintipaikkana heitä varten ja pyhänä paikkana pyhäkköä varten.',
        5: 'Kaksikymmentäviisi tuhatta pituutta ja kymmenentuhatta leveyttä on tuleva leeviläisille, jotka toimittavat palvelusta pyhäkössä, heille perintömaaksi – kaksikymmentä kammiota.',
        6: 'Kaupungille antakaa perintömaata viisituhatta kyynärää leveyttä ja kaksikymmentäviisi tuhatta kyynärää pituutta, pyhän anniksi annetun maan viereltä. Se olkoon koko Israelin heimon oma.',
        7: 'Ruhtinaalle: molemmilta puolin pyhää anniksi annettua maata ja kaupungin perintömaata, pyhän anniksi annetun maan sivusta ja kaupungin perintömaan sivusta, lännen puolelta länteen päin ja idän puolelta itään päin, maata yhtä pitkälti kuin on yhden sukukunnan osuuden pituus länsirajasta itärajaan.',
        8: 'Se olkoon hänellä maana, perintömaana Israelissa. Älkööt ruhtinaani enää sortako kansaani, vaan jättäkööt muun maan Israelin heimolle sukukunnittain.',
        9: 'Näin sanoo Herra, Herra: Jo riittää, te Israelin ruhtinaat! Pankaa pois väkivalta ja sorto, noudattakaa oikeutta ja vanhurskautta, lakatkaa häätämästä kansaani sen mailta, sanoo Herra, Herra.',
        10: 'Olkoon teillä oikea paino, oikea eefa-mitta ja oikea bat-mitta.',
        11: 'Eefa- ja bat-mitta olkoot tarkasti yhtä suuret: bat vetäköön kymmenenneksen hoomer-mittaa ja eefa kymmenenneksen hoomer-mittaa. Hoomerin mukaan määrättäköön kummankin suuruus.',
        12: 'Sekelissä olkoon kaksikymmentä geeraa. Miina olkoon teillä kaksikymmentä sekeliä, kaksikymmentäviisi sekeliä, viisitoista sekeliä.',
        13: 'Tämä on anti, joka teidän on annettava: kuudennes eefaa vehnähoomerista ja kuudennes eefaa ohrahoomerista.',
        14: 'Öljyn määrä bat-mitasta öljyä: kymmenennes batia koor-mitasta – kymmenestä batista, hoomerista – sillä hoomer on kymmenen batia,',
        15: 'ja pikkukarjasta: kahdestasadasta yksi lammas Israelin runsasvetisiltä laitumilta ruokauhriksi, polttouhriksi ja rauhanuhriksi, että voitaisiin toimittaa heille sovitus, sanoo Herra, Herra.',
        16: 'Koko maan kansa on velvollinen antamaan tämän annin Israelin ruhtinaalle.',
        17: 'Mutta ruhtinas toimittakoon polttouhrit, ruokauhrin ja juomauhrin juhlina, uusinakuina ja sapatteina, kaikkina Israelin heimon juhla-aikoina. Hän uhratkoon syntiuhrin, ruokauhrin, polttouhrin ja rauhanuhrin toimittaakseen sovituksen Israelin heimolle.',
        18: 'Näin sanoo Herra, Herra: Ota ensimmäisessä kuussa, kuukauden ensimmäisenä päivänä virheetön mulli ja puhdista pyhäkkö.',
        19: 'Pappi ottakoon syntiuhrin verta ja sivelköön sitä temppelin ovenpieliin ja alttarin neljään kulmaan ja sisemmän esipihan portin ovenpieliin.',
        20: 'Samoin tee kuukauden seitsemäntenä päivänä sen varalta, että joku olisi erehdyksestä tai tietämättömyydestä rikkonut, ja toimitatte temppelin sovituksen.',
        21: 'Ensimmäisessä kuussa, kuukauden neljäntenätoista päivänä, on teillä pääsiäinen. Se on seitsemän päivää kestävä juhla. Syötäköön silloin happamatonta leipää.',
        22: 'Sinä päivänä uhratkoon ruhtinas omasta puolestaan ja maan kaiken kansan puolesta mullin syntiuhriksi.',
        23: 'Mutta kunakin seitsemänä juhlapäivänä hän uhratkoon polttouhriksi Herralle seitsemän mullia ja seitsemän pässiä, virheettömiä, joka päivä seitsemänä päivänä, ja syntiuhriksi vuohipukin joka päivä.',
        24: 'Ruokauhriksi hän uhratkoon eefa-mitan mullia ja eefa-mitan pässiä kohti sekä öljyä hiin-mitan eefaa kohti.',
        25: 'Seitsemännessä kuussa, kuukauden viidentenätoista päivänä, juhlana, hän uhratkoon samalla tavoin – niin seitsemänä päivänä – samankaltaisen syntiuhrin, polttouhrin ja ruokauhrin sekä saman määrän öljyä."',
    },
    46: {
        1: '"Näin sanoo Herra, Herra: Sisemmän esipihan portti, se, joka antaa itään päin, olkoon suljettuna kuusi työpäivää. Mutta sapatinpäivänä se avattakoon, ja avattakoon se myös uudenkuun päivänä.',
        2: 'Silloin tulkoon ruhtinas porttieteisen kautta ulkoa ja asettukoon portin ovipieleen. Kun papit uhraavat hänen polttouhriaan ja rauhanuhriaan, niin hän kumartaen rukoilkoon portin kynnyksellä ja menköön sitten ulos. Mutta porttia älköön suljettako ennen iltaa.',
        3: 'Mutta maan kansa kumartaen rukoilkoon sen portin ovella sapatteina ja uusinakuina Herran edessä.',
        4: 'Polttouhrina, jonka ruhtinas tuo Herralle sapatinpäivänä, olkoon kuusi virheetöntä karitsaa ja virheetön pässi;',
        5: 'ja ruokauhrina eefa-mitta pässiä kohti, mutta ruokauhrina karitsoita kohti se, mitä hän voi ja tahtoo antaa, sekä hiin-mitta öljyä eefaa kohti.',
        6: 'Uudenkuun päivänä olkoon polttouhrina: virheetön mulli, kuusi karitsaa ja pässi, kaikki virheettömiä;',
        7: 'ja ruokauhrina hän uhratkoon eefan mullia kohti ja eefan pässiä kohti sekä karitsoita kohti sen, mitä hän saa hankituksi, sekä öljyä hiin-mitan eefaa kohti.',
        8: 'Kun ruhtinas tulee, tulkoon porttieteisen kautta ja menköön ulos samaa tietä.',
        9: 'Mutta kun maan kansa tulee juhlina Herran eteen, niin se, joka pohjoisportin kautta tuli kumartaen rukoilemaan, menköön ulos eteläportin kautta, ja se, joka tuli eteläportin kautta, menköön ulos pohjoisportin kautta. Kukaan älköön palatko sen portin kautta, josta tuli, vaan menköön ulos vastakkaisesta.',
        10: 'Ruhtinas tulkoon heidän joukossaan, kun he tulevat, ja menköön ulos, kun he menevät.',
        11: 'Juhlina ja juhla-aikoina olkoon ruokauhri: eefa mullia kohti ja eefa pässiä kohti sekä karitsoita kohti se, mitä kukin voi antaa, sekä öljyä hiin-mitta eefaa kohti.',
        12: 'Milloin ruhtinas uhraa vapaaehtoisia lahjoja, polttouhrin tai rauhanuhrin vapaaehtoisena lahjana Herralle, avattakoon hänelle portti, joka antaa itään, ja hän uhratkoon polttouhrinsa sekä rauhanuhrinsa samoin, kuin hän uhraa sapatinpäivänä, ja menköön ulos. Hänen lähdettyään suljettakoon portti.',
        13: 'Uhraa vuoden vanha virheetön karitsa joka päivä polttouhriksi Herralle. Uhraa se joka aamu.',
        14: 'Sen lisäksi uhraa ruokauhriksi joka aamu kuudennes eefaa sekä öljyä kolmannes hiin-mittaa ydinjauhojen kostuttamiseksi. Tämä on ruokauhri Herralle – ikiaikainen, pysyvä säädös.',
        15: 'Uhratkaa joka aamu karitsa, ruokauhri ja öljy jokapäiväiseksi polttouhriksi.',
        16: 'Näin sanoo Herra, Herra: Jos ruhtinas antaa jollekin pojistaan lahjan, se on tämän perintöosa. Se on tuleva hänen pojilleen. Se on perintöosana heidän omaisuuttaan.',
        17: 'Mutta jos hän antaa lahjan perintöosastaan jollekin palvelijoistaan, olkoon se tämän oma vapautusvuoteen saakka, mutta sitten palatkoon ruhtinaalle. Sehän on hänen perintöosaansa ja on tuleva hänen pojilleen.',
        18: 'Älköönkä ruhtinas ottako kansan perintöosia, niin että sortaisi heitä pois heidän perintömaaltaan. Omasta perintömaastaan hän antakoon perintöosia pojilleen, ettei kukaan kansastani tulisi häädetyksi pois omalta perintömaaltaan."',
        19: 'Hän vei minut siitä sisäänkäytävästä, joka oli portin sivuseinämällä, niiden kammioiden luo, jotka olivat pyhitettyjä papeille ja jotka antoivat pohjoiseen. Katso, siellä oli eräs paikka kauimpana länttä kohti.',
        20: 'Hän sanoi minulle: "Tämä on paikka, missä pappien on keitettävä vikauhri ja syntiuhri sekä leivottava ruokauhri, etteivät veisi ulos sitä ulompaan esipihaan pyhittääkseen kansan."',
        21: 'Sitten hän vei minut ulompaan esipihaan ja johdatti minut esipihan neljän nurkkauksen ohi, ja katso, esipihan joka nurkkauksessa oli piha.',
        22: 'Esipihan neljässä nurkkauksessa oli suljetut pihat, neljänkymmenen pituiset ja kolmenkymmenen levyiset. Nämä neljä nurkkapihaa olivat yhtä suuret.',
        23: 'Niissä neljässä oli ympäriinsä kivikehä, ja alas kivikehään oli tehty keittoliesiä.',
        24: 'Sitten hän sanoi minulle: "Nämä ovat keittiötilat, joissa temppelipalvelijat keittävät kansan teurasuhrit."',
    },
    47: {
        1: 'Hän vei minut takaisin temppelin ovelle. Katso, vettä tuli temppelin kynnyksen alta itään päin, sillä temppelin etusivu oli itään. Vesi juoksi alas temppelin oikeanpuoleisen sivuseinän ali alttarin eteläpuolitse.',
        2: 'Hän toi minut ulos pohjoisportin kautta ja kierrätti minut ulkopuolelta ulkoportille, joka antoi itään. Katso, vesi virtasi oikeanpuoleiselta sivuseinältä päin.',
        3: 'Mennessään itää kohti mittanuora kädessään mies mittasi tuhat kyynärää ja antoi minun käydä veden poikki. Vettä oli nilkkoihin asti.',
        4: 'Hän mittasi tuhat ja antoi minun kävellä veden poikki: vettä oli polviin asti. Hän mittasi tuhat ja antoi minun kävellä poikki: vettä oli vyötäisille asti.',
        5: 'Ja hän mittasi tuhat. Tuli virta, jota en voinut ylittää. Sillä vesi nousi uimavedeksi, virraksi, jonka yli ei pääse.',
        6: 'Hän kysyi minulta: "Oletko nähnyt, ihmislapsi?" Ja hän kuljetti minua ja toi takaisin virran rannalle.',
        7: 'Mutta kun tulin takaisin, katso: virran rannalla oli hyvin paljon puita molemmilla puolin.',
        8: 'Hän sanoi minulle: "Nämä vedet juoksevat itäiselle alueelle, virtaavat alas Aromaahan ja tulevat mereen. Niiden tultua mereen vesi siinä paranee.',
        9: 'Kaikki elolliset, kaikki, jotka liikkuvat, virkoavat elämään kaikkialla, mihin tämä kaksoisvirta tulee. Kaloja on oleva hyvin paljon. Sillä kun nämä vedet tulevat sinne ja vesi paranee, niin kaikki virkoaa elämään, minne vain virta tulee.',
        10: 'Kalastajia seisoo sen rannalla. Een-Gedistä Een-Eglaimiin asti he levittävät verkkojaan. Siinä on kaikenlaisia kaloja, aivan kuin suuren meren kaloja, hyvin paljon.',
        11: 'Sen suot ja lammikot eivät parane. Ne jätetään suolan valtaan.',
        12: 'Mutta virran varrella, sen molemmilla rannoilla, kasvaa kaikenlaisia hedelmäpuita. Niistä eivät lehdet lakastu eivätkä hedelmät lopu. Joka kuukausi ne kantavat tuoreet hedelmät, sillä niiden vedet juoksevat pyhäköstä, ja niiden hedelmät ovat ravitsevia ja niiden lehdet parantavia.',
        13: 'Näin sanoo Herra, Herra: Tämä on raja, jonka mukaan teidän on jaettava maa perintöosiksi kahdelletoista Israelin sukukunnalle – Joosef saakoon kaksi osaa.',
        14: 'Te saatte siitä perintöosan jokainen kohdaltaan. Sillä olen kättä kohottaen luvannut antaa sen teidän isillenne, ja niin tämä maa tulee teille perintöosaksi.',
        15: 'Tämä on maan pohjoisraja: Suuresta merestä Hetlonin tietä siihen asti, mistä mennään Sedadiin.',
        16: 'Hamat, Beerota, Sibraim, joka on Damaskon alueen ja Hamatin alueen välissä, keskimmäinen Haaser, joka on Hauranin rajalla;',
        17: 'ja näin menee raja merestä Hasar-Eenoniin – Damaskon alue jää siitä pohjoiseen ja pohjoiseen siitä jää myös Hamatin alue. Tämä on pohjoispuoli.',
        18: 'Itäpuoli: Hauranin ja Damaskon välistä sekä Gileadin ja Israelin maan välistä, Jordania pitkin. Mitatkaa se rajasta itäiseen mereen. Tämä on itäpuoli.',
        19: 'Eteläpuoli, etelään päin: Taamarista Meriban veteen, joka on Kaadeksessa, virtaan, joka laskee Suureen mereen. Tämä on eteläpuoli, etelään päin.',
        20: 'Meren puoli: Suuri meri rajasta sen paikan kohdalle, mistä mennään Hamatiin. Tämä on meren puoli.',
        21: 'Jakakaa tämä maa keskenänne Israelin sukukuntien mukaan.',
        22: 'Arpokaa se perintöosiksi itsellenne ja muukalaisille, jotka asuvat muukalaisina keskuudessanne ja ovat synnyttäneet lapsia keskuudessanne. Olkoot he keskuudessanne samanarvoisia israelilaisten kanssa. He saakoot arvalla perintöosan Israelin sukukuntien keskuudessa.',
        23: 'Missä sukukunnassa muukalainen asuu, siinä antakaa hänelle perintöosa, sanoo Herra, Herra."',
    },
    48: {
        1: '"Nämä ovat sukukuntien nimet: Pohjoisreunalta Hetlonista Hamatiin johtavaa tietä, ja siitä Hasar-Eenamiin Damaskon alueen jäädessä siitä pohjoiseen Hamatin sivulle. Tämä on Daanille idästä länteen asti tuleva osuus.',
        2: 'Daanin alueen ollessa rajana idästä länteen asti tulee Asserille yksi osuus.',
        3: 'Asserin alueen ollessa rajana idästä länteen asti tulee Naftalille yksi osuus.',
        4: 'Naftalin alueen ollessa rajana idästä länteen asti tulee Manasselle yksi osuus.',
        5: 'Manassen alueen ollessa rajana idästä länteen asti tulee Efraimille yksi osuus.',
        6: 'Efraimin alueen ollessa rajana idästä länteen asti tulee Ruubenille yksi osuus.',
        7: 'Ruubenin alueen ollessa rajana idästä länteen asti tulee Juudalle yksi osuus.',
        8: 'Juudan alueen ollessa rajana idästä länteen asti on oleva se lahjoitusmaa, joka teidän on annettava, kaksikymmentäviisi tuhatta kyynärää leveä ja niin pitkä kuin on yksi sukukunnan osa idästä länteen, ja pyhäkkö olkoon sen keskellä.',
        9: 'Lahjoitusmaa, joka teidän on annettava Herralle, olkoon kaksikymmentäviisi tuhatta pitkä ja kaksikymmentä tuhatta leveä.',
        10: 'Pyhää lahjoitusmaata tulkoon seuraaville: papeille pohjoisesta kaksikymmentäviisi tuhatta, lännestä kymmenentuhatta leveälti, idästä kymmenentuhatta leveälti ja etelästä kaksikymmentäviisi tuhatta pitkälti, ja Herran pyhäkkö olkoon siinä keskellä.',
        11: 'Papeille, niille Saadokin jälkeläisistä, jotka ovat pyhitettyjä, jotka ovat hoitaneet minulle suoritettavat tehtävät ja jotka eivät eksyneet, niin kuin leeviläiset eksyivät, silloin kun israelilaiset joutuivat eksyksiin,',
        12: 'heille se tulkoon verona lahjoitusmaasta, korkeasti pyhänä; tulkoon se leeviläisten alueen vierestä.',
        13: 'Leeviläiset saakoot samanlaisen alueen kuin papit, kaksikymmentäviisi tuhatta pitkän ja kymmenentuhatta leveän. Koko pituus olkoon kaksikymmentäviisi tuhatta ja leveys kaksikymmentä tuhatta.',
        14: 'Älkööt he myykö siitä mitään, älköönkä maan ensi hedelmää vaihdettako tai luovutettako, sillä se on pyhitetty Herralle.',
        15: 'Mutta viisituhatta leveä maa, mikä jää yli kahdenkymmenenviiden tuhannen sivusta, on kaupungin yhteisomaisuutta asumuksia ja avointa tilaa varten, ja kaupunki olkoon sen keskellä.',
        16: 'Nämä olkoot sen mitat: pohjoispuoli neljätuhatta viisisataa, eteläpuoli neljätuhatta viisisataa, itäpuoli neljätuhatta viisisataa ja länsipuoli neljätuhatta viisisataa.',
        17: 'Kaupungilla olkoon avoin tila: pohjoiseen kaksisataa viisikymmentä, etelään kaksisataa viisikymmentä, itään kaksisataa viisikymmentä ja länteen kaksisataa viisikymmentä.',
        18: 'Mutta niin pitkälti kuin jää pyhän lahjoitusmaan viereltä yli, kymmenentuhatta itään ja kymmenen tuhatta länteen, se olkoon pyhän lahjoitusmaan vierellä, ja sen sato tulkoon leiväksi kaupungin työmiehille,',
        19: 'ja sitä viljelkööt kaupungin työmiehet kaikista Israelin sukukunnista.',
        20: 'Koko lahjoitusmaa on kaksikymmentäviisi tuhatta ja kaksikymmentäviisi tuhatta. Neliönmuotoisena on teidän annettava pyhä lahjoitusmaa sekä kaupungin perintömaa.',
        21: 'Mikä jää yli, se tulkoon ruhtinaalle: molemmilta puolilta pyhää lahjoitusmaata ja kaupungin perintömaata, niiden kahdenkymmenenviiden tuhannen – lahjoitusmaan – sivusta itärajaan asti, sekä länteen päin niiden kahdenkymmenenviiden tuhannen sivusta länsirajaan asti, on ruhtinaalle tuleva sukukuntaosia vastaava maa. Pyhä lahjoitusmaa sekä temppelipyhäkkö olkoot sen keskellä.',
        22: 'Leeviläisten perintömaasta ja kaupungin perintömaasta asti, jotka ovat ruhtinaalle tulevan maan keskellä, tulee ruhtinaalle se, mikä on Juudan alueen ja Benjaminin alueen välissä.',
        23: 'Muut sukukunnat: Idästä länteen asti Benjaminille tulee yksi osuus.',
        24: 'Benjaminin alueen ollessa rajana idästä länteen asti tulee Simeonille yksi osuus.',
        25: 'Simeonin alueen ollessa rajana idästä länteen asti tulee Isaskarille yksi osuus.',
        26: 'Isaskarin alueen ollessa rajana idästä länteen asti tulee Sebulonille yksi osuus.',
        27: 'Sebulonin alueen ollessa rajana idästä länteen asti tulee Gaadille yksi osuus.',
        28: 'Gaadin alueen eteläraja menee Taamarista Meriban veteen, Kaadekseen, Egyptin puroon ja Suureen mereen.',
        29: 'Tämä on maa, joka teidän on arvottava perintöosiksi Israelin sukukunnille, ja nämä ovat heidän osuutensa, sanoo Herra, Herra.',
        30: 'Nämä ovat kaupungin uloskäytävät: Pohjoispuolella on mitta neljätuhatta viisisataa.',
        31: 'Kaupungin portteja, jotka ovat nimitetyt Israelin sukukuntien mukaan, on pohjoisessa kolme: Ruubenin portti yksi, Juudan portti toinen ja Leevin portti kolmas.',
        32: 'Itäpuolella: neljätuhatta viisisataa, ja portteja kolme: Joosefin portti yksi, Benjaminin portti toinen ja Daanin portti kolmas.',
        33: 'Eteläpuolella on mitta neljätuhatta viisisataa, ja portteja kolme: Simeonin portti yksi, Isaskarin portti toinen ja Sebulonin portti kolmas.',
        34: 'Länsipuolella: neljätuhatta viisisataa, ja portteja kolme: Gaadin portti yksi, Asserin portti toinen ja Naftalin portti kolmas.',
        35: 'Ympärysmitta on kahdeksantoista tuhatta. Kaupungin nimi on tästedes oleva: Herra on täällä."',
    },
}
